    return f"""
        QMainWindow, QWidget {{
            background: {token["shell_bg_1"]};
            color: {token["text"]};
            font-family: "Microsoft YaHei UI", "Microsoft YaHei", "Segoe UI", "PingFang SC", "Source Han Sans SC", sans-serif;
            font-size: 13px;
        }}
        QTabWidget::pane {{
            border: 1px solid {token["border"]};
            border-radius: 18px;
            background: {token["panel_0"]};
            top: -1px;
        }}
        QTabBar::tab {{
            background: {token["tab_bg"]};
            color: {token["tab_fg"]};
            border: 1px solid {token["border"]};
            padding: 10px 18px;
            margin-right: 6px;
            border-top-left-radius: 12px;
            border-top-right-radius: 12px;
            min-width: 108px;
            min-height: 22px;
        }}
        QTabBar::tab:hover {{
            border-color: {token["primary"]};
        }}
        QTabBar::tab:selected {{
            background: {token["tab_selected_bg"]};
            color: {token["tab_selected_fg"]};
            font-weight: 800;
        }}
        QGroupBox {{
            border: 1px solid {token["border"]};
            border-radius: 16px;
            margin-top: 14px;
            padding: 18px 14px 14px 14px;
            background: {token["panel_0"]};
            font-weight: 700;
        }}
        QGroupBox::title {{
            subcontrol-origin: margin;
            left: 12px;
            padding: 0 6px;
            color: {token["primary"]};
        }}
        QPushButton {{
            background: {token["accent_0"]};
            color: {token["button_accent_text"]};
            border: 1px solid {token["accent_1"]};
            border-radius: 12px;
            padding: 9px 16px;
            font-weight: 800;
        }}
        QPushButton:hover {{
            background: {token["accent_1"]};
            border-color: {token["primary"]};
        }}
        QPushButton:pressed {{
            background: {token["accent_0"]};
        }}
        QLineEdit,
        QComboBox,
        QListWidget,
        QTextEdit,
        QTableWidget {{
            background: {token["input_bg"]};
            color: {token["input_fg"]};
            border: 1px solid {token["border"]};
            border-radius: 12px;
            padding: 6px;
            selection-background-color: {token["selection"]};
            selection-color: {token["selection_text"]};
        }}
        QComboBox QAbstractItemView,
        QListWidget {{
            background: {token["input_bg"]};
            color: {token["text"]};
            selection-background-color: {token["selection"]};
            selection-color: {token["selection_text"]};
        }}
        QTableWidget {{
            gridline-color: {token["border"]};
            alternate-background-color: {token["panel_1"]};
        }}
        QHeaderView::section {{
            background: {token["panel_1"]};
            color: {token["tab_selected_fg"]};
            border: none;
            border-bottom: 1px solid {token["border"]};
            padding: 8px;
            font-weight: 700;
        }}
        QCheckBox {{
            spacing: 8px;
        }}
        QLabel#heroTitle {{
            color: {token["primary"]};
            font-size: 26px;
            font-weight: 800;
            padding: 6px 0;
        }}
        QLabel#heroSubtitle {{
            color: {token["text_soft"]};
            font-size: 14px;
            padding-bottom: 4px;
        }}
        QLabel#topBadge {{
            color: {token["primary"]};
            font-weight: 700;
            padding-right: 8px;
        }}
    """


