class OrderConfirmationDialog(QDialog):
    def __init__(
        self,
        profile: BrokerProfile,
        intents: list[OrderIntent],
        adapter: EastmoneyBrokerAdapter,
        parent: QWidget | None = None,
        *,
        holdings=None,
        cash_snapshot=None,
        recommendations=None,
        execution_summary: dict[str, object] | None = None,
        strategy_name: str = "",
        experiment_bridge: dict[str, str] | None = None,
        guard_notes: list[str] | None = None,
    ) -> None:
        super().__init__(parent)
        self.setWindowTitle("下单确认")
        self.resize(980, 560)
        self.strategy_name = str(strategy_name or "")
        self.experiment_bridge = dict(experiment_bridge or {})
        self.confirmation_holdings = holdings
        self.confirmation_cash_snapshot = cash_snapshot
        self.confirmation_recommendations = list(recommendations or [])
        guard_notes = list(guard_notes or [])

        layout = QVBoxLayout(self)

        env = adapter.diagnose_environment(profile)
        account_box = QGroupBox("账户核对")
        account_grid = QGridLayout(account_box)
        info_rows = [
            ("账户名称", profile.account_name or "-"),
            ("账户 ID", profile.account_id or "-"),
            ("策略 ID", profile.strategy_id or "-"),
            ("交易模式", DISPLAY_TEXT["mode"].get(profile.mode or "", profile.mode or "-")),
            ("桥接 Python", env.get("bridge_python") or "未配置"),
            ("SDK 模块", profile.sdk_module or "-"),
        ]
        for idx, (label, value) in enumerate(info_rows):
            row = idx // 2
            col = (idx % 2) * 2
            account_grid.addWidget(QLabel(f"{label}:"), row, col)
            account_grid.addWidget(QLabel(str(value)), row, col + 1)
        layout.addWidget(account_box)

        hint = QLabel(
            "请确认 account_id、token、strategy_id 以及桥接 Python 与实盘账户一致后再提交。"
        )
        hint.setWordWrap(True)
        layout.addWidget(hint)

        self.order_table = build_table(
            [
                "代码",
                "方向",
                "价格",
                "数量",
                "止损",
                "目标",
                "信号日期",
            ]
        )
        self.order_table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
        updates_enabled = self.order_table.updatesEnabled()
        self.order_table.setUpdatesEnabled(False)
        self.order_table.blockSignals(True)
        try:
            self.order_table.setRowCount(len(intents))
            for row_index, item in enumerate(intents):
                values = [
                    item.symbol,
                    DISPLAY_TEXT["action"].get(item.side, item.side),
                    f"{item.price:.3f}",
                    str(item.quantity),
                    f"{item.stop_price:.3f}",
                    f"{item.target_price:.3f}",
                    item.signal_date,
                ]
                for column, value in enumerate(values):
                    self.order_table.setItem(row_index, column, QTableWidgetItem(value))
        finally:
            self.order_table.blockSignals(False)
            self.order_table.setUpdatesEnabled(updates_enabled)
        layout.addWidget(self.order_table)

        footer = QHBoxLayout()
        self.confirm_checkbox = QCheckBox("我已核对账户与委托信息。")
        footer.addWidget(self.confirm_checkbox)
        footer.addStretch(1)
        self.submit_button = QPushButton("确认提交")
        self.submit_button.setEnabled(False)
        cancel_button = QPushButton("取消")
        footer.addWidget(self.submit_button)
        footer.addWidget(cancel_button)
        layout.addLayout(footer)

        self.confirm_checkbox.toggled.connect(self.submit_button.setEnabled)
        self.submit_button.clicked.connect(self.accept)
        cancel_button.clicked.connect(self.reject)

    @staticmethod
    def confirm(
        profile: BrokerProfile,
        intents: list[OrderIntent],
        adapter: EastmoneyBrokerAdapter,
        parent: QWidget | None = None,
    ) -> bool:
        dialog = OrderConfirmationDialog(profile, intents, adapter, parent)
        return dialog.exec() == QDialog.Accepted


def build_table(headers: list[str]) -> QTableWidget:
    table = QTableWidget(0, len(headers))
    table.setHorizontalHeaderLabels(headers)
    table.setSelectionBehavior(QAbstractItemView.SelectRows)
    table.setSelectionMode(QAbstractItemView.SingleSelection)
    table.setEditTriggers(QAbstractItemView.NoEditTriggers)
    table.verticalHeader().setVisible(False)
    table.setAlternatingRowColors(False)
    table.setShowGrid(False)
    table.setObjectName("terminalTable")
    table.setWordWrap(False)
    table.setTextElideMode(Qt.ElideRight)
    table.verticalHeader().setDefaultSectionSize(42)
    table.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
    table.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
    table.setVerticalScrollMode(QAbstractItemView.ScrollPerPixel)
    table.setHorizontalScrollMode(QAbstractItemView.ScrollPerPixel)
    table.setFrameShape(QFrame.NoFrame)
    table.setCornerButtonEnabled(False)
    table.horizontalHeader().setStretchLastSection(True)
    table.horizontalHeader().setDefaultAlignment(Qt.AlignCenter)
    table.horizontalHeader().setFixedHeight(46)
    return table


class BackgroundTaskSignals(QObject):
    succeeded = Signal(object)
    failed = Signal(str)
    progressed = Signal(object)
    finished = Signal()


class BackgroundTask(QRunnable):
    def __init__(self, fn, *, pass_progress_callback: bool = False) -> None:
        super().__init__()
        self.fn = fn
        self.pass_progress_callback = pass_progress_callback
        self.signals = BackgroundTaskSignals()
        self.setAutoDelete(False)

    def run(self) -> None:
        try:
            if self.pass_progress_callback:
                result = self.fn(self.signals.progressed.emit)
            else:
                result = self.fn()
        except Exception as exc:
            try:
                self.signals.failed.emit(str(exc))
            except RuntimeError:
                pass
        else:
            try:
                self.signals.succeeded.emit(result)
            except RuntimeError:
                pass
        finally:
            try:
                self.signals.finished.emit()
            except RuntimeError:
                pass


BACKGROUND_TASK_REGISTRY: list[BackgroundTask] = []


def build_quant_hunter_logo_pixmap(size: int = 72) -> QPixmap:
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.transparent)
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.Antialiasing)

    background = QLinearGradient(0, 0, size, size)
    background.setColorAt(0.0, QColor("#66e0a3"))
    background.setColorAt(0.58, QColor("#5fb3ff"))
    background.setColorAt(1.0, QColor("#7ed7ff"))
    painter.setPen(Qt.NoPen)
    painter.setBrush(background)
    painter.drawRoundedRect(0, 0, size, size, 22, 22)

    inner = QPainterPath()
    inner.addRoundedRect(8, 8, size - 16, size - 16, 16, 16)
    painter.fillPath(inner, QColor(11, 20, 31, 168))

    line_pen = QPen(QColor("#effaff"))
    line_pen.setWidth(4)
    line_pen.setCapStyle(Qt.RoundCap)
    line_pen.setJoinStyle(Qt.RoundJoin)
    painter.setPen(line_pen)
    signal = QPainterPath()
    signal.moveTo(size * 0.22, size * 0.66)
    signal.lineTo(size * 0.38, size * 0.52)
    signal.lineTo(size * 0.52, size * 0.58)
    signal.lineTo(size * 0.74, size * 0.34)
    painter.drawPath(signal)

    painter.setPen(Qt.NoPen)
    candle_color = QColor("#f8feff")
    accent_color = QColor("#9af7d2")
    for x, height, color in (
        (0.26, 0.18, candle_color),
        (0.46, 0.26, accent_color),
        (0.66, 0.34, candle_color),
    ):
        center_x = size * x
        bar_height = size * height
        top = size * 0.72 - bar_height
        painter.setBrush(color)
        painter.drawRoundedRect(center_x - 4, top, 8, bar_height, 4, 4)
        painter.drawRoundedRect(center_x - 1, top - 8, 2, bar_height + 16, 1, 1)

    painter.end()
    return pixmap


class StartupSplashWindow(QDialog):
    def __init__(self) -> None:
        super().__init__(None, Qt.SplashScreen | Qt.FramelessWindowHint | Qt.WindowStaysOnTopHint)
        self.setObjectName("startupSplashWindow")
        self.setModal(False)
        self.setAttribute(Qt.WA_DeleteOnClose, False)
        self.setAttribute(Qt.WA_TranslucentBackground, True)
        self.setFixedSize(780, 440)
        self._finish_pending = False
        self.owner_window: QWidget | None = None
        self._build_ui()
        self.set_progress(4, "正在点亮机构级交易终端...")

    def _build_stage_card(self, title: str, detail: str) -> tuple[QFrame, QLabel]:
        card = QFrame()
        card.setObjectName("startupStageCard")
        card.setProperty("stageState", "pending")
        layout = QVBoxLayout(card)
        layout.setContentsMargins(14, 12, 14, 12)
        layout.setSpacing(6)

        title_label = QLabel(title)
        title_label.setObjectName("startupStageTitle")
        detail_label = QLabel(detail)
        detail_label.setObjectName("startupStageDetail")
        detail_label.setWordWrap(True)
        status_label = QLabel("等待接入")
        status_label.setObjectName("startupStageStatus")
        status_label.setWordWrap(True)

        layout.addWidget(title_label)
        layout.addWidget(detail_label)
        layout.addStretch(1)
        layout.addWidget(status_label)
        return card, status_label

    def _set_stage_card_state(self, card: QFrame, label: QLabel, state: str, text: str) -> None:
        if card.property("stageState") != state:
            card.setProperty("stageState", state)
            style = card.style()
            if style is not None:
                style.unpolish(card)
                style.polish(card)
        label.setText(text)

    def _build_ui(self) -> None:
        root_layout = QVBoxLayout(self)
        root_layout.setContentsMargins(18, 18, 18, 18)
        root_layout.setSpacing(0)

        panel = QFrame()
        panel.setObjectName("startupSplashPanel")
        panel_layout = QVBoxLayout(panel)
        panel_layout.setContentsMargins(28, 24, 28, 22)
        panel_layout.setSpacing(18)

        panel_shadow = QGraphicsDropShadowEffect(panel)
        panel_shadow.setBlurRadius(42)
        panel_shadow.setOffset(0, 18)
        panel_shadow.setColor(QColor(0, 0, 0, 120))
        panel.setGraphicsEffect(panel_shadow)

        top_row = QHBoxLayout()
        top_row.setContentsMargins(0, 0, 0, 0)
        top_row.setSpacing(16)

        self.startup_loading_logo = QLabel()
        self.startup_loading_logo.setObjectName("startupLoadingLogo")
        self.startup_loading_logo.setAlignment(Qt.AlignCenter)
        self.startup_loading_logo.setFixedSize(68, 68)
        self.startup_loading_logo.setPixmap(build_quant_hunter_logo_pixmap(68))
        self.startup_loading_logo.setScaledContents(False)

        identity_layout = QVBoxLayout()
        identity_layout.setContentsMargins(0, 0, 0, 0)
        identity_layout.setSpacing(4)
