    def _fill_strategy_history_compare_table(self) -> None:
        table = getattr(self, "strategy_history_compare_table", None)
        rows = self._strategy_history_selected_compare_rows() if hasattr(self, "_strategy_history_selected_compare_rows") else []
        if table is None:
            return
        signature = tuple(
            (
                str(item.get("scenario_label", "") or ""),
                str(item.get("strategy_name", "") or ""),
                int(item.get("max_hold_days", 0) or 0),
                float(item.get("total_return", 0.0) or 0.0),
                float(item.get("win_rate", 0.0) or 0.0),
                float(item.get("max_drawdown", 0.0) or 0.0),
                float(item.get("profit_factor", 0.0) or 0.0),
                float(item.get("payoff_ratio", 0.0) or 0.0),
                int(item.get("max_consecutive_losses", 0) or 0),
                str(item.get("scenario_note", "") or ""),
            )
            for item in rows
        )
        if getattr(self, "_strategy_history_compare_signature", None) == signature:
            return
        updates_enabled = table.updatesEnabled()
        table.setUpdatesEnabled(False)
        table.blockSignals(True)
        try:
            table.setRowCount(len(rows))
            for row_index, item in enumerate(rows):
                values = [
                    str(item.get("scenario_label", "") or "--"),
                    str(item.get("strategy_name", "") or "--"),
                    f"{int(item.get('max_hold_days', 0) or 0)} 天",
                    f"{float(item.get('total_return', 0.0) or 0.0):.2%}",
                    f"{float(item.get('win_rate', 0.0) or 0.0):.2%}",
                    f"{float(item.get('max_drawdown', 0.0) or 0.0):.2%}",
                    f"{float(item.get('profit_factor', 0.0) or 0.0):.2f}",
                    f"{float(item.get('payoff_ratio', 0.0) or 0.0):.2f}",
                    str(int(item.get("max_consecutive_losses", 0) or 0)),
                    str(item.get("scenario_note", "") or "--"),
                ]
                for column, value in enumerate(values):
                    table.setItem(row_index, column, QTableWidgetItem(value))
        finally:
            table.blockSignals(False)
            table.setUpdatesEnabled(updates_enabled)
        self._strategy_history_compare_signature = signature

    def _fill_strategy_history_trade_table(self) -> None:
        table = getattr(self, "strategy_history_trade_table", None)
        rows = self._strategy_history_selected_trades()
        if table is None:
            return
        signature = tuple(
            (
                str(item.get("strategy_name", "") or ""),
                str(item.get("stock_name", "") or item.get("symbol", "") or ""),
                str(item.get("signal_date", "") or ""),
                str(item.get("entry_date", "") or ""),
                str(item.get("exit_date", "") or ""),
                float(item.get("entry_price", 0.0) or 0.0),
                float(item.get("exit_price", 0.0) or 0.0),
                float(item.get("pnl_pct", 0.0) or 0.0),
                int(item.get("hold_days", 0) or 0),
                str(item.get("exit_reason", "") or ""),
            )
            for item in rows
        )
        if getattr(self, "_strategy_history_trade_table_signature", None) == signature:
            return
        updates_enabled = table.updatesEnabled()
        table.setUpdatesEnabled(False)
        table.blockSignals(True)
        try:
            table.setRowCount(len(rows))
            for row_index, item in enumerate(rows):
                values = [
                    str(item.get("strategy_name", "") or "--"),
                    str(item.get("stock_name", "") or item.get("symbol", "") or "--"),
                    str(item.get("signal_date", "") or "--"),
                    str(item.get("entry_date", "") or "--"),
                    str(item.get("exit_date", "") or "--"),
                    f"{float(item.get('entry_price', 0.0) or 0.0):.4f}",
                    f"{float(item.get('exit_price', 0.0) or 0.0):.4f}",
                    f"{float(item.get('pnl_pct', 0.0) or 0.0):.2%}",
                    str(int(item.get("hold_days", 0) or 0)),
                    str(item.get("exit_reason", "") or "--"),
                ]
                for column, value in enumerate(values):
                    table.setItem(row_index, column, QTableWidgetItem(value))
        finally:
            table.blockSignals(False)
            table.setUpdatesEnabled(updates_enabled)
        self._strategy_history_trade_table_signature = signature
        if rows:
            table.selectRow(0)

    def _fill_strategy_history_period_tables(self) -> None:
        yearly_table = getattr(self, "strategy_history_yearly_table", None)
        monthly_table = getattr(self, "strategy_history_monthly_table", None)
        heatmap_table = getattr(self, "strategy_history_heatmap_table", None)
        yearly_rows = self._strategy_history_selected_yearly_rows()
        monthly_rows = self._strategy_history_selected_monthly_rows()

        if yearly_table is not None:
            yearly_signature = tuple(
                (
                    str(item.get("strategy_name", "") or ""),
                    str(item.get("period", "") or ""),
                    int(item.get("trade_count", 0) or 0),
                    float(item.get("win_rate", 0.0) or 0.0),
                    float(item.get("total_return", 0.0) or 0.0),
                    float(item.get("avg_return", 0.0) or 0.0),
                )
                for item in yearly_rows
            )
            if getattr(self, "_strategy_history_yearly_signature", None) != yearly_signature:
                updates_enabled = yearly_table.updatesEnabled()
                yearly_table.setUpdatesEnabled(False)
                yearly_table.blockSignals(True)
                try:
                    yearly_table.setRowCount(len(yearly_rows))
                    for row_index, item in enumerate(yearly_rows):
                        values = [
                            str(item.get("strategy_name", "") or "--"),
                            str(item.get("period", "") or "--"),
                            str(int(item.get("trade_count", 0) or 0)),
                            f"{float(item.get('win_rate', 0.0) or 0.0):.2%}",
                            f"{float(item.get('total_return', 0.0) or 0.0):.2%}",
                            f"{float(item.get('avg_return', 0.0) or 0.0):.2%}",
                        ]
                        for column, value in enumerate(values):
                            yearly_table.setItem(row_index, column, QTableWidgetItem(value))
                finally:
                    yearly_table.blockSignals(False)
                    yearly_table.setUpdatesEnabled(updates_enabled)
                self._strategy_history_yearly_signature = yearly_signature

        if monthly_table is not None:
            monthly_signature = tuple(
                (
                    str(item.get("strategy_name", "") or ""),
                    str(item.get("period", "") or ""),
                    int(item.get("trade_count", 0) or 0),
                    float(item.get("win_rate", 0.0) or 0.0),
                    float(item.get("total_return", 0.0) or 0.0),
                    float(item.get("avg_return", 0.0) or 0.0),
                )
                for item in monthly_rows
            )
            if getattr(self, "_strategy_history_monthly_signature", None) != monthly_signature:
                updates_enabled = monthly_table.updatesEnabled()
                monthly_table.setUpdatesEnabled(False)
                monthly_table.blockSignals(True)
                try:
                    monthly_table.setRowCount(len(monthly_rows))
                    for row_index, item in enumerate(monthly_rows):
                        values = [
                            str(item.get("strategy_name", "") or "--"),
                            str(item.get("period", "") or "--"),
                            str(int(item.get("trade_count", 0) or 0)),
                            f"{float(item.get('win_rate', 0.0) or 0.0):.2%}",
                            f"{float(item.get('total_return', 0.0) or 0.0):.2%}",
                            f"{float(item.get('avg_return', 0.0) or 0.0):.2%}",
                        ]
                        for column, value in enumerate(values):
                            monthly_table.setItem(row_index, column, QTableWidgetItem(value))
                finally:
                    monthly_table.blockSignals(False)
                    monthly_table.setUpdatesEnabled(updates_enabled)
                self._strategy_history_monthly_signature = monthly_signature

        if heatmap_table is not None:
            heatmap_map: dict[tuple[str, str], dict[str, str]] = {}
            for item in monthly_rows:
                strategy_name = str(item.get("strategy_name", "") or "--")
                period = str(item.get("period", "") or "")
                year, _sep, month = period.partition("-")
                if not year or not month:
                    continue
                bucket = heatmap_map.setdefault((strategy_name, year), {})
                bucket[month] = f"{float(item.get('total_return', 0.0) or 0.0):.1%}"
            heatmap_rows = sorted(heatmap_map.items(), key=lambda item: (item[0][0], item[0][1]))
            heatmap_signature = tuple(
                (
                    strategy_name,
                    year,
                    *tuple(month_values.get(f"{month:02d}", "--") for month in range(1, 13)),
                )
                for (strategy_name, year), month_values in heatmap_rows
            )
            if getattr(self, "_strategy_history_heatmap_signature", None) != heatmap_signature:
                updates_enabled = heatmap_table.updatesEnabled()
                heatmap_table.setUpdatesEnabled(False)
                heatmap_table.blockSignals(True)
                try:
                    heatmap_table.setRowCount(len(heatmap_rows))
                    for row_index, ((strategy_name, year), month_values) in enumerate(heatmap_rows):
                        values = [strategy_name, year] + [month_values.get(f"{month:02d}", "--") for month in range(1, 13)]
                        for column, value in enumerate(values):
                            heatmap_table.setItem(row_index, column, QTableWidgetItem(value))
                finally:
                    heatmap_table.blockSignals(False)
                    heatmap_table.setUpdatesEnabled(updates_enabled)
                self._strategy_history_heatmap_signature = heatmap_signature

    def _render_strategy_history_curve(self) -> None:
        view = getattr(self, "strategy_history_curve_view", None)
        report = getattr(self, "strategy_history_report", None)
        if view is None:
            return
        chart = QChart()
        chart.legend().hide()
        chart.setTitle("历史战法收益曲线")
        if report is None:
            view.setChart(chart)
            return
        selected_strategy = self._selected_strategy_history_name() if hasattr(self, "_selected_strategy_history_name") else ""
        points = [
            item
            for item in getattr(report, "equity_points", []) or []
            if not selected_strategy or getattr(item, "strategy_name", "") == selected_strategy
        ]
        series = QLineSeries()
        if points:
            chart.setTitle(f"历史战法收益曲线 - {selected_strategy or getattr(points[0], 'strategy_name', '全部战法')}")
            for index, item in enumerate(points):
                series.append(float(index), float(getattr(item, "equity", 1.0) or 1.0))
        else:
            series.append(0.0, 1.0)
        chart.addSeries(series)
        axis_x = QValueAxis()
        axis_x.setLabelFormat("%d")
        axis_x.setTitleText("成交序号")
        axis_y = QValueAxis()
        axis_y.setLabelFormat("%.2f")
        axis_y.setTitleText("净值")
        chart.addAxis(axis_x, Qt.AlignBottom)
        chart.addAxis(axis_y, Qt.AlignLeft)
        series.attachAxis(axis_x)
        series.attachAxis(axis_y)
        max_x = max(len(points) - 1, 1)
        axis_x.setRange(0, max_x)
        y_values = [float(getattr(item, "equity", 1.0) or 1.0) for item in points] or [1.0]
        y_min = min(y_values)
        y_max = max(y_values)
        padding = max((y_max - y_min) * 0.1, 0.05)
        axis_y.setRange(max(0.0, y_min - padding), y_max + padding)
        view.setChart(chart)

    def _apply_strategy_history_report(self, report) -> None:
        self.strategy_history_report = report
        self.strategy_history_rows = StrategyHistoryReplayer.report_as_table_rows(report)
        self.strategy_history_compare_rows = []
        self.strategy_history_leaderboard_rows = []
        self.strategy_history_trade_rows = StrategyHistoryReplayer.trade_as_table_rows(report)
        self.strategy_history_yearly_rows = [item.__dict__ for item in getattr(report, "yearly_stats", [])]
        self.strategy_history_monthly_rows = [item.__dict__ for item in getattr(report, "monthly_stats", [])]
        self._fill_strategy_history_table()
        self._fill_strategy_history_leaderboard_table()
        self._fill_strategy_history_compare_table()
        self._fill_strategy_history_period_tables()
        self._render_strategy_history_curve()
        self._fill_strategy_history_trade_table()
        self._refresh_detail_workspace_panels()
        if hasattr(self, "active_symbol_label"):
            current_text = self.active_symbol_label.text() if hasattr(self.active_symbol_label, "text") else "当前标的：未选择"
            suffix = f" | 历史战法 {len(getattr(report, 'summaries', []) or [])} 组"
            if suffix not in current_text:
                self._set_label_text_if_changed(self.active_symbol_label, current_text + suffix)

    def _handle_strategy_history_error(self, message: str) -> None:
        if hasattr(self, "metrics_text"):
            current = self.metrics_text.toPlainText().strip()
            text = f"{current}\n\n历史战法回测失败：{message}" if current else f"历史战法回测失败：{message}"
            self._set_plain_text_if_changed(self.metrics_text, text)
        QMessageBox.critical(self, "历史战法回测失败", message)

    def _apply_strategy_history_parameter_compare(self, rows) -> None:
        self.strategy_history_compare_rows = StrategyHistoryReplayer.comparison_as_table_rows(rows)
        self.strategy_history_leaderboard_rows = StrategyHistoryReplayer.leaderboard_as_table_rows(
            StrategyHistoryReplayer.comparison_leaderboard(rows)
        )
        self._fill_strategy_history_leaderboard_table()
        self._fill_strategy_history_compare_table()
        if hasattr(self, "metrics_text"):
            existing = self.metrics_text.toPlainText().strip()
            line = f"战法参数对比已完成：{len(self.strategy_history_compare_rows)} 条场景结果。"
            merged = f"{existing}\n\n{line}".strip() if existing else line
            self._set_plain_text_if_changed(self.metrics_text, merged)
        self._refresh_detail_workspace_panels()

    def run_strategy_history_backtest(self) -> None:
        runtime_params = self._strategy_history_runtime_params() if hasattr(self, "_strategy_history_runtime_params") else {
            "start_date": "2021-01-01",
            "end_date": "2099-12-31",
            "max_hold_days": 8,
            "include_watch_only": False,
        }
        if hasattr(self, "metrics_text"):
            self._set_plain_text_if_changed(
                self.metrics_text,
                "历史战法回测\n\n"
                f"正在按战法回放 {runtime_params['start_date']} 以来的每日荐股信号、计划买卖点与止盈止损，"
                f"最长持有 {runtime_params['max_hold_days']} 天，"
                f"滑点 {float(runtime_params['slippage_rate']):.4%}，手续费 {float(runtime_params['commission_rate']):.4%}，"
                f"印花税 {float(runtime_params['stamp_duty_rate']):.4%}，"
                f"{'纳入' if runtime_params['include_watch_only'] else '不纳入'}观察信号。"
                "计算的是规则化信号收益，不依赖真实下单记录，请稍候...",
            )

        def build_report():
            replayer = StrategyHistoryReplayer(
                params=StrategyHistoryReplayParams(
                    start_date=str(runtime_params["start_date"]),
                    end_date=str(runtime_params["end_date"]),
                    max_hold_days=int(runtime_params["max_hold_days"]),
                    slippage_rate=float(runtime_params["slippage_rate"]),
                    commission_rate=float(runtime_params["commission_rate"]),
                    stamp_duty_rate=float(runtime_params["stamp_duty_rate"]),
                    include_watch_only=bool(runtime_params["include_watch_only"]),
                    block_limit_up_entry=bool(runtime_params["block_limit_up_entry"]),
                    block_limit_down_exit=bool(runtime_params["block_limit_down_exit"]),
                )
            )
            return replayer.build_report(
                start_date=str(runtime_params["start_date"]),
                end_date=str(runtime_params["end_date"]),
                include_watch_only=bool(runtime_params["include_watch_only"]),
            )

        started = self._run_background_job(
            "strategy_history_backtest",
            build_report,
            self._apply_strategy_history_report,
            self._handle_strategy_history_error,
        )
        if not started and hasattr(self, "metrics_text"):
            current = self.metrics_text.toPlainText().strip()
            self._set_plain_text_if_changed(self.metrics_text, f"{current}\n\n历史战法回测仍在运行，请稍候。".strip())

    def run_strategy_history_parameter_compare(self) -> None:
        runtime_params = self._strategy_history_runtime_params() if hasattr(self, "_strategy_history_runtime_params") else {
            "start_date": "2021-01-01",
            "end_date": "2099-12-31",
            "max_hold_days": 8,
            "slippage_rate": 0.0005,
            "commission_rate": 0.0003,
            "stamp_duty_rate": 0.001,
            "include_watch_only": False,
            "block_limit_up_entry": True,
            "block_limit_down_exit": True,
        }
        if hasattr(self, "metrics_text"):
            self._set_plain_text_if_changed(
                self.metrics_text,
                "战法参数对比\n\n"
                f"正在基于 {runtime_params['start_date']} 以来的每日荐股信号，"
                "对同一批战法做多组参数场景回放，请稍候...",
            )

        def build_compare_rows():
            replayer = StrategyHistoryReplayer(
                params=StrategyHistoryReplayParams(
                    start_date=str(runtime_params["start_date"]),
                    end_date=str(runtime_params["end_date"]),
                    max_hold_days=int(runtime_params["max_hold_days"]),
                    slippage_rate=float(runtime_params["slippage_rate"]),
                    commission_rate=float(runtime_params["commission_rate"]),
                    stamp_duty_rate=float(runtime_params["stamp_duty_rate"]),
                    include_watch_only=bool(runtime_params["include_watch_only"]),
                    block_limit_up_entry=bool(runtime_params["block_limit_up_entry"]),
                    block_limit_down_exit=bool(runtime_params["block_limit_down_exit"]),
                )
            )
            return replayer.compare_parameter_scenarios(
                start_date=str(runtime_params["start_date"]),
                end_date=str(runtime_params["end_date"]),
                include_watch_only=bool(runtime_params["include_watch_only"]),
            )

        started = self._run_background_job(
            "strategy_history_parameter_compare",
            build_compare_rows,
            self._apply_strategy_history_parameter_compare,
            self._handle_strategy_history_error,
        )
        if not started and hasattr(self, "metrics_text"):
            current = self.metrics_text.toPlainText().strip()
            self._set_plain_text_if_changed(self.metrics_text, f"{current}\n\n战法参数对比仍在运行，请稍候。".strip())

    def export_strategy_history_report_from_ui(self, show_dialog: bool = True):
        report = getattr(self, "strategy_history_report", None)
        if report is None:
            if show_dialog:
                QMessageBox.information(self, "提示", "请先运行历史战法回测。")
            return None
        selected_strategy = self._selected_strategy_history_name() if hasattr(self, "_selected_strategy_history_name") else ""
        artifacts = export_strategy_history_report(
            report=report,
            output_dir=self._strategy_history_output_dir(),
            selected_strategy=selected_strategy,
            comparison_rows=list(getattr(self, "strategy_history_compare_rows", []) or []),
            leaderboard_rows=list(getattr(self, "strategy_history_leaderboard_rows", []) or []),
        )
        headline = "历史战法报表已导出："
        if selected_strategy:
            headline = f"历史战法报表已导出（{selected_strategy}）："
        export_lines = [
            headline,
            f"Markdown：{artifacts.markdown_path}",
            f"CSV：{artifacts.csv_path}",
            f"JSON：{artifacts.json_path}",
        ]
        if hasattr(self, "metrics_text"):
            existing = self.metrics_text.toPlainText().strip()
            merged = "\n".join([existing, "", *export_lines]) if existing else "\n".join(export_lines)
            self._set_plain_text_if_changed(self.metrics_text, merged)
        if show_dialog:
            QMessageBox.information(self, "导出完成", "\n".join(export_lines))
        return artifacts

    def load_single_csv(self) -> None:
        path, _ = QFileDialog.getOpenFileName(self, "选择行情 CSV", str(PROJECT_ROOT), "CSV 文件 (*.csv);;所有文件 (*)")
        if not path:
            return
        bars = load_bars_from_csv(path)
        analyses = AntiHarvestStrategy(self.strategy_params()).analyze(bars)
        symbol = bars[-1].symbol
        self.universe_bars[symbol] = bars
        self.universe_analyses[symbol] = analyses
        self.paths_by_symbol[symbol] = Path(path)
        self.select_symbol(symbol)

    def _refresh_signal_panel(self) -> None:
        rows = [row for row in self.analyses if row.label != "NONE"][-20:]
        selected_signal = self._selected_detail_signal_snapshot()
        signal_signature = tuple(
            (
                item.date,
                self._display_label(item.label),
                str(item.score),
                f"{item.close:.2f}",
                item.reason,
            )
            for item in rows
        )
        if getattr(self, "_signal_table_signature", None) != signal_signature:
            updates_enabled = self.signal_table.updatesEnabled()
            self.signal_table.setUpdatesEnabled(False)
            self.signal_table.blockSignals(True)
            try:
                self.signal_table.setRowCount(len(rows))
                for row_index, row_values in enumerate(signal_signature):
                    for column, value in enumerate(row_values):
                        self.signal_table.setItem(row_index, column, QTableWidgetItem(value))
            finally:
                self.signal_table.blockSignals(False)
                self.signal_table.setUpdatesEnabled(updates_enabled)
            self._signal_table_signature = signal_signature
        if rows:
            target_row = next(
                (
                    index
                    for index, row in enumerate(rows)
                    if selected_signal
                    and row.date == selected_signal.get("date", "")
                    and self._display_label(row.label) == selected_signal.get("label", "")
                ),
                0,
            )
            self.signal_table.selectRow(target_row)

    def run_backtest_for_active(self, quiet: bool = False) -> None:
        if not self.bars or not self.analyses:
            if not quiet:
                QMessageBox.information(self, "提示", "请先选择一个标的。")
            return
        result = Backtester(strategy_params=self.strategy_params()).run(self.bars, self.analyses)
        self.last_backtest_result = result
        latest_signal = next((item for item in reversed(self.analyses) if item.label != "NONE"), None)
        if latest_signal is None:
            latest_note = "最近 K 线中暂无有效信号。"
        else:
            latest_note = (
                f"最新信号：{latest_signal.date} | {self._display_label(latest_signal.label)} | 评分 {latest_signal.score}\n"
                f"{latest_signal.reason}"
            )
        source_path = self.paths_by_symbol.get(self.active_symbol)
        self._set_plain_text_if_changed(
            self.metrics_text,
            (
                f"{latest_note}\n"
                f"数据文件：{source_path}\n\n"
                f"{format_result(result)}\n\n"
                "说明：\n"
                "- 回测默认使用下一交易日开盘附近成交的日线近似。\n"
                "- 适合做研究、排序和半自动执行前检查。\n"
            )
        )
        selected_trade = self._selected_detail_trade_snapshot()
        trade_signature = tuple(
            (
                trade.entry_date,
                trade.exit_date,
                str(trade.entry_price),
                str(trade.exit_price),
                str(trade.shares),
                str(trade.pnl),
                trade.exit_reason,
            )
            for trade in result.trades
        )
        if getattr(self, "_trades_table_signature", None) != trade_signature:
            updates_enabled = self.trades_table.updatesEnabled()
            self.trades_table.setUpdatesEnabled(False)
            self.trades_table.blockSignals(True)
            try:
                self.trades_table.setRowCount(len(result.trades))
                for row_index, row_values in enumerate(trade_signature):
                    for column, value in enumerate(row_values):
                        self.trades_table.setItem(row_index, column, QTableWidgetItem(value))
            finally:
                self.trades_table.blockSignals(False)
                self.trades_table.setUpdatesEnabled(updates_enabled)
            self._trades_table_signature = trade_signature
        if result.trades:
            target_row = next(
                (
                    index
                    for index, trade in enumerate(result.trades)
                    if selected_trade
                    and trade.entry_date == selected_trade.get("entry_date", "")
                    and trade.exit_date == selected_trade.get("exit_date", "")
                    and str(trade.entry_price) == selected_trade.get("entry_price", "")
                ),
                0,
            )
            self.trades_table.selectRow(target_row)
        self._refresh_detail_workspace_panels()


    def export_workspace_report_from_ui(self) -> None:
        if not self.scan_rows:
            QMessageBox.information(self, "提示", "请先完成股票池扫描。")
            return
        artifacts = export_workspace_report(self.scan_rows, self.backtest_summaries, REPORT_DIR)
        self._set_plain_text_if_changed(
            self.optimization_text,
            "\n".join(
                [
                    "工作台报告已导出。",
                    f"Markdown：{artifacts.markdown_path}",
                    f"CSV：{artifacts.csv_path}",
                    f"JSON：{artifacts.json_path}",
                ]
            )
        )

    def choose_export_dir(self) -> None:
        folder = QFileDialog.getExistingDirectory(self, "选择导出目录")
        if folder:
            self.broker_inputs["export_dir"].setText(folder)

    def save_profile(self) -> None:
        self._sync_shared_broker_fields("broker")
        self.state.broker_profile = self.current_broker_profile()
        self.save_state()
        self._refresh_broker_status()
        self._refresh_login_status()
        QMessageBox.information(self, "提示", "账户配置已保存。")

    def validate_broker_connection(self) -> None:
        validate_broker_connection_controller(
            self,
            adapter_cls=EastmoneyBrokerAdapter,
            info_dialog_fn=QMessageBox.information,
            warning_dialog_fn=QMessageBox.warning,
        )

    def create_broker_templates(self) -> None:
        files = EastmoneyBrokerAdapter().create_templates(self.current_broker_profile().export_dir)
        self._refresh_broker_status(extra="\n".join(f"已生成模板：{item}" for item in files))

    def import_holdings_csv(self) -> None:
        path, _ = QFileDialog.getOpenFileName(self, "选择持仓 CSV", str(PROJECT_ROOT), "CSV 文件 (*.csv);;所有文件 (*)")
        if not path:
            return
        self.holdings = load_holdings_from_csv(path)
        self._fill_holdings()

    def import_cash_csv(self) -> None:
        path, _ = QFileDialog.getOpenFileName(self, "选择资金 CSV", str(PROJECT_ROOT), "CSV 文件 (*.csv);;所有文件 (*)")
        if not path:
            return
        self.cash_snapshot = load_cash_snapshot_from_csv(path)
        self._refresh_broker_status()

    def _fill_holdings(self) -> None:
        fill_holdings_table(self)

    def generate_order_suggestions(self) -> None:
        if not self.scan_rows:
            QMessageBox.information(self, "提示", "请先完成股票池扫描。")
            return
        try:
            per_trade_budget = float(self.per_trade_budget_input.text().strip())
        except ValueError:
            QMessageBox.critical(self, "参数错误", "单笔预算必须填写数字。")
            return
        rows = self.scan_rows if not self.state.watchlist else [row for row in self.scan_rows if row.symbol in self.state.watchlist]
        self.order_intents = EastmoneyBrokerAdapter().build_order_intents(rows, per_trade_budget)
        self._fill_orders()
        if not self.order_intents:
            self._refresh_broker_status(extra="当前参数下暂无新的买入建议。")

    def _fill_orders(self) -> None:
        fill_order_intents_table(self)

    def export_order_plan(self) -> None:
        if not self.order_intents:
            self.generate_order_suggestions()
        if not self.order_intents:
            return
        output = EastmoneyBrokerAdapter().export_order_plan(
            self.order_intents,
            self.current_broker_profile().export_dir,
            recommendations=getattr(self, "daily_pool_rows", []),
            execution_summary=getattr(self, "last_broker_execution_summary", {}) or {},
        )
        self._append_order_result(f"[{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] 已导出委托计划：{output}")
        self._refresh_broker_status(extra=f"已导出委托计划：{output}")

    def export_order_result_log(self) -> None:
        if not self.order_submission_records:
            QMessageBox.information(self, "提示", "当前还没有可导出的提交记录。")
            return
        output = EastmoneyBrokerAdapter().export_submission_records(
            self.order_submission_records,
            self.current_broker_profile().export_dir,
            recommendations=getattr(self, "daily_pool_rows", []),
            execution_summary=getattr(self, "last_broker_execution_summary", {}) or {},
        )
        self._append_order_result(f"[{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] 已导出提交日志：{output}")
        self._refresh_broker_status(extra=f"已导出提交日志：{output}")

    def sync_broker_via_sdk(self, quiet: bool = False) -> None:
        profile = self.current_broker_profile()
        previous_holdings = list(getattr(self, "holdings", []) or [])
        try:
            cash, holdings = EastmoneyBrokerAdapter().sync_account_via_sdk(profile)
        except Exception as exc:
            if not quiet:
                QMessageBox.critical(self, "SDK 同步失败", str(exc))
            return
        try:
            execution_rows = EastmoneyBrokerAdapter().sync_execution_records_via_sdk(profile)
        except Exception:
            execution_rows = []
        self.cash_snapshot = cash
        self.holdings = holdings
        execution_notes: list[str] = []
        if execution_rows:
            merged_records, execution_notes = merge_submission_records_with_execution_records(
                list(getattr(self, "order_submission_records", []) or []),
                execution_rows,
            )
            self.order_submission_records = merged_records
        reconciled_records, reconciliation_notes = reconcile_submission_records_with_holdings(
            list(getattr(self, "order_submission_records", []) or []),
            previous_holdings,
            holdings,
        )
        if execution_notes or reconciliation_notes:
            self.order_submission_records = reconciled_records
            self.execution_status_by_symbol = {}
            for item in self.order_submission_records:
                symbol = str(item.get("symbol", "") or "")
                if not symbol:
                    continue
                order_status = str(item.get("order_status", "") or "").upper()
                fill_status = str(item.get("fill_status", "") or "").upper()
                if order_status == "FAILED" or fill_status == "REJECTED":
                    self.execution_status_by_symbol[symbol] = "提交失败"
                elif fill_status == "FILLED":
                    self.execution_status_by_symbol[symbol] = "已成交"
                elif fill_status in {"PARTIAL", "PART_FILLED", "PARTIALLY_FILLED"}:
                    self.execution_status_by_symbol[symbol] = "部分成交"
                elif order_status == "SUBMITTED":
                    self.execution_status_by_symbol[symbol] = "已提交"
        self._fill_holdings()
        if execution_notes or reconciliation_notes:
            self._refresh_submission_table()
            for note in [*execution_notes[:4], *reconciliation_notes[:4]]:
                self._append_order_result(f"[{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] {note}")
        self._refresh_broker_status(extra="已通过 SDK 同步资金和持仓。")

    def generate_sdk_strategy_script(self) -> None:
        if not self.order_intents:
            self.generate_order_suggestions()
        if not self.order_intents:
            return
        profile = self.current_broker_profile()
        if not profile.token or not profile.strategy_id or not profile.account_id:
            QMessageBox.critical(self, "字段缺失", "请先填写 token、strategy_id 和 account_id。")
            return
        path = EastmoneyBrokerAdapter().generate_gm_strategy_script(profile, self.order_intents, profile.export_dir)
        self._refresh_broker_status(extra=f"已生成 GM 实盘脚本：{path}")

    def confirm_and_submit_orders(self) -> None:
        if not self.order_intents:
            self.generate_order_suggestions()
        if not self.order_intents:
            return
        profile = self.current_broker_profile()
        adapter = EastmoneyBrokerAdapter()
        if not OrderConfirmationDialog.confirm(
            profile,
            self.order_intents,
            adapter,
            self,
            recommendations=getattr(self, "daily_pool_rows", []),
            execution_summary=getattr(self, "last_broker_execution_summary", {}) or {},
        ):
            return

        submit_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        try:
            results = adapter.submit_order_intents(profile, self.order_intents)
        except Exception as exc:
            fallback_path = adapter.export_order_plan(self.order_intents, profile.export_dir)
            failure_lines = [
                f"[{submit_time}] SDK 下单失败：{exc}",
                f"[{submit_time}] 已回退导出 CSV：{fallback_path}",
            ]
            for item in self.order_intents:
                self._append_submission_record(
                    timestamp=submit_time,
                    order_status="FAILED",
                    fill_status="REJECTED",
                    order_id="",
                    symbol=item.symbol,
                    side=item.side,
                    price=f"{item.price:.3f}",
                    quantity=str(item.quantity),
                    failure_reason=str(exc),
                    message=str(exc),
                )
            for line in failure_lines:
                self._append_order_result(line)
            self._refresh_broker_status(extra="\n".join(failure_lines))
            QMessageBox.warning(self, "下单失败", f"{exc}\n\n已回退导出 CSV：\n{fallback_path}")
            return

        success_lines = [f"[{submit_time}] SDK 下单完成：共 {len(results)} 笔"]
        success_lines.extend(f"[{submit_time}] {item}" for item in results)
        for item, result in zip(self.order_intents, results):
            self._append_submission_record(
                timestamp=submit_time,
                order_status="SUBMITTED",
                fill_status="PENDING",
                order_id="",
                symbol=item.symbol,
                side=item.side,
                price=f"{item.price:.3f}",
                quantity=str(item.quantity),
                failure_reason="",
                message=result,
            )
        for line in success_lines:
            self._append_order_result(line)
        self.sync_broker_via_sdk(quiet=True)
        self._refresh_broker_status(extra="\n".join(success_lines))
        QMessageBox.information(self, "下单完成", "\n".join(results))

    def _append_order_result(self, line: str) -> None:
        self.order_submission_log.append(line.rstrip())
        self.order_submission_log = self.order_submission_log[-200:]
        self._set_plain_text_if_changed(self.order_result_text, "\n".join(self.order_submission_log) + "\n")

    def _append_submission_record(
        self,
        timestamp: str,
        order_status: str,
        fill_status: str,
        order_id: str,
        symbol: str,
        side: str,
        price: str,
        quantity: str,
        failure_reason: str,
        message: str,
        *,
        planned_price: str = "",
        planned_quantity: str = "",
        planned_stop_price: str = "",
        planned_target_price: str = "",
        opportunity_tier: str = "",
        planned_risk_reward_ratio: str = "",
        portfolio_fit_score: str = "",
        diversification_score: str = "",
        concentration_penalty_score: str = "",
        fill_price: str = "",
        fill_quantity: str = "",
    ) -> None:
        self.order_submission_records.append(
            {
                "timestamp": timestamp,
                "order_status": order_status,
                "fill_status": fill_status,
                "order_id": str(order_id or ""),
                "symbol": symbol,
                "side": side,
                "price": price,
                "quantity": quantity,
                "failure_reason": failure_reason,
                "message": message,
                "planned_price": str(planned_price or ""),
                "planned_quantity": str(planned_quantity or ""),
                "planned_stop_price": str(planned_stop_price or ""),
                "planned_target_price": str(planned_target_price or ""),
                "opportunity_tier": str(opportunity_tier or ""),
                "planned_risk_reward_ratio": str(planned_risk_reward_ratio or ""),
                "portfolio_fit_score": str(portfolio_fit_score or ""),
                "diversification_score": str(diversification_score or ""),
                "concentration_penalty_score": str(concentration_penalty_score or ""),
                "fill_price": str(fill_price or ""),
                "fill_quantity": str(fill_quantity or ""),
            }
        )
        if symbol:
            normalized_fill_status = str(fill_status or "").upper()
            if order_status == "FAILED" or normalized_fill_status == "REJECTED":
                self.execution_status_by_symbol[symbol] = "提交失败"
            elif normalized_fill_status == "FILLED":
                self.execution_status_by_symbol[symbol] = "已成交"
            elif normalized_fill_status in {"PARTIAL", "PART_FILLED", "PARTIALLY_FILLED"}:
                self.execution_status_by_symbol[symbol] = "部分成交"
            elif order_status == "SUBMITTED":
                self.execution_status_by_symbol[symbol] = "已提交"
            event_title = (
                f"{self._stock_name_for_symbol(symbol)} 提交失败"
                if order_status == "FAILED" or normalized_fill_status == "REJECTED"
                else (f"{self._stock_name_for_symbol(symbol)} 已成交" if normalized_fill_status == "FILLED" else f"{self._stock_name_for_symbol(symbol)} 已提交")
            )
            event_level = "ERROR" if order_status == "FAILED" or normalized_fill_status == "REJECTED" else "SUCCESS"
            event_detail = f"{side} {quantity} 股 @ {price}"
            if portfolio_fit_score:
                event_detail = f"{event_detail} | 组合适配 {portfolio_fit_score}"
            if message:
                event_detail = f"{event_detail} | {message}"
            self._append_smart_message_event(
                category="trade",
                title=event_title,
                detail=event_detail,
                symbol=symbol,
                level=event_level,
                timestamp=timestamp.split(" ")[-1] if " " in timestamp else timestamp,
            )
        self.order_submission_records = self.order_submission_records[-500:]
        self._refresh_submission_table()

    def _refresh_submission_table(self) -> None:
        selected_timestamp = ""
        if not hasattr(self, "execution_table"):
            return
        records_signature = tuple(
            (
                item.get("timestamp", ""),
                item.get("order_status", ""),
                item.get("fill_status", ""),
                item.get("order_id", ""),
                item.get("symbol", ""),
                item.get("side", ""),
                item.get("planned_price", ""),
                item.get("planned_quantity", ""),
                item.get("price", ""),
                item.get("quantity", ""),
                item.get("fill_price", ""),
                item.get("fill_quantity", ""),
                item.get("failure_reason", ""),
                item.get("message", ""),
            )
            for item in self.order_submission_records
        )
        if getattr(self, "_execution_table_signature", None) == records_signature:
            self._refresh_submission_focus()
            return
        current_row = self.execution_table.currentRow()
        if 0 <= current_row < len(self.order_submission_records):
            selected_timestamp = str(self.order_submission_records[current_row].get("timestamp", "") or "")
        updates_enabled = self.execution_table.updatesEnabled()
        self.execution_table.setUpdatesEnabled(False)
        self.execution_table.blockSignals(True)
        try:
            self.execution_table.setRowCount(len(self.order_submission_records))
            for row_index, item in enumerate(self.order_submission_records):
                order_status = self._display_order_status(item.get("order_status", ""))
                fill_status = self._display_fill_status(item.get("fill_status", ""))
                symbol = str(item.get("symbol", "") or "")
                stock_name = self._stock_name_for_symbol(symbol) if symbol else "--"
                stock_id = self._stock_id_for_symbol(symbol) if symbol else "--"
                action_text = self._display_action(item.get("side", ""))
                snapshot = submission_table_snapshot_v2(
                    item,
                    stock_name=stock_name,
                    stock_id=stock_id,
                    action_text=action_text,
                    order_status_text=order_status,
                    fill_status_text=fill_status,
                )
                values = [
                    snapshot["timeline"],
                    order_status,
                    fill_status,
                    snapshot["focus"],
                    snapshot["action"],
                    snapshot["price_compare"],
                    snapshot["quantity_compare"],
                    snapshot["risk_badge"],
                    snapshot["message"],
                ]
                background, foreground = self._submission_colors(item)
                for column, value in enumerate(values):
                    table_item = QTableWidgetItem(value)
                    table_item.setData(Qt.UserRole + 77, value)
                    table_item.setBackground(background)
                    table_item.setForeground(foreground)
                    if column in {0, 3, 4, 8}:
                        table_item.setToolTip(snapshot["tooltip"])
                    if column == 0:
                        table_item.setTextAlignment(Qt.AlignLeft | Qt.AlignVCenter)
                    elif column in {5, 6}:
                        table_item.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                    else:
                        table_item.setTextAlignment(Qt.AlignCenter if column in {1, 2, 7} else (Qt.AlignLeft | Qt.AlignVCenter))
                    if column == 7:
                        badge_bg, badge_fg = submission_risk_badge_palette_v2(item)
                        table_item.setBackground(badge_bg)
                        table_item.setForeground(badge_fg)
                    self.execution_table.setItem(row_index, column, table_item)
        finally:
            self.execution_table.blockSignals(False)
            self.execution_table.setUpdatesEnabled(updates_enabled)
        self._execution_table_signature = records_signature
        if self.order_submission_records:
            target_row = next(
                (
                    index
                    for index, record in enumerate(self.order_submission_records)
                    if str(record.get("timestamp", "") or "") == selected_timestamp
                ),
                len(self.order_submission_records) - 1,
            )
            self.execution_table.selectRow(target_row)
        self._refresh_execution_table_selection_chrome()
        self._refresh_submission_focus()

    def _refresh_execution_table_selection_chrome(self) -> None:
        table = getattr(self, "execution_table", None)
        if not isinstance(table, QTableWidget):
            return
        current_row = table.currentRow()
        if current_row < 0 and table.rowCount() > 0:
            current_row = table.rowCount() - 1
        base_role = Qt.UserRole + 77
        for row in range(table.rowCount()):
            is_current = row == current_row
            for column in range(table.columnCount()):
                item = table.item(row, column)
                if item is None:
                    continue
                base_text = item.data(base_role)
                if base_text is None:
                    base_text = item.text()
                    item.setData(base_role, base_text)
                if column == 0:
                    marker = "\u25cf" if is_current else "\u25cb"
                    decorated = f"{marker} {base_text}"
                    if item.text() != decorated:
                        item.setText(decorated)
                elif item.text() != str(base_text):
                    item.setText(str(base_text))
                font = item.font()
                if font.bold() != is_current:
                    font.setBold(is_current)
                    item.setFont(font)
        if hasattr(table, "viewport"):
            table.viewport().update()

    def _selected_submission_record(self) -> dict[str, str] | None:
        if not hasattr(self, "execution_table") or not self.order_submission_records:
            return None
        row_index = self.execution_table.currentRow()
        if row_index < 0:
            return self.order_submission_records[-1]
        if row_index >= len(self.order_submission_records):
            return self.order_submission_records[-1]
        return self.order_submission_records[row_index]

    def _on_execution_selection_changed(self) -> None:
        self._refresh_submission_focus()

    def _refresh_submission_focus(self) -> None:
        record = self._selected_submission_record()
        if hasattr(self, "order_result_text"):
            if record is None:
                self._set_plain_text_if_changed(
                    self.order_result_text,
                    "执行回放\n\n"
                    "新的提交结果会按时间顺序沉淀在这里，包括订单状态、成交状态、失败原因和系统反馈。\n"
                    "刷新委托或提交模拟单后，这里会自动切换到最新一条。\n"
                    "你也可以先从推荐页或打板页送审候选，再回到这里看执行反馈。"
                )
            else:
                lines = [
                    "执行回放",
                    "",
                    f"时间：{record.get('timestamp', '--')}",
                    f"股票：{self._stock_name_for_symbol(record.get('symbol', ''))} ({self._stock_id_for_symbol(record.get('symbol', ''))} / {record.get('symbol', '--')})",
                    f"动作：{self._display_action(record.get('side', ''))} | 价格：{record.get('price', '--')} | 数量：{record.get('quantity', '--')}",
                    f"订单状态：{self._display_order_status(record.get('order_status', ''))}",
                    f"成交状态：{self._display_fill_status(record.get('fill_status', ''))}",
                    f"失败原因：{record.get('failure_reason', '') or '无'}",
                    f"反馈信息：{record.get('message', '') or '等待更多反馈'}",
                ]
                self._set_plain_text_if_changed(self.order_result_text, "\n".join(lines))
        if hasattr(self, "broker_recap_text"):
            if record is None:
                self._set_plain_text_if_changed(
                    self.broker_recap_text,
                    "成交回顾\n\n"
                    "提交后，这里会沉淀通过率、阻塞原因、成交偏差和回看要点。\n"
                    "当订单建议生成后，可以在这里快速检查执行质量。"
                )
            else:
                symbol = record.get("symbol", "")
                recommendation = next((item for item in getattr(self, "daily_pool_rows", []) if getattr(item, "symbol", "") == symbol), None)
                lines = [
                    f"成交回顾：{self._stock_name_for_symbol(symbol)}",
                    f"订单状态：{self._display_order_status(record.get('order_status', ''))} | 成交状态：{self._display_fill_status(record.get('fill_status', ''))}",
                    f"动作：{self._display_action(record.get('side', ''))} | 价格 {record.get('price', '--')} | 数量 {record.get('quantity', '--')}",
                ]
                if recommendation is not None:
                    lines.append(
                        f"主线参考：{getattr(recommendation, 'mainline_flow_signal', '') or '待确认'} / {getattr(recommendation, 'mainline_stage', '') or '待确认'}"
                    )
                    lines.append(f"推荐动作：{self._display_action(getattr(recommendation, 'action', ''))}")
                    lines.append(f"推荐理由：{getattr(recommendation, 'rationale', '') or '等待推荐逻辑生成。'}")
                message = record.get("message", "") or ""
                if message:
                    lines.append(f"系统反馈：{message}")
                failure_reason = record.get("failure_reason", "") or ""
                if failure_reason:
                    lines.append(f"需要处理：{failure_reason}")
                else:
                    lines.append("后续动作：可继续查看委托明细，或回到推荐页校验主线和仓位。")
                self._set_plain_text_if_changed(self.broker_recap_text, "\n".join(lines))

    def _signal_colors(self, action: str, label: str) -> tuple[QColor, QColor]:
        key = label or action
        if key == "RECLAIM_LONG" or action == "BUY":
            return QColor("#E8F7EC"), QColor("#0F5132")
        if key == "TRAP_DETECTED" or action == "AVOID":
            return QColor("#FBEAEA"), QColor("#842029")
        if key == "WATCH":
            return QColor("#FFF4DB"), QColor("#7C4A03")
        if key == "NONE" or action == "HOLD":
            return QColor("#F5F6F7"), QColor("#495057")
        return QColor("#F8F9FA"), QColor("#212529")

    def _submission_colors(self, item: dict[str, str]) -> tuple[QColor, QColor]:
        return shared_submission_colors(item)

    def _refresh_broker_status(self, extra: str = "") -> None:
        adapter = EastmoneyBrokerAdapter()
        profile = self.current_broker_profile()
        env = adapter.diagnose_environment(profile)
        market_value = sum(item.market_value for item in self.holdings)
        available = self.cash_snapshot.available_cash if self.cash_snapshot else 0.0
        total_assets = self.cash_snapshot.total_assets if self.cash_snapshot else market_value + available
        connected = (env["direct_ready"] or env["bridge_ready"]) and profile.mode == "sdk"
        note_lines = [
            "环境诊断",
            f"- 主程序 Python：{env['python_version']}",
            f"- 当前解释器 SDK：{'已安装' if env['module_installed'] else '未安装'} ({env['sdk_module']})",
        ]
        if env["bridge_python"]:
            note_lines.append(
                f"- 桥接解释器：{env['bridge_python']} | SDK {'已安装' if env['bridge_module_installed'] else '未安装'}"
            )
        if env["bridge_ready"]:
            note_lines.append("- 当前环境已满足桥接下单条件，可通过 Python 3.12 + GM SDK 调用。")
        elif env["direct_ready"]:
            note_lines.append("- 当前环境已满足直连 SDK 调用条件。")
        else:
            note_lines.append("- 当前环境暂未满足 SDK 下单条件，建议继续使用导出 CSV 或 GM 脚本。")
        content = [
            "网关：东方财富 / 掘金 GM",
            f"模式：{self._display_mode(profile.mode)}",
            f"连接状态：{'已就绪' if connected else '未就绪'}",
            "",
            "\n".join(note_lines),
            "",
            "账户概览",
            f"- 持仓证券数：{len(self.holdings)}",
            f"- 持仓市值：{market_value:,.2f}",
            f"- 可用资金：{available:,.2f}",
            f"- 总资产：{total_assets:,.2f}",
            "",
            f"委托建议数：{len(self.order_intents)}",
        ]
        if extra:
            content.extend(["", extra])
        self._set_plain_text_if_changed(self.broker_status_text, "\n".join(content))
        if hasattr(self, "broker_metric_labels"):
            readiness = "已就绪" if connected else ("桥接可用" if env["bridge_ready"] else "待配置")
            risk_count = sum(1 for item in self.order_intents if getattr(item, "side", "") in {"SELL", "REDUCE"})
            buy_count = sum(1 for item in self.order_intents if getattr(item, "side", "") == "BUY")
            buy_budget = sum(float(getattr(item, "price", 0.0) or 0.0) * float(getattr(item, "quantity", 0) or 0) for item in self.order_intents if getattr(item, "side", "") == "BUY")
            exposure = (buy_budget / available) if available > 0 else 0.0
            self.broker_metric_labels["readiness"].setText(readiness)
            self.broker_metric_accents["readiness"].setText("SDK 可下单" if connected else ("可桥接调用" if env["bridge_ready"] else "建议先导出/桥接"))
            self.broker_metric_labels["capital"].setText(f"{available:,.0f}")
            self.broker_metric_accents["capital"].setText(f"持仓市值 {market_value:,.0f}")
            self.broker_metric_labels["risk_reward"].setText(f"{buy_count} / {risk_count}")
            self.broker_metric_accents["risk_reward"].setText("买入候选 / 卖减建议")
            self.broker_metric_labels["risk_budget"].setText(f"{exposure:.0%}" if buy_budget > 0 else "0%")
            self.broker_metric_accents["risk_budget"].setText("预计买入力度")

    def _display_action(self, value: str) -> str:
        if value == "REDUCE":
            return "减仓"
        return DISPLAY_TEXT["action"].get(value, value)

    def _display_leader_level(self, value: str) -> str:
        return {
            "CORE_LEADER": "核心龙头",
            "ACTIVE_LEADER": "活跃龙头",
            "FOLLOWER": "跟风股",
            "NOISE": "噪声",
            "": "未分类",
        }.get(value, value)

    def _display_mainline_role(self, value: str) -> str:
        return {
            "CORE": "核心龙头",
            "FRONT": "前排核心",
            "ASSIST": "助攻前排",
            "FOLLOW": "跟风观察",
            "NOISE": "杂毛噪声",
            "ELIMINATED": "淘汰风险",
            "": "待确认",
        }.get(value, value)

    def _stock_profile_for_symbol(self, symbol: str) -> StockProfile | None:
        return self.stock_profiles.get(symbol)

    def _stock_name_for_symbol(self, symbol: str) -> str:
        profile = self._stock_profile_for_symbol(symbol)
        if profile and profile.name:
            return profile.name
        return extract_stock_id(symbol)

    def _stock_id_for_symbol(self, symbol: str) -> str:
        profile = self._stock_profile_for_symbol(symbol)
        if profile and profile.stock_id:
            return profile.stock_id
        return extract_stock_id(symbol)

    def _theme_for_symbol(self, symbol: str, recommendation=None) -> str:
        theme_name = ""
        if recommendation is not None:
            theme_name = getattr(recommendation, "mainline_tag", "") or getattr(recommendation, "theme_name", "")
        if not theme_name:
            profile = self._stock_profile_for_symbol(symbol)
            theme_name = getattr(profile, "industry", "") if profile is not None else ""
        return theme_name or "待确认"

    def _hype_logic_for_symbol(self, symbol: str, recommendation=None, scan_row=None) -> str:
        news_items = list(getattr(self, "news_catalysts", {}).get(symbol, []) or [])
        latest_news = news_items[0] if news_items else None
        profile = self._stock_profile_for_symbol(symbol)
        if recommendation is not None:
            return build_hype_logic_summary(
                theme_name=self._theme_for_symbol(symbol, recommendation=recommendation),
                catalyst=getattr(recommendation, "catalyst", "") or "",
                rationale=getattr(recommendation, "rationale", "") or "",
                profile_notes=getattr(profile, "notes", "") if profile is not None else "",
                scan_reason=getattr(scan_row, "reason", "") if scan_row is not None else "",
                news_title=getattr(latest_news, "title", "") if latest_news is not None else "",
            )
        if profile is not None and getattr(profile, "notes", ""):
            return build_hype_logic_summary(
                theme_name=self._theme_for_symbol(symbol, recommendation=recommendation),
                profile_notes=getattr(profile, "notes", ""),
                scan_reason=getattr(scan_row, "reason", "") if scan_row is not None else "",
                news_title=getattr(latest_news, "title", "") if latest_news is not None else "",
            )
        if scan_row is not None and getattr(scan_row, "reason", ""):
            return build_hype_logic_summary(
                theme_name=self._theme_for_symbol(symbol, recommendation=recommendation),
                scan_reason=getattr(scan_row, "reason", ""),
                news_title=getattr(latest_news, "title", "") if latest_news is not None else "",
            )
        return "等待逻辑生成"

    def _news_digest_lines_for_symbol(self, symbol: str, limit: int = 2) -> list[str]:
        if not symbol:
            return []
        items = list(getattr(self, "news_catalysts", {}).get(symbol, []) or [])
        return build_news_digest_lines(items, limit=limit)

    def _latest_news_item_for_symbol(self, symbol: str):
        if not symbol:
            return None
        items = list(getattr(self, "news_catalysts", {}).get(symbol, []) or [])
        return items[0] if items else None

