    def _news_source_button_base_tooltip(self) -> str:
        return "打开当前焦点消息的原文链接。已公告优先打开公告 PDF，媒体催化则打开来源页面。"

    def _news_detail_label(self, item) -> str:
        source = str(getattr(item, "source", "") or "") if item is not None else ""
        visual = news_source_visual_label(source)
        return {
            "已公告": "公告详情",
            "媒体催化": "媒体详情",
            "传闻线索": "线索详情",
        }.get(visual, "消息详情")

    def _news_detail_button_base_tooltip(self) -> str:
        return "查看当前焦点消息的详情信息，包括分层、来源、时间、摘要和原文入口。"

    def _news_item_tooltip(self, item) -> str:
        if item is None:
            return "当前焦点还没有可查看的消息原文。"
        source = str(getattr(item, "source", "") or "来源未知")
        published = str(getattr(item, "published_at", "") or "时间未知")
        visual = news_source_visual_label(source)
        title = str(getattr(item, "title", "") or "消息标题未填写")
        summary = str(getattr(item, "summary", "") or "暂无补充说明")
        url = str(getattr(item, "url", "") or "").strip()
        availability = "可直接打开原文链接。" if url else "当前这条消息还没有稳定原文链接。"
        return "\n".join(
            [
                f"分层：{visual}",
                f"来源：{source}",
                f"时间：{published}",
                f"标题：{title}",
                f"摘要：{summary}",
                availability,
            ]
        )

    def _news_detail_lines(self, item) -> list[str]:
        if item is None:
            return ["当前焦点还没有可查看的消息详情。"]
        source = str(getattr(item, "source", "") or "来源未知")
        published = str(getattr(item, "published_at", "") or "时间未知")
        visual = news_source_visual_label(source)
        confidence = news_source_tier(source)
        title = str(getattr(item, "title", "") or "消息标题未填写")
        summary = str(getattr(item, "summary", "") or "暂无补充说明")
        url = str(getattr(item, "url", "") or "").strip()
        availability = "可直接打开原文链接。" if url else "当前这条消息还没有稳定原文链接。"
        return [
            f"分层：{visual} / 可信度 {confidence}",
            f"来源：{source}",
            f"时间：{published}",
            f"标题：{title}",
            f"摘要：{summary}",
            f"原文：{url or '暂无稳定原文链接'}",
            availability,
        ]

    def _news_related_notice_lines(self, item) -> list[str]:
        if item is None:
            return []
        summary = str(getattr(item, "summary", "") or "")
        if "同日合并" not in summary or "：" not in summary:
            return []
        tail = summary.split("：", 1)[-1]
        if " | " in tail:
            tail = tail.split(" | ", 1)[0]
        return [part.strip() for part in tail.split(" / ") if part.strip()]

    def _set_news_focus_context(self, item, *, target: str = "") -> None:
        symbol = str(getattr(item, "symbol", "") or "") if item is not None else ""
        if not symbol:
            self.last_news_focus_context = {}
            return
        self.last_news_focus_context = {
            "symbol": symbol,
            "title": str(getattr(item, "title", "") or "消息标题未填写"),
            "source": str(getattr(item, "source", "") or "来源未知"),
            "target": target,
        }

    def _trigger_news_navigation_feedback(self, item, *, target: str = "") -> None:
        symbol = str(getattr(item, "symbol", "") or "") if item is not None else ""
        if not symbol:
            self.transient_news_feedback = {}
            return
        title = str(getattr(item, "title", "") or "消息标题未填写")
        source = str(getattr(item, "source", "") or "来源未知")
        self.transient_news_feedback = {
            "symbol": symbol,
            "title": title,
            "source": source,
            "target": target,
        }
        if hasattr(self, "statusBar"):
            status_bar = self.statusBar()
            if status_bar is not None and hasattr(status_bar, "showMessage"):
                status_bar.showMessage(f"已根据消息定位焦点：{title}", 2600)
        if hasattr(self, "_refresh_workspace_focus_banners"):
            self._refresh_workspace_focus_banners()
        if hasattr(self, "_news_feedback_timer"):
            self._news_feedback_timer.start(2600)

    def _clear_news_navigation_feedback(self) -> None:
        self.transient_news_feedback = {}
        if hasattr(self, "_refresh_workspace_focus_banners"):
            self._refresh_workspace_focus_banners()

    def _news_focus_context_suffix(self, symbol: str) -> str:
        context = getattr(self, "last_news_focus_context", {}) or {}
        if not symbol or context.get("symbol") != symbol:
            return ""
        transient = getattr(self, "transient_news_feedback", {}) or {}
        if transient.get("symbol") == symbol:
            return " | 【消息驱动】刚由消息定位"
        return " | 【消息驱动】"

    def _news_focus_context_tooltip(self, symbol: str) -> str:
        context = getattr(self, "last_news_focus_context", {}) or {}
        if not symbol or context.get("symbol") != symbol:
            return ""
        visual = news_source_visual_label(str(context.get("source", "") or ""))
        title = str(context.get("title", "") or "消息标题未填写")
        target = str(context.get("target", "") or "workspace")
        target_map = {
            "recommend": "推荐页",
            "detail": "复盘页",
            "broker": "交易页",
            "overview": "总览",
        }
        return f"来自消息驱动：{visual} | {title} | 由消息详情跳转到{target_map.get(target, target)}"

    def _news_focus_badge_html(self, symbol: str, *, compact: bool = False) -> str:
        context = getattr(self, "last_news_focus_context", {}) or {}
        if not symbol or context.get("symbol") != symbol:
            return ""
        transient = getattr(self, "transient_news_feedback", {}) or {}
        padding = "1px 6px" if compact else "2px 8px"
        font_size = "10px" if compact else "11px"
        primary = (
            "<span style=\"display:inline-block;vertical-align:middle;"
            "background:rgba(27,74,58,0.96);color:#e8fff4;border:1px solid rgba(77,226,154,0.72);"
            f"border-radius:999px;padding:{padding};font-size:{font_size};font-weight:800;letter-spacing:0.3px;\">"
            "消息驱动</span>"
        )
        if transient.get("symbol") != symbol:
            return primary
        secondary = (
            "<span style=\"display:inline-block;vertical-align:middle;margin-left:4px;"
            "background:rgba(22,48,74,0.96);color:#eef8ff;border:1px solid rgba(143,213,255,0.68);"
            f"border-radius:999px;padding:{padding};font-size:{font_size};font-weight:800;letter-spacing:0.3px;\">"
            "刚定位</span>"
        )
        return primary + secondary

    def _render_text_with_news_badge(self, text: str, symbol: str, *, compact: bool = False) -> str:
        badge = self._news_focus_badge_html(symbol, compact=compact)
        if not badge:
            return text
        return f"{badge} <span>{html.escape(text)}</span>"

    def _card_news_badge_html(self, symbol: str) -> str:
        context = getattr(self, "last_news_focus_context", {}) or {}
        if not symbol or context.get("symbol") != symbol:
            return ""
        transient = getattr(self, "transient_news_feedback", {}) or {}
        bg = "rgba(27,74,58,0.94)"
        border = "rgba(77,226,154,0.72)"
        text = "消息驱动"
        if transient.get("symbol") == symbol:
            bg = "rgba(22,48,74,0.94)"
            border = "rgba(143,213,255,0.68)"
            text = "刚由消息定位"
        return (
            "<span style=\"display:inline-block;vertical-align:middle;"
            f"background:{bg};color:#eef8ff;border:1px solid {border};"
            "border-radius:999px;padding:1px 7px;font-size:10px;font-weight:800;letter-spacing:0.3px;\">"
            f"{text}</span>"
        )

    def _prepend_card_badge(self, text: str, symbol: str) -> str:
        badge = self._card_news_badge_html(symbol)
        if not badge:
            return text
        return f"{badge} <span>{html.escape(text)}</span>"

    def _news_recommended_action(self, item) -> tuple[str, str, str]:
        if item is None:
            return ("overview", "先看总览", "当前消息还没绑定清晰股票上下文，先回到总览确认焦点。")
        summary = str(getattr(item, "summary", "") or "")
        title = str(getattr(item, "title", "") or "")
        combined = f"{title} {summary}"
        if any(token in combined for token in ("治理动作", "审计安排")):
            return ("broker", "先看交易页", "这类公告偏中性，先确认有没有足够执行价值再推进交易。")
        if any(token in combined for token in ("分红预案", "资本动作", "订单催化")):
            return ("recommend", "先看推荐页", "这类催化更适合先看机会分层、题材位置和后续承接。")
        if any(token in combined for token in ("定期报告", "业绩快报", "年报季")):
            return ("detail", "先看复盘页", "这类催化更适合先核对业绩兑现、预期差和历史信号回放。")
        if any(token in combined for token in ("交流信息", "媒体催化", "传闻线索")):
            return ("overview", "先看总览", "先回到总览看它是否已经被主线资金放大，再决定要不要深入。")
        return ("overview", "先看总览", "先回到总览确认主线和量价，再决定往哪个工作流继续。")

    def _news_recommended_action_copy(self, item, *, prefix: str = "建议") -> str:
        _target, headline, detail = self._news_recommended_action(item)
        return f"{prefix}：{headline} | {detail}"

    def _news_source_button_base_tooltip_safe_v58(self) -> str:
        fn = getattr(self, "_news_source_button_base_tooltip", None)
        if callable(fn):
            return fn()
        return QuantHunterWindow._news_source_button_base_tooltip(self)

    def _news_detail_button_base_tooltip_safe_v58(self) -> str:
        fn = getattr(self, "_news_detail_button_base_tooltip", None)
        if callable(fn):
            return fn()
        return QuantHunterWindow._news_detail_button_base_tooltip(self)

    def _news_workflow_snapshot_lines(self, symbol: str = "") -> list[str]:
        current = self._selected_daily_pool_recommendation() if hasattr(self, "_selected_daily_pool_recommendation") else None
        target_symbol = (
            symbol
            or getattr(current, "symbol", "")
            or getattr(self, "active_symbol", "")
            or next(iter(getattr(self, "news_catalysts", {}) or {}), "")
        )
        if not target_symbol:
            return ["- 当前消息工作流：等待焦点消息同步。"]
        item = self._latest_news_item_for_symbol(target_symbol)
        if item is None:
            return [f"- 当前消息工作流：{self._stock_name_for_symbol(target_symbol)} 还没有可用消息。"]
        stock_name = self._stock_name_for_symbol(target_symbol)
        stock_id = self._stock_id_for_symbol(target_symbol)
        source = str(getattr(item, "source", "") or "来源未知")
        visual = news_source_visual_label(source)
        title = str(getattr(item, "title", "") or "消息标题未填写")
        url = str(getattr(item, "url", "") or "").strip()
        action_target, action_headline, _action_detail = self._news_recommended_action(item)
        route_map = {
            "recommend": "推荐页",
            "detail": "复盘页",
            "broker": "交易页",
            "overview": "总览",
        }
        return [
            f"- 当前焦点：{stock_name} ({stock_id} / {target_symbol})",
            f"- 当前消息：{visual} | {title}",
            f"- 建议动作：{action_headline} -> {route_map.get(action_target, action_target)}",
            f"- 原文状态：{'可打开原文' if url else '暂无稳定原文'}",
        ]

    def _news_action_brief(self, symbol: str = "") -> str:
        item = self._latest_news_item_for_symbol(symbol)
        if item is None:
            return ""
        _target, headline, _detail = self._news_recommended_action(item)
        return f"消息建议：{headline}"

    def _news_recommended_action_copy_safe_v57(self, item, *, prefix: str = "建议") -> str:
        recommended_copy_fn = getattr(self, "_news_recommended_action_copy", None)
        if callable(recommended_copy_fn):
            return recommended_copy_fn(item, prefix=prefix)
        recommended_action_fn = getattr(self, "_news_recommended_action", None)
        if callable(recommended_action_fn):
            _target, headline, detail = recommended_action_fn(item)
            return f"{prefix}：{headline} | {detail}"
        _target, headline, detail = QuantHunterWindow._news_recommended_action(self, item)
        return f"{prefix}：{headline} | {detail}"

    def _update_news_action_button(self, button, item) -> None:
        if button is None:
            return
        if item is None:
            button.setText("查看原文")
            button.setEnabled(False)
            button.setToolTip("当前焦点还没有可查看的消息原文。")
            if hasattr(self, "_set_button_role"):
                self._set_button_role(button, "ghost")
            return
        source = str(getattr(item, "source", "") or "")
        visual = news_source_visual_label(source)
        button.setText(self._news_action_label(item))
        button.setEnabled(True)
        recommended_copy = QuantHunterWindow._news_recommended_action_copy_safe_v57(self, item)
        button.setToolTip(QuantHunterWindow._news_source_button_base_tooltip_safe_v58(self) + "\n" + self._news_item_tooltip(item) + "\n" + recommended_copy)
        if hasattr(self, "_set_button_role"):
            role = "ghost"
            if visual == "已公告":
                role = "accent"
            elif visual == "媒体催化":
                role = "tonal"
            self._set_button_role(button, role)

    def _update_news_detail_button(self, button, item) -> None:
        if button is None:
            return
        if item is None:
            button.setText("消息详情")
            button.setEnabled(False)
            button.setToolTip("当前焦点还没有可查看的消息详情。")
            if hasattr(self, "_set_button_role"):
                self._set_button_role(button, "ghost")
            return
        source = str(getattr(item, "source", "") or "")
        visual = news_source_visual_label(source)
        button.setText(f"查看{self._news_detail_label(item)}")
        button.setEnabled(True)
        recommended_copy = QuantHunterWindow._news_recommended_action_copy_safe_v57(self, item)
        button.setToolTip(QuantHunterWindow._news_detail_button_base_tooltip_safe_v58(self) + "\n" + self._news_item_tooltip(item) + "\n" + recommended_copy + "\n点击查看详情弹窗。")
        if hasattr(self, "_set_button_role"):
            role = "ghost"
            if visual == "已公告":
                role = "tonal"
            elif visual == "媒体催化":
                role = "ghost"
            self._set_button_role(button, role)

    def _show_news_detail_dialog(self, item, *, title: str = "消息详情") -> None:
        if item is None:
            QMessageBox.information(self, "提示", "当前焦点还没有可查看的消息详情。")
            return
        dialog = QDialog(self)
        dialog.setWindowTitle(title)
        dialog.resize(720, 440)
        layout = QVBoxLayout(dialog)

        title_label = QLabel(str(getattr(item, "title", "") or "消息标题未填写"))
        title_label.setObjectName("workspaceTitle")
        title_label.setWordWrap(True)
        layout.addWidget(title_label)

        meta_label = QLabel(self._news_detail_lines(item)[0])
        meta_label.setObjectName("inlineHint")
        meta_label.setWordWrap(True)
        layout.addWidget(meta_label)

        action_target, action_headline, action_detail = self._news_recommended_action(item)
        action_label = QLabel(f"建议动作：{action_headline} | {action_detail}")
        action_label.setObjectName("inlineHint")
        action_label.setWordWrap(True)
        layout.addWidget(action_label)

        body = QTextEdit(dialog)
        body.setReadOnly(True)
        self._style_terminal_console(body)
        self._set_plain_text_if_changed(body, "\n".join(self._news_detail_lines(item)[1:]))
        layout.addWidget(body, stretch=1)

        related_lines = self._news_related_notice_lines(item)
        if related_lines:
            related_title = QLabel("配套公告")
            related_title.setObjectName("inlineHint")
            layout.addWidget(related_title)
            related_text = QTextEdit(dialog)
            related_text.setReadOnly(True)
            self._style_terminal_console(related_text)
            self._set_plain_text_if_changed(related_text, "\n".join(f"- {line}" for line in related_lines))
            related_text.setMaximumHeight(120)
            layout.addWidget(related_text)

        button_row = QHBoxLayout()
        open_button = QPushButton(self._news_action_label(item))
        recommend_button = QPushButton("查看推荐")
        detail_button = QPushButton("查看复盘")
        broker_button = QPushButton("去交易页")
        close_button = QPushButton("关闭")
        self._set_button_role(open_button, "accent" if str(getattr(item, "url", "") or "").strip() else "ghost")
        self._set_button_role(recommend_button, "accent" if action_target == "recommend" else "tonal")
        self._set_button_role(detail_button, "accent" if action_target == "detail" else "ghost")
        self._set_button_role(broker_button, "accent" if action_target == "broker" else "tonal")
        self._set_button_role(close_button, "ghost")
        open_button.setEnabled(bool(str(getattr(item, "url", "") or "").strip()))
        open_button.setToolTip(self._news_item_tooltip(item))
        open_button.clicked.connect(lambda: self._open_news_item_url(item, empty_title="提示"))
        symbol = str(getattr(item, "symbol", "") or "")
        recommend_button.setEnabled(bool(symbol))
        detail_button.setEnabled(bool(symbol))
        broker_button.setEnabled(bool(symbol))
        recommend_button.setToolTip("带着当前消息对应的股票跳到推荐页。\n建议动作：" + ("是" if action_target == "recommend" else "否"))
        detail_button.setToolTip("带着当前消息对应的股票跳到复盘页。\n建议动作：" + ("是" if action_target == "detail" else "否"))
        broker_button.setToolTip("带着当前消息对应的股票跳到交易执行页。\n建议动作：" + ("是" if action_target == "broker" else "否"))
        recommend_button.clicked.connect(lambda: (dialog.accept(), self._route_news_item_to_workspace(item, "recommend")) if symbol else None)
        detail_button.clicked.connect(lambda: (dialog.accept(), self._route_news_item_to_workspace(item, "detail")) if symbol else None)
        broker_button.clicked.connect(lambda: (dialog.accept(), self._route_news_item_to_workspace(item, "broker")) if symbol else None)
        close_button.clicked.connect(dialog.accept)
        button_row.addStretch(1)
        button_row.addWidget(open_button)
        button_row.addWidget(recommend_button)
        button_row.addWidget(detail_button)
        button_row.addWidget(broker_button)
        button_row.addWidget(close_button)
        layout.addLayout(button_row)
        dialog.exec()

    def _open_news_item_url(self, item, *, empty_title: str = "提示") -> bool:
        url = str(getattr(item, "url", "") or "").strip() if item is not None else ""
        if not url:
            QMessageBox.information(self, empty_title, "当前焦点消息还没有可打开的原文链接。")
            return False
        QDesktopServices.openUrl(QUrl(url))
        return True

    def open_overview_focus_news_source(self) -> None:
        symbol = getattr(self, "active_symbol", "") or ""
        item = self._latest_news_item_for_symbol(symbol)
        if item is None:
            QMessageBox.information(self, "提示", "当前焦点还没有可查看的消息原文。")
            return
        self._open_news_item_url(item, empty_title="提示")

    def open_overview_focus_news_detail(self) -> None:
        symbol = getattr(self, "active_symbol", "") or ""
        item = self._latest_news_item_for_symbol(symbol)
        self._show_news_detail_dialog(item, title="消息详情")

    def open_selected_recommend_news_source(self) -> None:
        current = self._selected_daily_pool_recommendation() if hasattr(self, "_selected_daily_pool_recommendation") else None
        symbol = getattr(current, "symbol", "") if current is not None else (getattr(self, "active_symbol", "") or "")
        item = self._latest_news_item_for_symbol(symbol)
        if item is None:
            QMessageBox.information(self, "提示", "当前焦点还没有可查看的消息原文。")
            return
        self._open_news_item_url(item, empty_title="提示")

    def open_selected_recommend_news_detail(self) -> None:
        current = self._selected_daily_pool_recommendation() if hasattr(self, "_selected_daily_pool_recommendation") else None
        symbol = getattr(current, "symbol", "") if current is not None else (getattr(self, "active_symbol", "") or "")
        item = self._latest_news_item_for_symbol(symbol)
        self._show_news_detail_dialog(item, title="焦点消息详情")

    def _route_news_item_to_workspace(self, item, target: str) -> None:
        symbol = str(getattr(item, "symbol", "") or "") if item is not None else ""
        if not symbol:
            QMessageBox.information(self, "提示", "当前消息还没有绑定股票代码，暂时无法跳转到工作流。")
            return
        news_focus_setter = getattr(self, "_set_news_focus_context", None)
        if callable(news_focus_setter):
            news_focus_setter(item, target=target)
        feedback_trigger = getattr(self, "_trigger_news_navigation_feedback", None)
        if callable(feedback_trigger):
            feedback_trigger(item, target=target)
        if hasattr(self, "_focus_symbol_everywhere"):
            self._focus_symbol_everywhere(symbol, origin="news")
        elif hasattr(self, "select_symbol") and symbol in getattr(self, "universe_bars", {}):
            self.select_symbol(symbol, origin="news")
        if target == "recommend":
            self._focus_symbol_in_recommend_workspace(symbol)
            return
        if target == "broker":
            self._focus_symbol_in_broker_workspace(symbol)
            return
        if target == "detail":
            if hasattr(self, "open_focus_symbol_in_detail"):
                self.active_symbol = symbol
                self.open_focus_symbol_in_detail()
            else:
                self._navigate_to_workspace("detail", "metrics_text")
            return
        if target == "overview":
            if symbol in getattr(self, "universe_bars", {}):
                self.select_symbol(symbol, origin="news")
            self._navigate_to_workspace("overview", "market_pool_table")

    def _compact_news_badge(self, symbol: str) -> str:
        items = list(getattr(self, "news_catalysts", {}).get(symbol, []) or [])
        if not items:
            return "消息：暂无"
        item = items[0]
        title = (getattr(item, "title", "") or "消息标题未填写")[:16]
        source = getattr(item, "source", "") or "来源未知"
        return f"消息：{news_source_visual_label(source)} | {title}"

    def _recommend_price_snapshot(self, recommendation) -> dict[str, float | None]:
        close_price = float(getattr(recommendation, "close", 0.0) or 0.0)
        entry_price = getattr(recommendation, "entry_price", None)
        stop_price = getattr(recommendation, "stop_price", None)
        target_price = getattr(recommendation, "target_price", None)
        entry = float(entry_price if entry_price is not None else close_price) if (entry_price is not None or close_price) else 0.0
        stop = float(stop_price if stop_price is not None else (entry * 0.95 if entry else 0.0))
        target = float(target_price if target_price is not None else (entry * 1.08 if entry else 0.0))
        upside_pct = ((target - entry) / entry * 100.0) if entry and target > entry else None
        downside_pct = ((entry - stop) / entry * 100.0) if entry and stop < entry else None
        rr_ratio = None
        if entry and stop and target and entry > stop and target > entry:
            rr_ratio = (target - entry) / max(entry - stop, 0.001)
        return {
            "entry": entry,
            "stop": stop,
            "target": target,
            "upside_pct": upside_pct,
            "downside_pct": downside_pct,
            "rr_ratio": rr_ratio,
        }

    def _recommend_price_brief(self, recommendation) -> str:
        snapshot = self._recommend_price_snapshot(recommendation)
        entry = float(snapshot["entry"] or 0.0)
        stop = float(snapshot["stop"] or 0.0)
        target = float(snapshot["target"] or 0.0)
        upside_pct = snapshot["upside_pct"]
        rr_ratio = snapshot["rr_ratio"]
        parts = [f"买 {entry:.2f}", f"损 {stop:.2f}", f"目标 {target:.2f}"]
        if upside_pct is not None:
            parts.append(f"上行 {upside_pct:.1f}%")
        if rr_ratio is not None:
            parts.append(f"盈亏比 {rr_ratio:.2f}")
        return " | ".join(parts)

