    def _maybe_auto_export_end_of_day_review(self, current_dt: datetime | None = None) -> None:
        if not hasattr(self, "auto_review_export_checkbox"):
            return
        if not self.auto_review_export_checkbox.isChecked():
            return

        current_dt = current_dt or datetime.now()
        if current_dt.time() < time(15, 5):
            return

        today_key = current_dt.strftime("%Y-%m-%d")
        if self.last_review_export_date == today_key:
            return

        artifacts = self.export_end_of_day_review_from_ui(show_dialog=False)
        if artifacts is None:
            return

        self.last_review_export_date = today_key
        self._set_label_text_if_changed(self.last_refresh_label, f"收盘复盘已导出：{current_dt.strftime('%H:%M:%S')}")

    def _maybe_auto_export_daily_trade_plan(self, current_dt: datetime | None = None) -> None:
        capabilities = self._license_capabilities()
        if not bool(capabilities["auto_daily_plan_export"]):
            return
        if not getattr(self.state, "auto_daily_plan_export", False):
            return
        if not self.daily_pool_rows:
            return

        current_dt = current_dt or datetime.now()
        current_time = current_dt.time()
        if current_time < time(8, 55) or current_time > time(9, 25):
            return

        today_key = current_dt.strftime("%Y-%m-%d")
        if self.last_daily_plan_export_date == today_key:
            return

        artifacts = self.export_daily_trade_plan_from_ui(show_dialog=False)
        if artifacts is None:
            return

        self.last_daily_plan_export_date = today_key
        if hasattr(self, "trade_plan_text"):
            existing = self.trade_plan_text.toPlainText().strip()
            note = f"自动盘前计划已导出：{current_dt.strftime('%H:%M:%S')}"
            merged = "\n".join([existing, "", note]) if existing else note
            self._set_plain_text_if_changed(self.trade_plan_text, merged)

    def _review_output_dir(self) -> Path:
        export_dir = self.current_broker_profile().export_dir.strip()
        if export_dir:
            return Path(export_dir) / "review_reports"
        return REPORT_DIR

    def _daily_plan_output_dir(self) -> Path:
        export_dir = self.current_broker_profile().export_dir.strip()
        if export_dir:
            return Path(export_dir) / "daily_plans"
        return REPORT_DIR / "daily_plans"

    def _strategy_history_output_dir(self) -> Path:
        export_dir = self.current_broker_profile().export_dir.strip()
        if export_dir:
            return Path(export_dir) / "strategy_history"
        return REPORT_DIR / "strategy_history"

    def _board_risk_colors(self, risk_level: str) -> tuple[QColor, QColor]:
        if risk_level == "低":
            return QColor("#E9F7EF"), QColor("#146C43")
        if risk_level == "中高":
            return QColor("#FFF4DB"), QColor("#8A5A00")
        if risk_level == "高":
            return QColor("#FBEAEA"), QColor("#842029")
        return QColor("#F8F9FA"), QColor("#212529")

    def _board_monitor_colors(self, state: str) -> tuple[QColor, QColor]:
        if state == "强势连板候选":
            return QColor("#E8F7EC"), QColor("#0F5132")
        if state == "回封观察":
            return QColor("#E7F1FF"), QColor("#084298")
        if state == "炸板风险":
            return QColor("#FBEAEA"), QColor("#842029")
        return QColor("#FFF4DB"), QColor("#7C4A03")


    def _refresh_board_mode(self) -> None:
        if not hasattr(self, "board_table") or not hasattr(self, "board_monitor_table"):
            return
        board_plan = BoardModeEngine().build(self.daily_pool_rows, top_n=5)
        board_signature = tuple(
            (
                item.stock_name,
                item.stock_id,
                item.symbol,
                f"{item.board_score:.1f}",
                f"{item.momentum_score:.1f}",
                f"{item.liquidity_score:.1f}",
                f"{item.leader_score:.1f}",
                item.trigger_style,
                item.risk_level,
                f"{item.planned_entry:.2f}",
                f"{item.planned_stop:.2f}",
                f"{item.planned_target:.2f}",
            )
            for item in board_plan.candidates
        )
        monitor_signature = tuple(
            (
                item.stock_name,
                item.stock_id,
                item.symbol,
                item.monitor_state,
                f"{item.strength_score:.1f}",
                f"{item.continuity_score:.1f}",
                f"{item.reboard_probability:.1f}",
                f"{item.blast_risk:.1f}",
                item.action_plan,
                item.note,
            )
            for item in board_plan.monitor_rows
        )
        selected_board_symbol = ""
        if self.board_table.currentRow() >= 0 and self.board_table.currentRow() < self.board_table.rowCount():
            item = self.board_table.item(self.board_table.currentRow(), 2)
            selected_board_symbol = item.text() if item else ""
        selected_monitor_symbol = ""
        if self.board_monitor_table.currentRow() >= 0 and self.board_monitor_table.currentRow() < self.board_monitor_table.rowCount():
            item = self.board_monitor_table.item(self.board_monitor_table.currentRow(), 2)
            selected_monitor_symbol = item.text() if item else ""

        if getattr(self, "_board_table_signature", None) != board_signature:
            board_updates_enabled = self.board_table.updatesEnabled()
            self.board_table.setUpdatesEnabled(False)
            self.board_table.blockSignals(True)
            try:
                self.board_table.setRowCount(len(board_plan.candidates))
                for row_index, item in enumerate(board_plan.candidates):
                    values = [
                        item.stock_name,
                        item.stock_id,
                        item.symbol,
                        f"{item.board_score:.1f}",
                        f"{item.momentum_score:.1f}",
                        f"{item.liquidity_score:.1f}",
                        f"{item.leader_score:.1f}",
                        item.trigger_style,
                        item.risk_level,
                        f"{item.planned_entry:.2f}",
                        f"{item.planned_stop:.2f}",
                        f"{item.planned_target:.2f}",
                    ]
                    bg, fg = self._board_risk_colors(item.risk_level)
                    for column, value in enumerate(values):
                        table_item = QTableWidgetItem(value)
                        table_item.setBackground(bg)
                        table_item.setForeground(fg)
                        table_item.setToolTip(
                            f"{item.stock_name} ({item.stock_id})\n"
                            f"交易标识：{item.symbol}\n"
                            f"触发方式：{item.trigger_style}\n"
                            f"风险级别：{item.risk_level}\n"
                            f"计划买点：{item.planned_entry:.2f}"
                        )
                        self.board_table.setItem(row_index, column, table_item)
                    identity_item = QTableWidgetItem(f"{item.stock_name} | {item.stock_id} | {item.symbol}")
                    identity_item.setBackground(bg)
                    identity_item.setForeground(fg)
                    identity_item.setToolTip(
                        f"{item.stock_name} ({item.stock_id})\n交易标识：{item.symbol}\n打板分：{item.board_score:.1f}\n风险：{item.risk_level}"
                    )
                    self.board_table.setItem(row_index, 0, identity_item)
            finally:
                self.board_table.blockSignals(False)
                self.board_table.setUpdatesEnabled(board_updates_enabled)
            self._board_table_signature = board_signature
            if board_plan.candidates:
                target_row = next(
                    (index for index, item in enumerate(board_plan.candidates) if item.symbol == selected_board_symbol),
                    0,
                )
                self.board_table.selectRow(target_row)

        if getattr(self, "_board_monitor_signature", None) != monitor_signature:
            monitor_updates_enabled = self.board_monitor_table.updatesEnabled()
            self.board_monitor_table.setUpdatesEnabled(False)
            self.board_monitor_table.blockSignals(True)
            try:
                self.board_monitor_table.setRowCount(len(board_plan.monitor_rows))
                for row_index, item in enumerate(board_plan.monitor_rows):
                    values = [
                        item.stock_name,
                        item.stock_id,
                        item.symbol,
                        item.monitor_state,
                        f"{item.strength_score:.1f}",
                        f"{item.continuity_score:.1f}",
                        f"{item.reboard_probability:.1f}",
                        f"{item.blast_risk:.1f}",
                        item.action_plan,
                        item.note,
                    ]
                    bg, fg = self._board_monitor_colors(item.monitor_state)
                    for column, value in enumerate(values):
                        table_item = QTableWidgetItem(value)
                        table_item.setBackground(bg)
                        table_item.setForeground(fg)
                        table_item.setToolTip(
                            f"{item.stock_name} ({item.stock_id})\n"
                            f"交易标识：{item.symbol}\n"
                            f"监控状态：{item.monitor_state}\n"
                            f"动作建议：{item.action_plan}\n"
                            f"备注：{item.note}"
                        )
                        self.board_monitor_table.setItem(row_index, column, table_item)
                    identity_item = QTableWidgetItem(f"{item.stock_name} | {item.stock_id} | {item.symbol}")
                    identity_item.setBackground(bg)
                    identity_item.setForeground(fg)
                    identity_item.setToolTip(
                        f"{item.stock_name} ({item.stock_id})\n交易标识：{item.symbol}\n监控状态：{item.monitor_state}\n强度：{item.strength_score:.1f}"
                    )
                    self.board_monitor_table.setItem(row_index, 0, identity_item)
            finally:
                self.board_monitor_table.blockSignals(False)
                self.board_monitor_table.setUpdatesEnabled(monitor_updates_enabled)
            self._board_monitor_signature = monitor_signature
            if board_plan.monitor_rows:
                target_row = next(
                    (index for index, item in enumerate(board_plan.monitor_rows) if item.symbol == selected_monitor_symbol),
                    0,
                )
                self.board_monitor_table.selectRow(target_row)
        self._apply_identity_table_headers()

        if hasattr(self, "board_text"):
            if board_plan.candidates:
                focus = board_plan.candidates[0]
                lines = [
                    f"打板温度：{board_plan.temperature}",
                    f"候选平均分：{board_plan.avg_score:.1f}",
                    "",
                    f"核心标的：{focus.stock_name} ({focus.stock_id})",
                    f"触发方式：{focus.trigger_style}",
                    f"计划价格：入场 {focus.planned_entry:.2f} | 止损 {focus.planned_stop:.2f} | 目标 {focus.planned_target:.2f}",
                    f"逻辑：{focus.rationale}",
                ]
            else:
                lines = ["当前没有满足条件的打板候选。"]
            self._set_plain_text_if_changed(self.board_text, "\n".join(lines))

        if hasattr(self, "board_monitor_text"):
            self._set_plain_text_if_changed(self.board_monitor_text, "\n".join(board_plan.notes))
        self._refresh_board_focus_panels()


    def _build_overview_tab(self) -> None:
        build_overview_workspace(
            self,
            build_table,
            StrategyParams,
            ActionFlowCard,
            CompactSummaryCard,
            LeaderboardCard,
        )

    def _refresh_overview_side_panels(self, rows: list) -> None:
        self._render_leaderboard_cards(rows)
        if hasattr(self, "market_leaderboard_text"):
            badge_map = {1: "TOP 1", 2: "TOP 2", 3: "TOP 3"}
            leaderboard_cards: list[str] = []
            for index, row in enumerate(rows[:3], start=1):
                border = "#f5c451" if index == 1 else ("#cfd8e3" if index == 2 else "#b7835a")
                badge = badge_map.get(index, f"TOP {index}")
                theme_name = getattr(row, "theme_name", "") or row.strategy_tag
                leaderboard_cards.append(
                    (
                        f"<div style='margin:0 0 12px 0;padding:12px;border:1px solid {border};"
                        "border-radius:10px;background:#11161d;'>"
                        f"<div style='color:{border};font-weight:800;font-size:12px;margin-bottom:6px;'>{badge}</div>"
                        f"<div style='color:#f5f7fa;font-weight:800;font-size:18px;'>{row.stock_name} {row.stock_id}</div>"
                        f"<div style='color:#8fa0b6;font-size:12px;margin-top:6px;'>题材方向：{theme_name}</div>"
                        f"<div style='color:#8fa0b6;font-size:12px;'>策略标签：{row.strategy_tag}</div>"
                        f"<div style='color:#8fa0b6;font-size:12px;'>资金标签：{row.fund_model}</div>"
                        f"<div style='color:#25f3ff;font-size:12px;margin-top:6px;'>热度 {row.heat_score:.1f} | 涨幅 {row.pct_change:.2f}%</div>"
                        f"<div style='color:#f5c451;font-size:12px;'>主力净流入 {row.main_inflow / 1e8:.2f} 亿</div>"
                        "</div>"
                    )
                )
            if not leaderboard_cards:
                leaderboard_cards.append("<div style='color:#8fa0b6;'>当前暂无入选标的。</div>")
            self.market_leaderboard_text.setHtml(
                "<div style='font-family:Microsoft YaHei UI;font-size:12px;'>"
                "<div style='color:#f5f7fa;font-size:18px;font-weight:800;margin-bottom:10px;'>掘龙榜</div>"
                + "".join(leaderboard_cards)
                + "</div>"
            )
        if hasattr(self, "market_theme_brief_text"):
            theme_counter: dict[str, int] = {}
            strategy_counter: dict[str, int] = {}
            for row in rows:
                theme_name = getattr(row, "theme_name", "") or row.strategy_tag
                theme_counter[theme_name] = theme_counter.get(theme_name, 0) + 1
                strategy_counter[row.strategy_tag] = strategy_counter.get(row.strategy_tag, 0) + 1
            ranked = sorted(theme_counter.items(), key=lambda item: item[1], reverse=True)
            top_theme_name = ranked[0][0] if ranked else "暂无主线"
            top_theme_count = ranked[0][1] if ranked else 0
            second_theme = ranked[1][0] if len(ranked) > 1 else "暂无副主线"
            top_strategy_name, top_strategy_count = (
                sorted(strategy_counter.items(), key=lambda item: item[1], reverse=True)[0]
                if strategy_counter
                else ("待策略同步", 0)
            )
            theme_lines = [
                "主线题材",
                f"结论：{top_theme_name} | 前排 {top_theme_count} 只",
                f"风险：题材数 {len(ranked)} | 次主线 {second_theme}",
                f"下一步：先看 {top_strategy_name}（{top_strategy_count} 只）",
            ]
            self._set_plain_text_if_changed(self.market_theme_brief_text, "\n".join(theme_lines))
            if hasattr(self, "overview_summary_cards"):
                self.overview_summary_cards["theme"].set_data(
                    top_theme_name,
                    f"前排 {top_theme_count} 只 | 题材数 {len(ranked)} | 焦点 {rows[0].stock_name if rows else '等待候选同步'}",
                )
        if hasattr(self, "market_breadth_text"):
            news_lines = ["新闻流", ""]
            seen_symbols: set[str] = set()
            for row in rows[:6]:
                symbol_news = self.news_catalysts.get(row.symbol, [])
                if symbol_news:
                    item = symbol_news[0]
                    source = getattr(item, "source", "") or "来源未知"
                    published = getattr(item, "published_at", "") or ""
                    meta = " / ".join(part for part in [source, published] if part)
                    news_lines.append(f"- {row.stock_name}: {item.title}{f' ({meta})' if meta else ''}")
                    if getattr(item, "summary", ""):
                        news_lines.append(f"  {item.summary[:42]}")
                    seen_symbols.add(row.symbol)
            if len(news_lines) == 2:
                for row in rows[:4]:
                    if row.symbol in seen_symbols:
                        continue
                    news_lines.append(
                        f"- {row.stock_name}: {row.strategy_tag} / 涨幅 {row.pct_change:.2f}% / 主力净流入 {row.main_inflow / 1e8:.2f} 亿"
                    )
            if len(news_lines) == 2:
                news_lines.append("- 当前暂无新闻流摘要。")
            self._set_plain_text_if_changed(self.market_breadth_text, "\n".join(news_lines))
        if hasattr(self, "overview_summary_cards") and not rows:
            self.overview_summary_cards["theme"].set_data("暂无", "等待远程行情或本地缓存加载。")
        self._refresh_market_source_status()

    def _refresh_market_source_status(self, extra_lines: list[str] | None = None) -> None:
        if not hasattr(self, "market_source_status_text"):
            return
        cache_stats = LocalMarketCache().cache_stats()
        source_code = getattr(self, "market_data_source", "unknown")
        cache_hit = "是" if source_code in {"cache_fresh", "cache_stale", "cache_only"} else "否"
        pool_count = len(getattr(self.market_screen_result, 'algorithmic_pool', []))
        source_name = self._market_source_mode_label()
        mode_name = self._market_mode_label()
        cache_mb = float(cache_stats.get('bytes', 0) or 0.0) / (1024 * 1024)
        lines = [
            f"结论：{source_name} | 模式 {mode_name} | 候选 {pool_count} 只",
            f"风险：缓存 {'命中' if cache_hit == '是' else '未命中'} | 文件 {cache_stats.get('files', 0)} | 体量 {cache_mb:.1f} MB",
            f"下一步：{(self.last_market_error[:72] if self.last_market_error else '继续刷新市场，确认图表、主线和候选同步。')}",
        ]
        source_detail = f"{mode_name} / 缓存 {'命中' if cache_hit == '是' else '未命中'} / 候选 {pool_count} 只"
        status_signature = (
            source_name,
            mode_name,
            pool_count,
            cache_hit,
            int(cache_stats.get('files', 0) or 0),
            round(cache_mb, 3),
            str(self.last_market_error[:72] if self.last_market_error else ""),
            tuple(extra_lines or []),
        )
        if getattr(self, "_market_source_status_signature_v2", None) == status_signature:
            return
        self._market_source_status_signature_v2 = status_signature
        self._set_plain_text_if_changed(self.market_source_status_text, "\n".join(lines))
        if hasattr(self, "overview_summary_cards"):
            self.overview_summary_cards["source"].set_data(source_name, source_detail)

    def _market_mode_label(self) -> str:
        return {"auto": "自动", "cache": "仅缓存", "sample": "示例模式"}.get(getattr(self, "market_data_mode", "auto"), "自动")

    def _market_source_mode_label(self) -> str:
        return {
            "remote": "东方财富实时",
            "cache_fresh": "本地新缓存",
            "cache_stale": "本地旧缓存",
            "cache_only": "仅缓存模式",
            "sample": "示例模式",
            "unknown": "未确定",
        }.get(getattr(self, "market_data_source", "unknown"), "未确定")

    def set_market_filter(self, tag: str) -> None:
        self.market_filter_tag = tag
        for current_tag, button in getattr(self, "market_filter_buttons", {}).items():
            button.setChecked(current_tag == tag)
        self._apply_market_filters()
        strategy_target = tag if tag in STRATEGY_SCORE_FIELDS else None
        if strategy_target and hasattr(self, "strategy_detail_combo"):
            self.strategy_detail_combo.setCurrentText(strategy_target)
        if strategy_target:
            self.recommend_strategy_filter = "尾盘优选" if strategy_target == "尾盘买入法" else strategy_target
            if hasattr(self, "_populate_filtered_daily_pool_table"):
                self._populate_filtered_daily_pool_table()
        if getattr(self, "market_status_label", None) is not None:
            status_text = self.market_status_label.text().split(" | 策略：", 1)[0].strip()
            strategy_text = "尾盘优选" if strategy_target == "尾盘买入法" else (strategy_target or "全部")
            self._set_label_text_if_changed(self.market_status_label, f"{status_text} | 策略：{strategy_text}")

    def toggle_dashboard_auto_refresh(self, checked: bool) -> None:
        if checked:
            self.execute_refresh_cycle()
            self.refresh_timer.start(self._refresh_interval_ms())
        elif not getattr(self, "auto_refresh_checkbox", None) or not self.auto_refresh_checkbox.isChecked():
            self.refresh_timer.stop()

    def load_universe_folder(self) -> None:
        self.refresh_remote_market(update_chart=True)

    def load_sample_universe(self) -> None:
        self.refresh_remote_market(update_chart=True)

    def rescan_universe(self) -> None:
        self.refresh_remote_market(update_chart=True)


    def _populate_existing_views_from_market(self) -> None:
        if hasattr(self, "scan_table"):
            self._fill_scan_rows()
        if hasattr(self, "summary_table"):
            self._fill_backtest_summaries()
        if hasattr(self, "daily_pool_table"):
            self._populate_daily_pool_table()
        if hasattr(self, "recommend_status_label"):
            self._set_label_text_if_changed(
                self.recommend_status_label,
                f"已切换为程序自动筛选股票池，共 {len(self.daily_pool_rows)} 只候选。"
            )
        if hasattr(self, "daily_pool_text"):
            if self.daily_pool_rows:
                top = self.daily_pool_rows[0]
                self._set_plain_text_if_changed(
                    self.daily_pool_text,
                    "\n".join(
                        [
                            "综合机会池",
                            f"结论：{top.stock_name} | 总分 {top.total_score:.1f}",
                            f"风险：{getattr(top, 'mainline_risk_flag', '--')} | {top.theme_name or '未分类'}",
                            f"下一步：{(top.next_focus or top.rationale or '继续盯主线与量价')[:22]}",
                        ]
                    )
                )
            else:
                self._set_plain_text_if_changed(self.daily_pool_text, "综合机会池\n结论：当前没有焦点票\n风险：暂无清晰主线\n下一步：继续等待。")
        self._refresh_trade_plan()
        self._refresh_board_mode()
        self._refresh_intraday_monitor()

    def _populate_daily_pool_table(self) -> None:
        self.theme_heat_rows, self.leader_candidates = summarize_themes(self.daily_pool_rows, top_n_themes=8, top_n_leaders=8)
        self._refresh_recommend_theme_options()
        self._populate_filtered_daily_pool_table()
        self._refresh_theme_heat_panels()

    def _populate_filtered_daily_pool_table(self) -> None:
        populate_filtered_daily_pool_table(self)

    def _refresh_recommend_theme_options(self) -> None:
        if not hasattr(self, "recommend_theme_combo"):
            return
        themes = ["全部"] + [item.theme_name for item in self.theme_heat_rows]
        current = self.recommend_theme_filter if self.recommend_theme_filter in themes else "全部"
        theme_signature = (tuple(themes), current)
        if getattr(self, "_recommend_theme_option_signature_v1", None) == theme_signature:
            self.recommend_theme_filter = current
            return
        self.recommend_theme_combo.blockSignals(True)
        self.recommend_theme_combo.clear()
        for theme in themes:
            self.recommend_theme_combo.addItem(theme)
        self.recommend_theme_combo.setCurrentText(current)
        self.recommend_theme_combo.blockSignals(False)
        self.recommend_theme_filter = current
        self._recommend_theme_option_signature_v1 = theme_signature

    def _on_recommend_theme_filter_changed(self, value: str) -> None:
        self.recommend_theme_filter = value or "全部"
        self._populate_filtered_daily_pool_table()
        self.save_state()

    def _refresh_theme_heat_panels(self) -> None:
        refresh_theme_heat_panels(self, STRATEGY_SCORE_FIELDS)

    def _refresh_strategy_pack_panels(self) -> None:
        refresh_strategy_pack_panels(self, STRATEGY_SCORE_FIELDS)

    def _filtered_daily_pool_rows(self) -> list[RecommendationRow]:
        rows = [
            row
            for row in self.daily_pool_rows
            if self.recommend_theme_filter == "全部" or (row.theme_name or "未分类") == self.recommend_theme_filter
        ]
        strategy_filter = str(getattr(self, "recommend_strategy_filter", "全部") or "全部")
        if strategy_filter == "尾盘优选":
            rows = [
                row
                for row in rows
                if (getattr(row, "primary_strategy", "") or "") == "尾盘买入法"
                and float(getattr(row, "tail_buy_score", 0.0) or 0.0) >= 82.0
                and float(getattr(row, "execution_readiness", 0.0) or 0.0) >= 72.0
                and str(getattr(row, "mainline_risk_flag", "") or "") != "高"
            ]
        elif strategy_filter not in {"全部", "全部策略"}:
            rows = [row for row in rows if (getattr(row, "primary_strategy", "") or "") == strategy_filter]
        return rows

    def _set_strategy_detail_from_row(self, row: RecommendationRow | None) -> None:
        if row is None or not hasattr(self, "strategy_detail_combo"):
            return
        self.strategy_detail_combo.setCurrentText(getattr(row, "primary_strategy", "") or "掘龙决策")

    def _refresh_recommendation_focus_panels(self, row: RecommendationRow | None = None) -> None:
        current = row or self._selected_daily_pool_recommendation()
        if current is None:
            if hasattr(self, "recommend_dispatch_text"):
                self._set_plain_text_if_changed(self.recommend_dispatch_text, "先看结论，再看分发顺序。\n刷新后这里会显示送审节奏、核心标的和优先队列。")
            if hasattr(self, "recommend_focus_review_text"):
                self._set_plain_text_if_changed(self.recommend_focus_review_text, "先看结论、位置和风险。\n选中一只股票后，这里会显示单票审查摘要。")
            if hasattr(self, "recommend_queue_text"):
                self._set_plain_text_if_changed(self.recommend_queue_text, "待审、已审和失败队列会集中显示在这里。")
            self._refresh_recommend_story_panels(None)
            self._refresh_recommend_focus_status(None)
            return

        theme_name = getattr(current, "mainline_tag", "") or getattr(current, "theme_name", "") or "待确认"
        action_label = self._display_action(getattr(current, "action", "WATCH"))
        opportunity = getattr(current, "opportunity_tier", "") or "待确认"
        catalyst = getattr(current, "catalyst", "") or "量价共振 + 主力净流入"
        rationale = getattr(current, "rationale", "") or "等待更清晰的主线信号。"
        next_focus = getattr(current, "next_focus", "") or "盯住主线强度、量能承接和资金回流。"
        risk_flag = getattr(current, "mainline_risk_flag", "") or "待评估"
        confidence = float(getattr(current, "confidence_score", 0.0) or 0.0)
        readiness = float(getattr(current, "execution_readiness", 0.0) or 0.0)

        if hasattr(self, "recommend_dispatch_text"):
            dispatch_lines = [
                f"分发标的：{current.stock_name} ({current.stock_id} / {current.symbol})",
                f"主线：{theme_name} | 动作：{action_label} | 分层：{opportunity}",
                f"送审优先级：执行准备 {readiness:.1f} / 置信 {confidence:.1f}",
                f"催化：{catalyst}",
                f"分发建议：{next_focus}",
            ]
            self._set_plain_text_if_changed(self.recommend_dispatch_text, "\n".join(dispatch_lines))

        if hasattr(self, "recommend_focus_review_text"):
            review_lines = [
                f"单票审查：{current.stock_name}",
                f"总分 {float(getattr(current, 'total_score', 0.0) or 0.0):.1f} | 风险 {risk_flag} | 主策略 {getattr(current, 'primary_strategy', '') or '掘龙决策'}",
            ]
            review_lines.extend(recommendation_focus_lines(current))
            review_lines.append(f"核心理由：{rationale}")
            self._set_plain_text_if_changed(self.recommend_focus_review_text, "\n".join(review_lines))

        if hasattr(self, "recommend_queue_text"):
            buy_rows = [item for item in self.daily_pool_rows[:5] if getattr(item, "action", "") == "BUY"]
            watch_rows = [item for item in self.daily_pool_rows[:5] if getattr(item, "action", "") == "WATCH"]
            queue_lines = [
                f"当前前排：{current.stock_name} | {action_label}",
                f"待执行队列：{', '.join(item.stock_name for item in buy_rows[:3]) or '暂无可直接执行标的'}",
                f"观察队列：{', '.join(item.stock_name for item in watch_rows[:3]) or '暂无观察标的'}",
                f"风险提示：{risk_flag} | 失效条件：{getattr(current, 'invalidation_reason', '') or '跌破防守位或主线切换时重新评估'}",
            ]
            self._set_plain_text_if_changed(self.recommend_queue_text, "\n".join(queue_lines))

        if hasattr(self, "recommend_focus_metric_labels"):
            metric_values = {
                "symbol": (current.stock_name, f"{current.stock_id} / {current.symbol}"),
                "theme": (theme_name, f"主线位次 {getattr(current, 'mainline_rank', 0) or '--'}"),
                "action": (action_label, f"执行准备 {readiness:.1f}"),
                "execution": ("待处理" if getattr(current, "action", "") in {"BUY", "WATCH"} else "复核中", f"风险 {risk_flag}"),
            }
            for key, (value, accent) in metric_values.items():
                if key in self.recommend_focus_metric_labels:
                    self._set_label_text_if_changed(self.recommend_focus_metric_labels[key], value)
                if hasattr(self, "recommend_focus_metric_accents") and key in self.recommend_focus_metric_accents:
                    self._set_label_text_if_changed(self.recommend_focus_metric_accents[key], accent)
        self._refresh_recommend_focus_cards(current)
        self._refresh_recommend_story_panels(current)
        self._refresh_recommend_focus_status(current)

    def _refresh_recommend_focus_status(self, row: RecommendationRow | None = None) -> None:
        current = row or self._selected_daily_pool_recommendation()
        if current is None:
            if hasattr(self, "recommend_status_label"):
                total = len(getattr(self, "daily_pool_rows", []))
                self._set_label_text_if_changed(
                    self.recommend_status_label,
                    f"推荐状态：已生成 {total} 只候选，先看主线、位置、风险，再决定是否送审。"
                    if total
                    else RECOMMEND_DEFAULT_STATUS_TEXT
                )
            if hasattr(self, "daily_pool_focus_label"):
                self._set_label_text_if_changed(self.daily_pool_focus_label, RECOMMEND_DEFAULT_FOCUS_TEXT)
            self._refresh_workspace_status_labels()
            return

        theme_name = getattr(current, "mainline_tag", "") or getattr(current, "theme_name", "") or "待确认"
        action_label = self._display_action(getattr(current, "action", "WATCH"))
        readiness = float(getattr(current, "execution_readiness", 0.0) or 0.0)
        confidence = float(getattr(current, "confidence_score", 0.0) or 0.0)
        if hasattr(self, "recommend_status_label"):
            self._set_label_text_if_changed(
                self.recommend_status_label,
                f"推荐状态：{current.stock_name} | {theme_name} | {action_label} | 执行准备 {readiness:.1f} | 置信 {confidence:.1f}"
            )
        if hasattr(self, "daily_pool_focus_label"):
            self._set_label_text_if_changed(
                self.daily_pool_focus_label,
                f"当前焦点：{current.stock_name} | {getattr(current, 'opportunity_tier', '') or '待确认'} | 主线 {theme_name}"
            )
        self._refresh_workspace_status_labels()

    def _refresh_recommend_bucket_panels(self, row: RecommendationRow | None = None) -> None:
        current = row or self._selected_daily_pool_recommendation()
        trade_plan = getattr(self, "current_trade_plan", None)
        decisions = list(getattr(trade_plan, "decisions", []) or [])
        position_advice = list(getattr(self, "current_position_advice", []) or [])
        buy_rows = [item for item in decisions if str(getattr(item, "action", "") or "").upper() == "BUY"]
        watch_rows = [item for item in getattr(self, "daily_pool_rows", []) if str(getattr(item, "action", "") or "").upper() == "WATCH"]
        risk_rows = [item for item in position_advice if str(getattr(item, "action", "") or "").upper() in {"SELL", "REDUCE"}]
        if not any(
            hasattr(self, name)
            for name in ("recommend_core_bucket_text", "recommend_watch_bucket_text", "recommend_risk_bucket_text")
        ):
            return
        signature = (
            (
                str(getattr(current, "symbol", "") or ""),
                str(getattr(current, "stock_id", "") or ""),
                str(getattr(current, "stock_name", "") or ""),
                str(getattr(current, "action", "") or ""),
                str(getattr(current, "mainline_tag", "") or getattr(current, "theme_name", "") or ""),
                str(getattr(current, "opportunity_tier", "") or ""),
                round(float(getattr(current, "execution_readiness", 0.0) or 0.0), 1) if current is not None else 0.0,
                str(getattr(current, "catalyst", "") or ""),
                str(getattr(current, "next_focus", "") or ""),
                str(getattr(current, "mainline_risk_flag", "") or ""),
                str(getattr(current, "invalidation_reason", "") or ""),
                str(getattr(current, "mainline_flow_signal", "") or ""),
                str(getattr(current, "mainline_stage", "") or ""),
            )
            if current is not None
            else ("empty",)
        )
        signature += (
            tuple(
                (
                    str(getattr(item, "symbol", "") or ""),
                    str(getattr(item, "stock_id", "") or ""),
                    str(getattr(item, "stock_name", "") or ""),
                    str(getattr(item, "action", "") or ""),
                    round(float(getattr(item, "position_pct", 0.0) or 0.0), 4),
                    round(float(getattr(item, "planned_price", getattr(item, "entry_price", 0.0)) or 0.0), 4),
                    round(float(getattr(item, "stop_price", 0.0) or 0.0), 4),
                    round(float(getattr(item, "target_price", 0.0) or 0.0), 4),
                    str(getattr(item, "reason", "") or getattr(item, "rationale", "") or ""),
                )
                for item in buy_rows[:1]
            ),
            tuple(
                (
                    str(getattr(item, "symbol", "") or ""),
                    str(getattr(item, "stock_name", "") or ""),
                )
                for item in watch_rows[:3]
            ),
            len(watch_rows),
            tuple(
                (
                    str(getattr(item, "symbol", "") or ""),
                    str(getattr(item, "stock_id", "") or ""),
                    str(getattr(item, "stock_name", "") or ""),
                    str(getattr(item, "action", "") or ""),
                    str(getattr(item, "mainline_flow_signal", "") or ""),
                    str(getattr(item, "mainline_stage", "") or ""),
                    str(getattr(item, "reason", "") or getattr(item, "rationale", "") or ""),
                )
                for item in risk_rows[:3]
            ),
            len(risk_rows),
        )
        if getattr(self, "_recommend_bucket_panels_signature_v1", None) == signature:
            return
        self._recommend_bucket_panels_signature_v1 = signature

        if hasattr(self, "recommend_core_bucket_text"):
            if buy_rows:
                top = buy_rows[0]
                lines = [
                    "主线前排执行桶",
                    f"优先标的：{getattr(top, 'stock_name', '') or self._stock_name_for_symbol(getattr(top, 'symbol', ''))} ({getattr(top, 'stock_id', '') or self._stock_id_for_symbol(getattr(top, 'symbol', ''))})",
                    f"计划动作：{self._display_action(getattr(top, 'action', 'BUY'))} | 仓位 {getattr(top, 'position_pct', 0.0):.0%}",
                    f"计划价格：{getattr(top, 'planned_price', getattr(top, 'entry_price', 0.0)) or 0.0:.2f} | 止损 {getattr(top, 'stop_price', 0.0) or 0.0:.2f} | 目标 {getattr(top, 'target_price', 0.0) or 0.0:.2f}",
                    f"执行理由：{getattr(top, 'reason', '') or getattr(top, 'rationale', '') or '优先处理主线前排。'}",
                ]
            elif current is not None and str(getattr(current, "action", "") or "").upper() == "BUY":
                lines = [
                    "主线前排执行桶",
                    f"候选标的：{current.stock_name} ({current.stock_id} / {current.symbol})",
                    f"主线：{getattr(current, 'mainline_tag', '') or getattr(current, 'theme_name', '') or '待确认'} | 执行准备 {getattr(current, 'execution_readiness', 0.0):.1f}",
                    f"预案：可优先送审，确认量能承接后进入交易页。",
                    f"催化：{getattr(current, 'catalyst', '') or '等待资金与主线共振。'}",
                ]
            else:
                lines = ["主线前排执行桶", "当前没有直接执行的新仓计划。", "先看推荐池前排和交易计划刷新结果。"]
            self._set_plain_text_if_changed(self.recommend_core_bucket_text, "\n".join(lines))

        if hasattr(self, "recommend_watch_bucket_text"):
            if current is not None:
                lines = [
                    "观察池",
                    f"当前焦点：{current.stock_name} ({current.stock_id} / {current.symbol})",
                    f"观察动作：{self._display_action(getattr(current, 'action', 'WATCH'))} | 分层 {getattr(current, 'opportunity_tier', '') or '待确认'}",
                    f"下一步：{getattr(current, 'next_focus', '') or '继续看主线强度、量能回流和分时承接。'}",
                    f"备选观察：{', '.join(item.stock_name for item in watch_rows[:3]) or '暂无其他观察标的'}",
                ]
            else:
                lines = ["观察池", "等待推荐池生成后，再更新观察名单。", f"当前观察数量：{len(watch_rows)}"]
            self._set_plain_text_if_changed(self.recommend_watch_bucket_text, "\n".join(lines))

        if hasattr(self, "recommend_risk_bucket_text"):
            if risk_rows:
                top = risk_rows[0]
                symbol = getattr(top, "symbol", "")
                lines = [
                    "风险池",
                    f"优先处理：{getattr(top, 'stock_name', '') or self._stock_name_for_symbol(symbol)} ({getattr(top, 'stock_id', '') or self._stock_id_for_symbol(symbol)})",
                    f"动作：{self._display_action(getattr(top, 'action', 'REDUCE'))} | 主线 {getattr(top, 'mainline_flow_signal', '') or '待确认'} / {getattr(top, 'mainline_stage', '') or '待确认'}",
                    f"原因：{getattr(top, 'reason', '') or getattr(top, 'rationale', '') or '主线走弱或触发风控条件。'}",
                    f"风险队列：{', '.join((getattr(item, 'stock_name', '') or self._stock_name_for_symbol(getattr(item, 'symbol', ''))) for item in risk_rows[:3])}",
                ]
            elif current is not None:
                lines = [
                    "风险池",
                    f"焦点风险：{getattr(current, 'mainline_risk_flag', '') or '待评估'} | 失效条件：{getattr(current, 'invalidation_reason', '') or '跌破防守位或主线切换。'}",
                    f"当前主线：{getattr(current, 'mainline_flow_signal', '') or '待确认'} / {getattr(current, 'mainline_stage', '') or '待确认'}",
                    "若盘中出现切换预警，优先减仓或回到观察状态。",
                ]
            else:
                lines = ["风险池", "当前没有新增风险处理任务。", "导入持仓或生成计划后，这里会优先展示卖出 / 减仓建议。"]
            self._set_plain_text_if_changed(self.recommend_risk_bucket_text, "\n".join(lines))

    def _refresh_recommend_focus_cards(self, row: RecommendationRow | None = None) -> None:
        current = row or self._selected_daily_pool_recommendation()
        if current is None:
            return

        theme_name = getattr(current, "mainline_tag", "") or getattr(current, "theme_name", "") or "待确认"
        strategy_name = getattr(current, "primary_strategy", "") or "掘龙决策"
        action_label = self._display_action(getattr(current, "action", "WATCH"))
        readiness = float(getattr(current, "execution_readiness", 0.0) or 0.0)
        confidence = float(getattr(current, "confidence_score", 0.0) or 0.0)
        flow_signal = getattr(current, "mainline_flow_signal", "") or "待确认"
        stage_name = getattr(current, "mainline_stage", "") or "待确认"
        risk_flag = getattr(current, "mainline_risk_flag", "") or "待评估"
        next_focus = getattr(current, "next_focus", "") or "继续跟踪主线强度、量能承接和资金回流。"
        catalyst = getattr(current, "catalyst", "") or "量价共振 + 资金回流"

        if hasattr(self, "recommend_summary_cards"):
            self.recommend_summary_cards["logic"].set_data(
                theme_name,
                f"{current.stock_name} | {self._display_mainline_role(getattr(current, 'mainline_role', '') or '')} | 总分 {current.total_score:.1f}",
            )
            self.recommend_summary_cards["plan"].set_data(
                action_label,
                f"执行准备 {readiness:.1f} | 置信 {confidence:.1f} | {strategy_name}",
            )
            self.recommend_summary_cards["pulse"].set_data(
                flow_signal,
                f"阶段 {stage_name} | 风险 {risk_flag}",
            )
            self.recommend_summary_cards["holding"].set_data(
                "盯下一步",
                next_focus,
            )

        if hasattr(self, "priority_cards"):
            self.priority_cards["theme"].set_data(
                f"{getattr(current, 'mainline_window_score', 0.0):.1f}",
                f"焦点: {theme_name}",
                f"{self._display_mainline_role(getattr(current, 'mainline_role', '') or '')} | 风险 {risk_flag}",
            )
            self.priority_cards["strategy"].set_data(
                f"{strategy_name}",
                f"焦点: {current.stock_name}",
                f"主打法与当前焦点一致，优先核对催化和位置。",
            )
            self.priority_cards["focus"].set_data(
                f"{getattr(current, 'dragon_decision_score', getattr(current, 'total_score', 0.0)):.1f}",
                f"焦点: {current.stock_name}",
                f"{action_label} | {theme_name} | 准备 {readiness:.1f}",
            )

        if hasattr(self, "action_flow_cards"):
            self.action_flow_cards["BUY"].set_data(
                self.action_flow_cards["BUY"].count_label.text(),
                f"焦点: {current.stock_name}" if getattr(current, "action", "") == "BUY" else f"焦点: {self.action_flow_cards['BUY'].focus_label.text().replace('焦点: ', '')}",
                "确认买点后推进送审。" if getattr(current, "action", "") == "BUY" else self.action_flow_cards["BUY"].note_label.text(),
            )
            self.action_flow_cards["WATCH"].set_data(
                self.action_flow_cards["WATCH"].count_label.text(),
                f"焦点: {current.stock_name}" if getattr(current, "action", "") == "WATCH" else self.action_flow_cards["WATCH"].focus_label.text(),
                "继续盯承接、量能和扩散。" if getattr(current, "action", "") == "WATCH" else self.action_flow_cards["WATCH"].note_label.text(),
            )
            if getattr(current, "action", "") in {"REDUCE", "SELL"}:
                key = "SELL" if getattr(current, "action", "") == "SELL" else "REDUCE"
                self.action_flow_cards[key].set_data(
                    self.action_flow_cards[key].count_label.text(),
                    f"焦点: {current.stock_name}",
                    "纪律触发后优先处理。" if key == "SELL" else "先降风险，再决定是否继续。",
                )

        if hasattr(self, "alert_cards"):
            self.alert_cards["theme"].set_data(stage_name, f"主线 {theme_name} | 信号 {flow_signal}")
            self.alert_cards["leader"].set_data(
                self._display_mainline_role(getattr(current, "mainline_role", "") or ""),
                f"焦点标的：{current.stock_name} | 龙头级别 {self._display_leader_level(getattr(current, 'leader_level', '') or '')}",
            )
            self.alert_cards["strategy"].set_data(strategy_name, f"动作 {action_label} | 催化 {catalyst[:12]}")
            self.alert_cards["action"].set_data(action_label, f"下一步 {next_focus[:18]}")

    def _refresh_overview_focus_cards(self, symbol: str, snapshot, recommendation) -> None:
        if not hasattr(self, "overview_summary_cards"):
            return
        if recommendation is not None:
            theme_name = getattr(recommendation, "mainline_tag", "") or getattr(recommendation, "theme_name", "") or "待确认"
            role_name = self._display_mainline_role(getattr(recommendation, "mainline_role", "") or "")
            strategy_name = getattr(recommendation, "primary_strategy", "") or "掘龙决策"
            action_label = self._display_action(getattr(recommendation, "action", "WATCH"))
            catalyst = getattr(recommendation, "catalyst", "") or "等待消息与量价共振"
            decision_score = float(getattr(recommendation, "dragon_decision_score", getattr(recommendation, "total_score", 0.0)) or 0.0)
            self.overview_summary_cards["theme"].set_data(
                theme_name,
                f"{recommendation.stock_name} | {role_name} | 位次 {getattr(recommendation, 'mainline_rank', getattr(recommendation, 'theme_rank', '--'))}",
            )
            self.overview_summary_cards["source"].set_data(
                strategy_name,
                f"{action_label} | 催化 {catalyst}",
            )
            self.overview_summary_cards["capital"].set_data(
                f"{float(getattr(recommendation, 'mainline_window_score', 0.0) or 0.0):.1f}",
                f"总分 {float(getattr(recommendation, 'total_score', 0.0) or 0.0):.1f} | 风险 {getattr(recommendation, 'mainline_risk_flag', '') or '待评估'}",
            )
            self.overview_summary_cards["decision"].set_data(
                action_label,
                f"决策分 {decision_score:.1f} | 执行准备 {float(getattr(recommendation, 'execution_readiness', 0.0) or 0.0):.1f}",
            )
            return
        if snapshot is not None:
            self.overview_summary_cards["theme"].set_data(
                snapshot.strategy_tag or "待确认",
                f"{snapshot.stock_name} | 热度 {snapshot.heat_score:.1f} | 动能 {snapshot.momentum_bias:.1f}",
            )
            self.overview_summary_cards["source"].set_data(
                snapshot.fund_model or "待确认",
                f"{snapshot.stock_id} | 涨跌 {snapshot.pct_change:.2f}% | 换手 {snapshot.turnover:.2f}%",
            )
            self.overview_summary_cards["capital"].set_data(
                f"{snapshot.main_inflow / 1e8:.2f} 亿",
                f"热度 {snapshot.heat_score:.1f} | 动能 {snapshot.momentum_bias:.1f} | 换手 {snapshot.turnover:.2f}%",
            )
            self.overview_summary_cards["decision"].set_data(
                "观察",
                f"{snapshot.strategy_tag} | 涨跌 {snapshot.pct_change:.2f}% | 先看量价承接",
            )
            return
        stock_name = self._stock_name_for_symbol(symbol) if symbol else "等待行情接入"
        self.overview_summary_cards["theme"].set_data("等待行情接入", f"{stock_name} | 等待主线题材、龙头位次与前排数量刷新。")
        self.overview_summary_cards["source"].set_data("等待行情接入", "等待远程行情、缓存或示例数据接入。")

    def _refresh_recommend_story_panels(self, row: RecommendationRow | None = None) -> None:
        current = row or self._selected_daily_pool_recommendation()
        if current is None:
            if hasattr(self, "daily_pool_text") and not self.daily_pool_text.toPlainText().strip():
                self._set_plain_text_if_changed(self.daily_pool_text, "综合机会池\n结论：等待机会池生成\n风险：暂无焦点风险\n下一步：先刷新市场。")
            if hasattr(self, "strategy_path_text") and not self.strategy_path_text.toPlainText().strip():
                self._set_plain_text_if_changed(self.strategy_path_text, "主线推演\n结论：等待主线确认\n风险：暂无主线风险\n下一步：先确认主线。")
            self._refresh_recommend_bucket_panels(None)
            return

        theme_name = getattr(current, "mainline_tag", "") or getattr(current, "theme_name", "") or "待确认"
        role_name = getattr(current, "mainline_role", "") or ""
        flow_signal = getattr(current, "mainline_flow_signal", "") or "待确认"
        stage_name = getattr(current, "mainline_stage", "") or "待确认"
        readiness = float(getattr(current, "execution_readiness", 0.0) or 0.0)
        confidence = float(getattr(current, "confidence_score", 0.0) or 0.0)
        stock_pool = getattr(current, "stock_pool", "") or "程序自动筛选池"
        catalyst = getattr(current, "catalyst", "") or "量价共振 + 资金回流"
        next_focus = getattr(current, "next_focus", "") or "继续盯主线强度、量能承接和回流节奏。"
        invalidation = getattr(current, "invalidation_reason", "") or "跌破防守位或主线切换时重新评估。"

        if hasattr(self, "daily_pool_text"):
            lines = [
                "综合机会池",
                f"结论：{current.stock_name} | {self._display_action(getattr(current, 'action', 'WATCH'))} | 总分 {current.total_score:.1f}",
                f"风险：{theme_name} | {stage_name} | {getattr(current, 'mainline_risk_flag', '--') or '--'}",
                f"下一步：{(next_focus or catalyst or '继续盯主线与量价')[:22]}",
            ]
            self._set_plain_text_if_changed(self.daily_pool_text, "\n".join(lines))

        if hasattr(self, "strategy_path_text"):
            lines = [
                "主线推演",
                f"结论：{theme_name} | {self._display_mainline_role(role_name)} | {flow_signal}",
                f"风险：窗口 {readiness:.1f} | {invalidation[:18]}",
                f"下一步：{next_focus[:22]}",
            ]
            self._set_plain_text_if_changed(self.strategy_path_text, "\n".join(lines))
        self._refresh_recommend_bucket_panels(current)

    def _select_daily_pool_row_by_stock_id(self, stock_id: str) -> RecommendationRow | None:
        if not stock_id or not hasattr(self, "daily_pool_table"):
            return None
        for index, row in enumerate(self._filtered_daily_pool_rows()):
            if row.stock_id == stock_id:
                changed = self._select_table_row_if_needed(self.daily_pool_table, index)
                self._set_strategy_detail_from_row(row)
                if changed:
                    self._refresh_recommendation_focus_panels(row)
                return row
        return None

    def _on_daily_pool_selection_changed(self) -> None:
        self._refresh_recommendation_focus_panels()
        self._refresh_strategy_focus_detail()

    def _on_theme_heat_selection_changed(self) -> None:
        if not hasattr(self, "theme_heat_table") or not hasattr(self, "recommend_theme_combo"):
            return
        row_index = self.theme_heat_table.currentRow()
        if row_index < 0 or row_index >= len(self.theme_heat_rows):
            return
        theme_name = self.theme_heat_rows[row_index].theme_name
        self.recommend_theme_combo.setCurrentText(theme_name)

    def _on_leader_table_selection_changed(self) -> None:
        if not hasattr(self, "leader_table") or not hasattr(self, "daily_pool_table"):
            return
        row_index = self.leader_table.currentRow()
        if row_index < 0 or row_index >= len(self.leader_candidates):
            return
        stock_id = self.leader_candidates[row_index].stock_id
        self._select_daily_pool_row_by_stock_id(stock_id)

    def _on_trade_plan_selection_changed(self) -> None:
        if not hasattr(self, "trade_plan_table") or not hasattr(self, "daily_pool_table"):
            return
        row_index = self.trade_plan_table.currentRow()
        if row_index < 0:
            return
        stock_id_item = self.trade_plan_table.item(row_index, 1)
        stock_id = stock_id_item.text() if stock_id_item else ""
        if not stock_id:
            return
        selected = self._select_daily_pool_row_by_stock_id(stock_id)
        self._refresh_recommendation_focus_panels(selected)

    def _on_position_advice_selection_changed(self) -> None:
        if not hasattr(self, "position_advice_table") or not hasattr(self, "daily_pool_table"):
            return
        row_index = self.position_advice_table.currentRow()
        if row_index < 0:
            return
        stock_id_item = self.position_advice_table.item(row_index, 1)
        stock_id = stock_id_item.text() if stock_id_item else ""
        if not stock_id:
            return
        self._select_daily_pool_row_by_stock_id(stock_id)

    def _refresh_strategy_focus_detail(self) -> None:
        refresh_strategy_focus_detail(self, STRATEGY_SCORE_FIELDS)

    def _apply_market_filters(self) -> None:
        apply_market_filters(self)

    def _populate_market_depth_texts(self, rows: list) -> None:
        populate_market_depth_texts(self, rows)

    def on_market_pool_selected(self) -> None:
        if not hasattr(self, "market_pool_table"):
            return
        row = self.market_pool_table.currentRow()
        if row < 0:
            return
        symbol_item = self.market_pool_table.item(row, 0)
        symbol = str(symbol_item.data(Qt.UserRole)) if symbol_item and symbol_item.data(Qt.UserRole) else ""
        if symbol and symbol in self.universe_bars:
            self.select_symbol(symbol, origin="overview")

    def select_symbol(self, symbol: str, origin: str = "") -> None:
        if symbol not in self.universe_bars:
            return
        self.active_symbol = symbol
        self.bars = self.universe_bars[symbol]
        self.analyses = self.universe_analyses[symbol]
        if hasattr(self, "active_symbol_label"):
            self._set_label_text_if_changed(self.active_symbol_label, f"当前标的：{symbol}")
        self.state.selected_symbol = symbol
        self._refresh_signal_panel()
        self.run_backtest_for_active(quiet=True)
        self._render_market_dashboard(symbol)
        self._refresh_detail_workspace_panels()
        self._sync_symbol_across_workspaces(symbol, origin=origin)
        self._refresh_workspace_focus_banners()
        self._refresh_live_workspace_summary_panels()
        self.save_state()

    def _render_market_dashboard(self, symbol: str) -> None:
        snapshot = self.market_snapshots.get(symbol)
        recommendation = next((item for item in self.daily_pool_rows if item.symbol == symbol), None)
        chart_series = getattr(self.market_screen_result, "chart_series_by_symbol", {}).get(symbol)
        if hasattr(self, "market_header_label"):
            title = symbol if snapshot is None else f"{snapshot.stock_name}  {snapshot.stock_id}  {symbol}"
            self._set_label_text_if_changed(self.market_header_label, title)
        if hasattr(self, "market_subheader_label"):
            sub = "程序自动筛选出的龙头候选"
            if snapshot is not None:
                sub = (
                    f"{snapshot.strategy_tag} | {snapshot.fund_model} | 涨跌幅 {snapshot.pct_change:.2f}% | "
                    f"换手 {snapshot.turnover:.1f}% | 主力净流入 {snapshot.main_inflow / 1e8:.2f} 亿"
                )
            self._set_label_text_if_changed(self.market_subheader_label, sub)
        if hasattr(self, "market_signal_label") and snapshot is not None:
            self._set_label_text_if_changed(
                self.market_signal_label,
                f"{snapshot.fund_model}   |   {snapshot.strategy_tag}   |   热度 {snapshot.heat_score:.1f}   |   动能 {snapshot.momentum_bias:.1f}"
            )
        if hasattr(self, "market_quote_label"):
            if snapshot is not None:
                self._set_label_text_if_changed(
                    self.market_quote_label,
                    f"开 {snapshot.open_price:.2f} / 高 {snapshot.high_price:.2f} / 低 {snapshot.low_price:.2f} / 收 {snapshot.latest_price:.2f} "
                    f"| 涨跌 {snapshot.pct_change:.2f}% | 换手 {snapshot.turnover:.2f}% | 历史窗口 {self.market_history_window}"
                )
            else:
                self._set_label_text_if_changed(
                    self.market_quote_label,
                    f"历史窗口 {self.market_history_window} | 周期 {self.market_timeframe_mode} | 叠加 {'/'.join(self._ordered_market_overlays(self.market_overlay_modes)) or '关闭'}"
                )
        self._update_intraday_chart(symbol, snapshot, chart_series)
        self._update_daily_chart(symbol)
        self._update_fund_chart(symbol, chart_series)
        self._update_momentum_chart(symbol, chart_series)
        self._update_indicator_chart(symbol)
        self._update_market_text_panels(symbol, snapshot, recommendation)
        self._refresh_overview_focus_cards(symbol, snapshot, recommendation)

    def _build_market_proxy_points(self) -> tuple[list[object], float]:
        rows = list(getattr(self.market_screen_result, "algorithmic_pool", []))[:8]
        if not rows:
            return [], 0.0
        avg_pct = sum(getattr(row, "pct_change", 0.0) for row in rows) / max(len(rows), 1)
        base_price = 1000.0
        values = [
            base_price,
            base_price * (1 + avg_pct / 100.0 * 0.04),
            base_price * (1 + avg_pct / 100.0 * 0.01),
            base_price * (1 + avg_pct / 100.0 * 0.08),
            base_price * (1 + avg_pct / 100.0 * 0.15),
            base_price * (1 + avg_pct / 100.0 * 0.11),
            base_price * (1 + avg_pct / 100.0 * 0.18),
        ]
        points = [type("P", (), {"t": f"{index}", "v": value})() for index, value in enumerate(values)]
        return points, base_price

    def _normalize_market_timeframe(self, timeframe: str | None = None) -> str:
        value = (timeframe or getattr(self, "market_timeframe_mode", "日线") or "日线").strip()
        return value or "日线"

    @staticmethod
    def _ordered_market_overlays(overlays: set[str] | list[str] | tuple[str, ...]) -> list[str]:
        order = ["MA", "BOLL", "HIGHLOW", "BREAK"]
        overlay_set = {item for item in overlays if item}
        return [name for name in order if name in overlay_set]

    @staticmethod
    def _market_breakout_reference(visible_bars: list[PriceBar], index: int, lookback: int = 10) -> float | None:
        if index < lookback:
            return None
        window = visible_bars[index - lookback:index]
        if len(window) < lookback:
            return None
        return max(bar.high for bar in window)

    @staticmethod
    def _classify_market_breakout(
        bar: PriceBar,
        baseline: float | None,
        previous_close: float | None = None,
    ) -> tuple[str | None, float | None]:
        if baseline is None or baseline <= 0:
            return None, None
        distance_pct = (bar.close - baseline) / baseline * 100.0
        tolerance = baseline * 0.003
        if previous_close is not None and previous_close < baseline - tolerance and bar.close > baseline + tolerance:
            return "向上突破", distance_pct
        if bar.low <= baseline <= bar.close and bar.close >= baseline - tolerance:
            return "回踩站稳", distance_pct
        if bar.high >= baseline and bar.close < baseline - tolerance:
            return "冲高回落", distance_pct
        if abs(bar.close - baseline) <= tolerance:
            return "临界观察", distance_pct
        if bar.close > baseline + tolerance:
            return "强势站上", distance_pct
        return "未破前高", distance_pct

    @staticmethod
    def _market_channel_position(bar: PriceBar, channel_high: float | None, channel_low: float | None) -> tuple[str | None, float | None]:
        if channel_high is None or channel_low is None or channel_high <= channel_low:
            return None, None
        ratio = (bar.close - channel_low) / (channel_high - channel_low)
        ratio = max(0.0, min(ratio, 1.0))
        if ratio >= 0.8:
            return "箱体上沿", ratio
        if ratio <= 0.2:
            return "箱体下沿", ratio
        return "箱体中部", ratio

    @staticmethod
    def _market_structure_summary(visible_bars: list[PriceBar]) -> str:
        if len(visible_bars) < 6:
            return "结构 观察样本不足"
        split_index = max(len(visible_bars) // 2, 1)
        left = visible_bars[:split_index]
        right = visible_bars[split_index:]
        if not left or not right:
            return "结构 观察样本不足"

        left_high = max(bar.high for bar in left)
        left_low = min(bar.low for bar in left)
        right_high = max(bar.high for bar in right)
        right_low = min(bar.low for bar in right)
        first_close = visible_bars[0].close
        last_close = visible_bars[-1].close
        total_change = ((last_close - first_close) / first_close * 100.0) if abs(first_close) > 1e-9 else 0.0

        midpoint = (right_high + right_low) / 2.0
        tolerance = max(midpoint * 0.01, 0.03)
        higher_high = right_high > left_high + tolerance
        higher_low = right_low > left_low + tolerance
        lower_high = right_high < left_high - tolerance
        lower_low = right_low < left_low - tolerance

        if higher_high and higher_low:
            structure = "抬高上行"
        elif lower_high and lower_low:
            structure = "转弱下压"
        elif abs(right_high - left_high) <= tolerance and abs(right_low - left_low) <= tolerance:
            structure = "箱体震荡"
        elif higher_high and not higher_low:
            structure = "上冲分歧"
        elif lower_low and not lower_high:
            structure = "下探承压"
        else:
            structure = "震荡整理"

        last_position = "偏强" if last_close >= midpoint + tolerance * 0.4 else ("偏弱" if last_close <= midpoint - tolerance * 0.4 else "中性")
        return f"结构 {structure} | 收盘位置 {last_position} | 窗口变化 {total_change:+.2f}%"

    @staticmethod
    def _market_swing_points(
        visible_bars: list[PriceBar],
        neighbor_span: int = 0,
    ) -> list[tuple[int, str, float, str]]:
        if neighbor_span <= 0:
            neighbor_span = 1 if len(visible_bars) <= 18 else 2
        if len(visible_bars) < neighbor_span * 2 + 1:
            return []
        swings: list[tuple[int, str, float, str]] = []
        last_type = ""
        for index in range(neighbor_span, len(visible_bars) - neighbor_span):
            bar = visible_bars[index]
            neighbors = visible_bars[index - neighbor_span:index] + visible_bars[index + 1:index + 1 + neighbor_span]
            if not neighbors:
                continue
            is_high = all(bar.high >= item.high for item in neighbors) and any(bar.high > item.high for item in neighbors)
            is_low = all(bar.low <= item.low for item in neighbors) and any(bar.low < item.low for item in neighbors)
            if is_high and last_type != "high":
                swings.append((index, "high", bar.high, f"摆点高 {bar.high:.2f}"))
                last_type = "high"
            elif is_low and last_type != "low":
                swings.append((index, "low", bar.low, f"摆点低 {bar.low:.2f}"))
                last_type = "low"
        return swings

    @staticmethod
    def _market_rhythm_summary(visible_bars: list[PriceBar]) -> str:
        if len(visible_bars) < 6:
            return "节奏 观察样本不足"
        structure_text = QuantHunterWindow._market_structure_summary(visible_bars)
        swings = QuantHunterWindow._market_swing_points(visible_bars)
        recent_window = visible_bars[-6:]
        recent_high = max(bar.high for bar in recent_window)
        recent_low = min(bar.low for bar in recent_window)
        first_close = recent_window[0].close
        last_close = recent_window[-1].close
        recent_change = ((last_close - first_close) / first_close * 100.0) if abs(first_close) > 1e-9 else 0.0
        drawdown_pct = ((recent_high - last_close) / recent_high * 100.0) if recent_high > 1e-9 else 0.0
        rebound_pct = ((last_close - recent_low) / recent_low * 100.0) if recent_low > 1e-9 else 0.0

        if "抬高上行" in structure_text and recent_change >= 2.0 and drawdown_pct <= 2.5:
            rhythm = "主升推进"
        elif "抬高上行" in structure_text and drawdown_pct <= 6.5 and rebound_pct >= 2.0:
            rhythm = "强势回踩"
        elif "转弱下压" in structure_text and recent_change <= -2.0:
            rhythm = "转弱回落"
        elif "箱体震荡" in structure_text or abs(recent_change) <= 1.2:
            rhythm = "震荡整理"
        elif rebound_pct >= 3.0 and drawdown_pct <= 4.0:
            rhythm = "低位修复"
        else:
            rhythm = "切换观察"

        signature = "".join("高" if item[1] == "high" else "低" for item in swings[-4:]) or "不足"
        last_turn = swings[-1][3] if swings else "最近摆点待确认"
        return f"节奏 {rhythm} | 摆点序列 {signature} | {last_turn}"

    @staticmethod
    def _classify_market_candle_tag(
        bar: PriceBar,
        previous_bars: list[PriceBar],
        breakout_value: float | None = None,
        breakout_state: str | None = None,
    ) -> tuple[str | None, str | None]:
        if not previous_bars:
            return None, None
        avg_volume = sum(item.volume for item in previous_bars[-5:]) / max(min(len(previous_bars), 5), 1)
        volume_ratio = (bar.volume / avg_volume) if avg_volume > 1e-9 else 1.0
        full_range = max(bar.high - bar.low, 1e-9)
        upper_shadow = bar.high - max(bar.open, bar.close)
        lower_shadow = min(bar.open, bar.close) - bar.low
        close_position = (bar.close - bar.low) / full_range
        prev_close = previous_bars[-1].close
        pct_change = ((bar.close - prev_close) / prev_close * 100.0) if abs(prev_close) > 1e-9 else 0.0

        if breakout_value is not None and breakout_state in {"向上突破", "强势站上"} and volume_ratio >= 1.15 and pct_change > 1.2:
            return "放量突破", f"量比 {volume_ratio:.2f} | 突破位上方 {((bar.close - breakout_value) / breakout_value * 100.0):+.2f}%"
        if breakout_value is not None and breakout_state == "回踩站稳" and volume_ratio <= 1.0 and close_position >= 0.58:
            return "缩量回踩", f"量比 {volume_ratio:.2f} | 回踩后收于区间上部"
        if breakout_value is not None and breakout_state in {"未破前高", "临界观察"} and prev_close >= breakout_value * 0.985 and bar.low <= breakout_value * 1.01 and bar.close >= breakout_value * 0.997 and volume_ratio <= 1.0:
            return "缩量回踩", f"量比 {volume_ratio:.2f} | 临近突破位反复确认"
        if (breakout_state == "冲高回落" or (upper_shadow / full_range >= 0.32 and close_position <= 0.38)) and pct_change < 1.0:
            return "冲高回落", f"上影占比 {upper_shadow / full_range * 100:.0f}% | 量比 {volume_ratio:.2f}"
        if lower_shadow / full_range >= 0.35 and close_position >= 0.65 and pct_change >= -1.2:
            return "长下影承接", f"下影占比 {lower_shadow / full_range * 100:.0f}% | 收盘位置 {close_position * 100:.0f}%"
        return None, None

    @staticmethod
    def _latest_market_candle_tag_summary(
        visible_bars: list[PriceBar],
        breakout_values: list[float | None],
        breakout_states: list[str | None],
    ) -> str:
        if not visible_bars:
            return "关键K线 待识别"
        for index in range(len(visible_bars) - 1, -1, -1):
            tag, detail = QuantHunterWindow._classify_market_candle_tag(
                visible_bars[index],
                visible_bars[:index],
                breakout_values[index] if index < len(breakout_values) else None,
                breakout_states[index] if index < len(breakout_states) else None,
            )
            if tag:
                return f"关键K线 {tag} | {detail or '等待细节补充'}"
        return "关键K线 待识别"

    def _is_intraday_market_timeframe(self, timeframe: str | None = None) -> bool:
        return self._normalize_market_timeframe(timeframe) in {"分时", "1分", "5分", "15分", "30分", "60分"}

    @staticmethod
    def _market_intraday_time_label(index: int, total: int) -> str:
        if total <= 1:
            return "09:30"
        ratio = index / max(total - 1, 1)
        minutes = int(round(ratio * 240))
        minutes = max(0, min(minutes, 240))
        if minutes <= 120:
            total_minutes = 30 + minutes
            hour = 9 + total_minutes // 60
            minute = total_minutes % 60
        else:
            after_lunch = minutes - 120
            hour = 13 + after_lunch // 60
            minute = after_lunch % 60
        return f"{hour:02d}:{minute:02d}"

    @staticmethod
    def _interpolate_market_values(values: list[float], target_count: int) -> list[float]:
        if not values or target_count <= 0:
            return []
        if len(values) == 1:
            return [values[0]] * target_count
        if len(values) == target_count:
            return list(values)
        result: list[float] = []
        max_source = len(values) - 1
        max_target = max(target_count - 1, 1)
        for index in range(target_count):
            position = index * max_source / max_target
            left = int(position)
            right = min(left + 1, max_source)
            ratio = position - left
            result.append(values[left] + (values[right] - values[left]) * ratio)
        return result

    def _build_intraday_source_points(
        self,
        symbol: str,
        snapshot,
        chart_series,
        target_points: int = 240,
    ) -> list[tuple[str, float]]:
        raw_points = list(getattr(chart_series, "intraday_price", [])) if chart_series else []
        values = [
            float(getattr(point, "v", 0.0) or 0.0)
            for point in raw_points
            if getattr(point, "v", None) is not None
        ]
        if not values and snapshot is not None:
            base = snapshot.prev_close or snapshot.latest_price or 0.0
            pseudo = [
                base,
                snapshot.open_price or base,
                snapshot.low_price or base,
                ((snapshot.low_price or base) + (snapshot.open_price or base)) / 2,
                ((snapshot.high_price or base) + (snapshot.latest_price or base)) / 2,
                snapshot.high_price or base,
                snapshot.latest_price or base,
            ]
            values = [float(value or 0.0) for value in pseudo]
        if not values:
            proxy_points, _ = self._build_market_proxy_points()
            values = [
                float(getattr(point, "v", 0.0) or 0.0)
                for point in proxy_points
                if getattr(point, "v", None) is not None
            ]
        if not values:
            day_bars = list(self.universe_bars.get(symbol, []))
            if day_bars:
                values = [day_bars[-1].close]
        resampled = self._interpolate_market_values(values, max(target_points, len(values), 1))
        return [
            (self._market_intraday_time_label(index, len(resampled)), round(value, 3))
            for index, value in enumerate(resampled)
        ]

    def _build_intraday_bars_for_timeframe(self, symbol: str, snapshot, chart_series) -> list[PriceBar]:
        bucket_minutes = {
            "分时": 5,
            "1分": 1,
            "5分": 5,
            "15分": 15,
            "30分": 30,
            "60分": 60,
        }.get(self._normalize_market_timeframe())
        if bucket_minutes is None:
            return []
        source_points = self._build_intraday_source_points(symbol, snapshot, chart_series, target_points=240)
        if not source_points:
            return []
        day_bars = list(self.universe_bars.get(symbol, []))
        trade_date = day_bars[-1].date if day_bars else datetime.now().strftime("%Y-%m-%d")
        day_volume = float(day_bars[-1].volume) if day_bars else 0.0
        midpoint = max((len(source_points) - 1) / 2, 1.0)
        weights = [1.0 + abs(index - midpoint) / midpoint * 0.9 for index in range(len(source_points))]
        total_weight = sum(weights) or 1.0

        bars: list[PriceBar] = []
        for start in range(0, len(source_points), bucket_minutes):
            chunk = source_points[start:start + bucket_minutes]
            if not chunk:
                continue
            chunk_weights = weights[start:start + bucket_minutes]
            values = [value for _, value in chunk]
            reference = max(abs(values[0]), 1.0)
            volatility_boost = 1.0 + (max(values) - min(values)) / reference * 2.2
            volume = day_volume * (sum(chunk_weights) / total_weight) * volatility_boost
            bars.append(
                PriceBar(
                    date=f"{trade_date} {chunk[0][0]}",
                    symbol=symbol,
                    open=values[0],
                    high=max(values),
                    low=min(values),
                    close=values[-1],
                    volume=volume,
                )
            )
        return bars

    def _market_chart_bars(self, symbol: str, snapshot=None, chart_series=None) -> list[PriceBar]:
        bars = list(self.universe_bars.get(symbol, []))
        timeframe = self._normalize_market_timeframe()
        if timeframe == "周线":
            return aggregate_price_bars(bars, "weekly")
        if timeframe == "月线":
            return aggregate_price_bars(bars, "monthly")
        if self._is_intraday_market_timeframe(timeframe):
            intraday_bars = self._build_intraday_bars_for_timeframe(symbol, snapshot, chart_series)
            return intraday_bars if intraday_bars else bars[-60:]
        return bars

    @staticmethod
    def _market_chart_bars_for_timeframe(
        bars: list[PriceBar],
        timeframe: str,
    ) -> list[PriceBar]:
        normalized = (timeframe or "日线").strip() or "日线"
        if normalized == "周线":
            return aggregate_price_bars(bars, "weekly")
        if normalized == "月线":
            return aggregate_price_bars(bars, "monthly")
        return list(bars)

    def _market_multi_timeframe_summary(self, symbol: str) -> str:
        bars = list(self.universe_bars.get(symbol, []))
        if not bars:
            return "多周期共振 待行情接入"

        timeframe_specs = [("日", "日线"), ("周", "周线"), ("月", "月线")]
        parts: list[str] = []
        bullish_count = 0
        weak_count = 0
        for short_label, timeframe in timeframe_specs:
            tf_bars = self._market_chart_bars_for_timeframe(bars, timeframe)
            target_size = self._market_history_target_size(len(tf_bars), timeframe)
            visible = tf_bars[-target_size:] if target_size > 0 else tf_bars
            structure = self._market_structure_summary(visible)
            rhythm = self._market_rhythm_summary(visible)
            breakout_values = [self._market_breakout_reference(visible, index, lookback=10) for index in range(len(visible))]
            breakout_states = [
                self._classify_market_breakout(
                    bar,
                    breakout_values[index],
                    visible[index - 1].close if index > 0 else None,
                )[0]
                for index, bar in enumerate(visible)
            ]
            candle_tag = self._latest_market_candle_tag_summary(visible, breakout_values, breakout_states)

            structure_brief = structure.replace("结构 ", "").split(" | ", 1)[0]
            rhythm_brief = rhythm.replace("节奏 ", "").split(" | ", 1)[0]
            candle_brief = candle_tag.replace("关键K线 ", "").split(" | ", 1)[0]
            parts.append(f"{short_label}:{structure_brief}/{rhythm_brief}/{candle_brief}")

            if structure_brief in {"抬高上行"} or rhythm_brief in {"主升推进", "强势回踩", "低位修复"}:
                bullish_count += 1
            if structure_brief in {"转弱下压"} or rhythm_brief in {"转弱回落"}:
                weak_count += 1

        if bullish_count >= 2 and weak_count == 0:
            resonance = "多周期共振 偏强"
        elif weak_count >= 2 and bullish_count == 0:
            resonance = "多周期共振 偏弱"
        elif bullish_count >= 1 and weak_count >= 1:
            resonance = "多周期共振 分化"
        else:
            resonance = "多周期共振 中性"
        return f"{resonance} | " + " | ".join(parts)

    @staticmethod
    def _market_chart_score_summary(
        structure_summary: str,
        rhythm_summary: str,
        candle_tag_summary: str,
        resonance_summary: str,
    ) -> str:
        score = 50

        structure_map = {
            "抬高上行": 18,
            "上冲分歧": 6,
            "箱体震荡": 0,
            "震荡整理": -2,
            "下探承压": -10,
            "转弱下压": -18,
        }
        rhythm_map = {
            "主升推进": 18,
            "强势回踩": 12,
            "低位修复": 8,
            "震荡整理": 0,
            "切换观察": -2,
            "转弱回落": -16,
        }
        candle_map = {
            "放量突破": 14,
            "缩量回踩": 8,
            "长下影承接": 6,
            "冲高回落": -12,
            "待识别": 0,
        }
        resonance_map = {
            "多周期共振 偏强": 16,
            "多周期共振 中性": 0,
            "多周期共振 分化": -4,
            "多周期共振 偏弱": -16,
        }

        structure_key = structure_summary.replace("结构 ", "").split(" | ", 1)[0]
        rhythm_key = rhythm_summary.replace("节奏 ", "").split(" | ", 1)[0]
        candle_key = candle_tag_summary.replace("关键K线 ", "").split(" | ", 1)[0]
        resonance_key = resonance_summary.split(" | ", 1)[0]

        score += structure_map.get(structure_key, 0)
        score += rhythm_map.get(rhythm_key, 0)
        score += candle_map.get(candle_key, 0)
        score += resonance_map.get(resonance_key, 0)
        score = max(0, min(score, 100))

        if score >= 78:
            action = "偏进攻"
            risk = "以回踩确认和量价延续为先"
        elif score >= 62:
            action = "积极跟踪"
            risk = "可顺势观察，不追急拉"
        elif score >= 45:
            action = "中性观察"
            risk = "等待更清晰共振"
        elif score >= 28:
            action = "偏谨慎"
            risk = "先看承接和风险释放"
        else:
            action = "以防守为主"
            risk = "弱共振，避免逆势试错"
        return f"图表评分 {score} / 100 | 倾向 {action} | 提示 {risk}"

    @staticmethod
    def _market_chart_score_value(score_summary: str) -> int:
        import re

        match = re.search(r"图表评分\s+(\d+)", score_summary or "")
        return int(match.group(1)) if match else 50

    @staticmethod
    def _market_trade_zone_summary(visible_bars: list[PriceBar], score_summary: str) -> dict[str, float | str] | None:
        if len(visible_bars) < 6:
            return None
        latest = visible_bars[-1]
        recent = visible_bars[-20:] if len(visible_bars) >= 20 else visible_bars
        recent_high = max(bar.high for bar in recent)
        recent_low = min(bar.low for bar in recent)
        score = QuantHunterWindow._market_chart_score_value(score_summary)

        true_ranges = []
        previous_close = visible_bars[0].close
        for bar in visible_bars[-14:]:
            true_ranges.append(max(bar.high - bar.low, abs(bar.high - previous_close), abs(bar.low - previous_close)))
            previous_close = bar.close
        atr = sum(true_ranges) / max(len(true_ranges), 1)
        atr = max(atr, latest.close * 0.006, 0.01)

        if score >= 70:
            attack = max(latest.close + atr * 0.35, recent_high * 1.002)
            watch_low = max(recent_low, latest.close - atr * 1.2)
            watch_high = max(latest.close, attack)
            defense = max(recent_low, latest.close - atr * 2.0)
            mode = "进攻确认"
        elif score >= 50:
            attack = max(latest.close + atr * 0.55, recent_high * 1.001)
            watch_low = max(recent_low, latest.close - atr * 1.0)
            watch_high = latest.close + atr * 0.8
            defense = max(recent_low, latest.close - atr * 1.7)
            mode = "观察等待"
        else:
            attack = max(latest.close + atr * 0.9, recent_high * 1.004)
            watch_low = max(recent_low, latest.close - atr * 0.7)
            watch_high = latest.close + atr * 0.45
            defense = min(recent_low, latest.close - atr * 1.2)
            mode = "防守优先"

        watch_low, watch_high = sorted((watch_low, watch_high))
        risk_pct = ((latest.close - defense) / latest.close * 100.0) if latest.close > 1e-9 else 0.0
        return {
            "mode": mode,
            "watch_low": watch_low,
            "watch_high": watch_high,
            "attack": attack,
            "defense": defense,
            "risk_pct": max(risk_pct, 0.0),
            "atr": atr,
        }

    @staticmethod
    def _format_market_trade_zone(zone: dict[str, float | str] | None) -> str:
        if not zone:
            return "交易区间 待更多K线确认"
        return (
            f"交易区间 {zone['mode']} | 观察 {float(zone['watch_low']):.2f}-{float(zone['watch_high']):.2f} | "
            f"进攻确认 {float(zone['attack']):.2f} | 防守 {float(zone['defense']):.2f} | 风险 {float(zone['risk_pct']):.1f}%"
        )

    def _market_history_target_size(self, total_bars: int, timeframe: str | None = None) -> int:
        if total_bars <= 0:
            return 0
        normalized = self._normalize_market_timeframe(timeframe)
        if self._is_intraday_market_timeframe(normalized):
            history_sizes = {"近1月": 48, "近3月": 96, "近1年": 240, "近3年": 240, "全部": total_bars}
            minimum = 16
        elif normalized == "周线":
            history_sizes = {"近1月": 8, "近3月": 16, "近1年": 52, "近3年": 156, "全部": total_bars}
            minimum = 8
        elif normalized == "月线":
            history_sizes = {"近1月": 6, "近3月": 12, "近1年": 24, "近3年": 36, "全部": total_bars}
            minimum = 6
        else:
            history_sizes = {"近1月": 22, "近3月": 66, "近1年": 250, "近3年": 750, "全部": total_bars}
            minimum = 20
        target_size = history_sizes.get(getattr(self, "market_history_window", "近1年"), history_sizes.get("近1年", total_bars))
        return max(minimum, min(target_size, total_bars))

    @staticmethod
    def _chart_datetime_from_label(label: str) -> QDateTime:
        for pattern in ("yyyy-MM-dd hh:mm", "yyyy-MM-dd"):
            parsed = QDateTime.fromString(label, pattern)
            if parsed.isValid():
                return parsed
        if ":" in label and len(label) == 5:
            parsed = QDateTime.fromString(f"{datetime.now().strftime('%Y-%m-%d')} {label}", "yyyy-MM-dd hh:mm")
            if parsed.isValid():
                return parsed
        return QDateTime.currentDateTime()

    def _market_axis_format(self, timeframe: str | None = None) -> str:
        normalized = self._normalize_market_timeframe(timeframe)
        if self._is_intraday_market_timeframe(normalized):
            return "hh:mm"
        if normalized == "月线":
            return "yyyy-MM"
        return "MM-dd"

    @staticmethod
    def _moving_average_values(values: list[float], window: int) -> list[float | None]:
        if window <= 0:
            return [None for _ in values]
        result: list[float | None] = []
        running = 0.0
        for index, value in enumerate(values):
            running += value
            if index >= window:
                running -= values[index - window]
            result.append(running / window if index + 1 >= window else None)
        return result

    @staticmethod
    def _compact_number(value: float) -> str:
        absolute = abs(float(value or 0.0))
        if absolute >= 1e8:
            return f"{value / 1e8:.2f}亿"
        if absolute >= 1e4:
            return f"{value / 1e4:.2f}万"
        return f"{value:,.0f}"

    def _connect_market_chart_hover_links(self) -> None:
        if getattr(self, "_market_chart_hover_links_ready", False):
            return
        self._market_chart_hover_links_ready = True
        views = [
            getattr(self, "daily_chart_view", None),
            getattr(self, "fund_chart_view", None),
            getattr(self, "indicator_chart_view", None),
        ]
        for source in views:
            if source is None or not hasattr(source, "hoverKeyChanged"):
                continue
            source.hoverKeyChanged.connect(lambda key, current=source: self._sync_market_hover_views(current, key))

    def _sync_market_hover_views(self, source_view, key: str) -> None:
        for target in [
            getattr(self, "daily_chart_view", None),
            getattr(self, "fund_chart_view", None),
            getattr(self, "indicator_chart_view", None),
        ]:
            if target is None or target is source_view or not hasattr(target, "sync_hover_key"):
                continue
            target.sync_hover_key(key)

    def _update_intraday_chart(self, symbol: str, snapshot, chart_series) -> None:
        if not hasattr(self, "intraday_chart_view"):
            return
        chart = QChart()
        timeframe = self._normalize_market_timeframe()
        intraday_title = "市场代理走势" if not self._is_intraday_market_timeframe(timeframe) else f"{timeframe} 分时走势"
        self._style_dark_chart(chart, intraday_title)
        price_series = QLineSeries()
        price_series.setPen(QPen(QColor("#57c7ff"), 2.4))
        reference_series = QLineSeries()
        reference_series.setPen(QPen(QColor("#f4c96a"), 1.2, Qt.DashLine))

        if self._is_intraday_market_timeframe(timeframe):
            point_pairs = self._build_intraday_source_points(symbol, snapshot, chart_series, target_points=240)
            points = [type("P", (), {"t": t, "v": v})() for t, v in point_pairs]
            proxy_points = []
            proxy_base = 0.0
        else:
            proxy_points, proxy_base = self._build_market_proxy_points()
            points = proxy_points if proxy_points else (list(getattr(chart_series, "intraday_price", [])) if chart_series else [])
            if not points and snapshot is not None:
                base = snapshot.prev_close or snapshot.latest_price
                pseudo = [
                    base,
                    snapshot.open_price or base,
                    snapshot.low_price or base * 0.99,
                    (snapshot.low_price + snapshot.open_price) / 2 if snapshot.low_price and snapshot.open_price else base,
                    (snapshot.high_price + snapshot.latest_price) / 2 if snapshot.high_price and snapshot.latest_price else base,
                    snapshot.high_price or base * 1.01,
                    snapshot.latest_price or base,
                ]
                points = [type("P", (), {"t": f"{index}", "v": value})() for index, value in enumerate(pseudo)]

        values = []
        base_price = proxy_base if proxy_points else (
            snapshot.prev_close if snapshot and snapshot.prev_close > 0 else (points[0].v if points else 0.0)
        )
        for index, point in enumerate(points):
            price_series.append(index, point.v)
            reference_series.append(index, base_price)
            values.append(point.v)

        chart.addSeries(price_series)
        if points:
            chart.addSeries(reference_series)

        axis_x = QValueAxis()
        self._style_chart_axis(axis_x, labels_visible=False, compact=True)
        axis_y = QValueAxis()
        self._style_chart_axis(axis_y, compact=True)
        if values:
            low = min(values + [base_price])
            high = max(values + [base_price])
            pad = max((high - low) * 0.1, base_price * 0.003 if base_price else 0.03)
            axis_y.setRange(low - pad, high + pad)
            axis_x.setRange(0, max(len(points) - 1, 1))
        chart.addAxis(axis_x, Qt.AlignBottom)
        chart.addAxis(axis_y, Qt.AlignRight)
        price_series.attachAxis(axis_x)
        price_series.attachAxis(axis_y)
        if points:
            reference_series.attachAxis(axis_x)
            reference_series.attachAxis(axis_y)
        self.intraday_chart_view.setChart(chart)
        if hasattr(self.intraday_chart_view, "set_chart_context"):
            labels = [getattr(point, "t", str(index)) for index, point in enumerate(points)]
            payloads = [
                [
                    f"时间: {label}",
                    f"价格: {float(getattr(point, 'v', 0.0) or 0.0):.2f}",
                    f"昨收基准: {base_price:.2f}",
                    f"偏离: {((float(getattr(point, 'v', 0.0) or 0.0) - base_price) / base_price * 100.0 if base_price else 0.0):+.2f}%",
                ]
                for label, point in zip(labels, points)
            ]
            self.intraday_chart_view.set_chart_context(
                x_label="时间",
                y_label="价格",
                y_suffix="",
                x_kind="category",
                x_labels=labels,
                x_values=list(range(len(labels))),
                y_values=[float(getattr(point, "v", 0.0) or 0.0) for point in points],
                hover_keys=labels,
                hover_payloads=payloads,
            )

    def _update_daily_chart(self, symbol: str) -> None:
        if not hasattr(self, "daily_chart_view"):
            return
        chart_series = getattr(self.market_screen_result, "chart_series_by_symbol", {}).get(symbol)
        snapshot = getattr(self.market_screen_result, "snapshots", {}).get(symbol)
        bars = self._market_chart_bars(symbol, snapshot, chart_series)
        chart = QChart()
        timeframe = self._normalize_market_timeframe()
        self._style_dark_chart(chart, "日线主图" if timeframe == "日线" else f"{timeframe} 主图")

        candle_series = QCandlestickSeries()
        candle_series.setIncreasingColor(QColor("#3fd59a"))
        candle_series.setDecreasingColor(QColor("#ff6b6b"))
        candle_series.setBodyOutlineVisible(True)

        ma_fast_series = QLineSeries()
        ma_fast_series.setPen(QPen(QColor("#ffd166"), 1.5))
        ma_fast_series.setName("MA5")
        ma_slow_series = QLineSeries()
        ma_slow_series.setPen(QPen(QColor("#9fb0c2"), 1.4))
        ma_slow_series.setName("MA20")
        boll_mid_series = QLineSeries()
        boll_mid_series.setPen(QPen(QColor("#7ed7ff"), 1.3))
        boll_mid_series.setName("BOLL 中轨")
        boll_upper_series = QLineSeries()
        boll_upper_series.setPen(QPen(QColor("#ffb867"), 1.1, Qt.DashLine))
        boll_upper_series.setName("BOLL 上轨")
        boll_lower_series = QLineSeries()
        boll_lower_series.setPen(QPen(QColor("#59d998"), 1.1, Qt.DashLine))
        boll_lower_series.setName("BOLL 下轨")
        high_band_series = QLineSeries()
        high_band_series.setPen(QPen(QColor("#ff8f6b"), 1.0, Qt.DashLine))
        high_band_series.setName("20周期高点")
        low_band_series = QLineSeries()
        low_band_series.setPen(QPen(QColor("#56d39b"), 1.0, Qt.DashLine))
        low_band_series.setName("20周期低点")
        breakout_series = QLineSeries()
        breakout_series.setPen(QPen(QColor("#7ed7ff"), 1.2, Qt.DotLine))
        breakout_series.setName("前10周期突破基准")
        breakout_up_series = QScatterSeries()
        breakout_up_series.setName("突破信号")
        breakout_up_series.setColor(QColor("#3fd59a"))
        breakout_up_series.setBorderColor(QColor("#d8ffe8"))
        breakout_up_series.setMarkerSize(9.0)
        breakout_down_series = QScatterSeries()
        breakout_down_series.setName("回落信号")
        breakout_down_series.setColor(QColor("#ff7b7b"))
        breakout_down_series.setBorderColor(QColor("#ffd6d6"))
        breakout_down_series.setMarkerSize(8.0)
        swing_high_series = QScatterSeries()
        swing_high_series.setName("摆点高")
        swing_high_series.setColor(QColor("#ffb867"))
        swing_high_series.setBorderColor(QColor("#ffe6bf"))
        swing_high_series.setMarkerSize(7.5)
        swing_low_series = QScatterSeries()
        swing_low_series.setName("摆点低")
        swing_low_series.setColor(QColor("#59d998"))
        swing_low_series.setBorderColor(QColor("#d8ffe8"))
        swing_low_series.setMarkerSize(7.5)
        watch_low_series = QLineSeries()
        watch_low_series.setName("观察下沿")
        watch_low_series.setPen(QPen(QColor("#5fb3ff"), 1.0, Qt.DashLine))
        watch_high_series = QLineSeries()
        watch_high_series.setName("观察上沿")
        watch_high_series.setPen(QPen(QColor("#5fb3ff"), 1.0, Qt.DashLine))
        attack_series = QLineSeries()
        attack_series.setName("进攻确认")
        attack_series.setPen(QPen(QColor("#3fd59a"), 1.2, Qt.DashDotLine))
        defense_series = QLineSeries()
        defense_series.setName("防守线")
        defense_series.setPen(QPen(QColor("#ff6b6b"), 1.2, Qt.DashDotLine))
        candle_tag_up_series = QScatterSeries()
        candle_tag_up_series.setName("强势K线")
        candle_tag_up_series.setColor(QColor("#7ed7ff"))
        candle_tag_up_series.setBorderColor(QColor("#dff4ff"))
        candle_tag_up_series.setMarkerSize(8.5)
        candle_tag_down_series = QScatterSeries()
        candle_tag_down_series.setName("风险K线")
        candle_tag_down_series.setColor(QColor("#ff8f6b"))
        candle_tag_down_series.setBorderColor(QColor("#ffe1d6"))
        candle_tag_down_series.setMarkerSize(8.5)

        visible_bars, _ = self._windowed_market_bars(symbol, bars, [])
        swing_points = self._market_swing_points(visible_bars)
        swing_point_by_index = {index: (kind, value, label) for index, kind, value, label in swing_points}
        dates = []
        highs = []
        lows = []
        closes: list[float] = []
        ma_fast_values: list[float | None] = []
        ma_slow_values: list[float | None] = []
        boll_mid_values: list[float | None] = []
        boll_upper_values: list[float | None] = []
        boll_lower_values: list[float | None] = []
        recent_high_values: list[float | None] = []
        recent_low_values: list[float | None] = []
        channel_positions: list[str | None] = []
        channel_position_ratios: list[float | None] = []
        breakout_values: list[float | None] = []
        breakout_states: list[str | None] = []
        breakout_distance_values: list[float | None] = []
        candle_tags: list[str | None] = []
        candle_tag_details: list[str | None] = []
        structure_summary = self._market_structure_summary(visible_bars)
        rhythm_summary = self._market_rhythm_summary(visible_bars)
        preliminary_resonance = self._market_multi_timeframe_summary(symbol)
        preliminary_score = self._market_chart_score_summary(structure_summary, rhythm_summary, "关键K线 待识别", preliminary_resonance)
        trade_zone = self._market_trade_zone_summary(visible_bars, preliminary_score)
        trade_zone_text = self._format_market_trade_zone(trade_zone)
        for index, bar in enumerate(visible_bars):
            dt = self._chart_datetime_from_label(bar.date)
            ts = float(dt.toMSecsSinceEpoch())
            candle_series.append(QCandlestickSet(bar.open, bar.high, bar.low, bar.close, ts))
            dates.append(ts)
            highs.append(bar.high)
            lows.append(bar.low)
            closes.append(bar.close)
            if "MA" in self.market_overlay_modes:
                if len(closes) >= 5:
                    ma_fast_value = sum(closes[-5:]) / 5
                    ma_fast_series.append(ts, ma_fast_value)
                else:
                    ma_fast_value = None
                if len(closes) >= 20:
                    ma_slow_value = sum(closes[-20:]) / 20
                    ma_slow_series.append(ts, ma_slow_value)
                else:
                    ma_slow_value = None
            else:
                ma_fast_value = None
                ma_slow_value = None
            ma_fast_values.append(ma_fast_value)
            ma_slow_values.append(ma_slow_value)
            if "BOLL" in self.market_overlay_modes and len(closes) >= 20:
                window = closes[-20:]
                mid = sum(window) / len(window)
                variance = sum((value - mid) ** 2 for value in window) / len(window)
                std = variance ** 0.5
                boll_mid_series.append(ts, mid)
                boll_upper_series.append(ts, mid + std * 2)
                boll_lower_series.append(ts, mid - std * 2)
                boll_mid_values.append(mid)
                boll_upper_values.append(mid + std * 2)
                boll_lower_values.append(mid - std * 2)
            else:
                boll_mid_values.append(None)
                boll_upper_values.append(None)
                boll_lower_values.append(None)
            if len(highs) >= 20:
                recent_high = max(highs[-20:])
                recent_low = min(lows[-20:])
                recent_high_values.append(recent_high)
                recent_low_values.append(recent_low)
                channel_position, channel_ratio = self._market_channel_position(bar, recent_high, recent_low)
                channel_positions.append(channel_position)
                channel_position_ratios.append(channel_ratio)
                if "HIGHLOW" in self.market_overlay_modes:
                    high_band_series.append(ts, recent_high)
                    low_band_series.append(ts, recent_low)
            else:
                recent_high_values.append(None)
                recent_low_values.append(None)
                channel_positions.append(None)
                channel_position_ratios.append(None)
            breakout_value = self._market_breakout_reference(visible_bars, index, lookback=10)
            breakout_values.append(breakout_value)
            if "BREAK" in self.market_overlay_modes and breakout_value is not None:
                breakout_series.append(ts, breakout_value)
            previous_close = visible_bars[index - 1].close if index > 0 else None
            breakout_state, breakout_distance = self._classify_market_breakout(bar, breakout_value, previous_close)
            breakout_states.append(breakout_state)
            breakout_distance_values.append(breakout_distance)
            candle_tag, candle_tag_detail = self._classify_market_candle_tag(
                bar,
                visible_bars[:index],
                breakout_value,
                breakout_state,
            )
            candle_tags.append(candle_tag)
            candle_tag_details.append(candle_tag_detail)
            if "BREAK" in self.market_overlay_modes and breakout_value is not None:
                if breakout_state in {"向上突破", "回踩站稳", "强势站上"}:
                    breakout_up_series.append(ts, bar.close)
                elif breakout_state == "冲高回落":
                    breakout_down_series.append(ts, bar.close)
            if candle_tag is not None:
                if candle_tag in {"放量突破", "缩量回踩", "长下影承接"}:
                    candle_tag_up_series.append(ts, bar.close)
                else:
                    candle_tag_down_series.append(ts, bar.close)
            if "HIGHLOW" in self.market_overlay_modes and index in swing_point_by_index:
                swing_kind, swing_value, _ = swing_point_by_index[index]
                if swing_kind == "high":
                    swing_high_series.append(ts, swing_value)
                else:
                    swing_low_series.append(ts, swing_value)
            if trade_zone is not None:
                watch_low_series.append(ts, float(trade_zone["watch_low"]))
                watch_high_series.append(ts, float(trade_zone["watch_high"]))
                attack_series.append(ts, float(trade_zone["attack"]))
                defense_series.append(ts, float(trade_zone["defense"]))
        latest_candle_tag_summary = self._latest_market_candle_tag_summary(visible_bars, breakout_values, breakout_states)

        chart.addSeries(candle_series)
        if "MA" in self.market_overlay_modes and ma_fast_series.count():
            chart.addSeries(ma_fast_series)
            chart.addSeries(ma_slow_series)
        if "BOLL" in self.market_overlay_modes and boll_mid_series.count():
            chart.addSeries(boll_mid_series)
            chart.addSeries(boll_upper_series)
            chart.addSeries(boll_lower_series)
        if "HIGHLOW" in self.market_overlay_modes and high_band_series.count():
            chart.addSeries(high_band_series)
            chart.addSeries(low_band_series)
        if "HIGHLOW" in self.market_overlay_modes and swing_high_series.count():
            chart.addSeries(swing_high_series)
        if "HIGHLOW" in self.market_overlay_modes and swing_low_series.count():
            chart.addSeries(swing_low_series)
        if trade_zone is not None and watch_low_series.count():
            chart.addSeries(watch_low_series)
            chart.addSeries(watch_high_series)
            chart.addSeries(attack_series)
            chart.addSeries(defense_series)
        if candle_tag_up_series.count():
            chart.addSeries(candle_tag_up_series)
        if candle_tag_down_series.count():
            chart.addSeries(candle_tag_down_series)
        if "BREAK" in self.market_overlay_modes and breakout_series.count():
            chart.addSeries(breakout_series)
        if "BREAK" in self.market_overlay_modes and breakout_up_series.count():
            chart.addSeries(breakout_up_series)
        if "BREAK" in self.market_overlay_modes and breakout_down_series.count():
            chart.addSeries(breakout_down_series)

        axis_x = QDateTimeAxis()
        axis_x.setFormat(self._market_axis_format(timeframe))
        axis_x.setTickCount(6)
        self._style_chart_axis(axis_x, compact=True)

        axis_y = QValueAxis()
        self._style_chart_axis(axis_y, compact=True)
        if highs and lows:
            low = min(lows)
            high = max(highs)
            if trade_zone is not None:
                low = min(low, float(trade_zone["defense"]), float(trade_zone["watch_low"]))
                high = max(high, float(trade_zone["attack"]), float(trade_zone["watch_high"]))
            padding = max((high - low) * 0.08, 0.05)
            axis_y.setRange(low - padding, high + padding)

        chart.addAxis(axis_x, Qt.AlignBottom)
        chart.addAxis(axis_y, Qt.AlignRight)
        attach_series = [candle_series]
        if "MA" in self.market_overlay_modes and ma_fast_series.count():
            attach_series.extend([ma_fast_series, ma_slow_series])
        if "BOLL" in self.market_overlay_modes and boll_mid_series.count():
            attach_series.extend([boll_mid_series, boll_upper_series, boll_lower_series])
        if "HIGHLOW" in self.market_overlay_modes and high_band_series.count():
            attach_series.extend([high_band_series, low_band_series])
        if "HIGHLOW" in self.market_overlay_modes and swing_high_series.count():
            attach_series.append(swing_high_series)
        if "HIGHLOW" in self.market_overlay_modes and swing_low_series.count():
            attach_series.append(swing_low_series)
        if trade_zone is not None and watch_low_series.count():
            attach_series.extend([watch_low_series, watch_high_series, attack_series, defense_series])
        if candle_tag_up_series.count():
            attach_series.append(candle_tag_up_series)
        if candle_tag_down_series.count():
            attach_series.append(candle_tag_down_series)
        if "BREAK" in self.market_overlay_modes and breakout_series.count():
            attach_series.append(breakout_series)
        if "BREAK" in self.market_overlay_modes and breakout_up_series.count():
            attach_series.append(breakout_up_series)
        if "BREAK" in self.market_overlay_modes and breakout_down_series.count():
            attach_series.append(breakout_down_series)
        for series in attach_series:
            series.attachAxis(axis_x)
            series.attachAxis(axis_y)
        if dates:
            axis_x.setRange(QDateTime.fromMSecsSinceEpoch(int(dates[0])), QDateTime.fromMSecsSinceEpoch(int(dates[-1])))

        self.daily_chart_view.setChart(chart)
        if hasattr(self.daily_chart_view, "set_chart_context"):
            tooltip_format = "hh:mm" if self._is_intraday_market_timeframe(timeframe) else ("yyyy-MM" if timeframe == "月线" else "yyyy-MM-dd")
            hover_keys = [bar.date for bar in visible_bars]
            hover_payloads = []
            for index, bar in enumerate(visible_bars):
                prev_close = visible_bars[index - 1].close if index > 0 else (snapshot.prev_close if snapshot is not None else bar.open)
                pct = ((bar.close - prev_close) / prev_close * 100.0) if prev_close else 0.0
                lines = [
                    f"时间: {bar.date}",
                    f"开/高/低/收: {bar.open:.2f} / {bar.high:.2f} / {bar.low:.2f} / {bar.close:.2f}",
                    f"涨跌: {pct:+.2f}%",
                    f"成交量: {self._compact_number(bar.volume)}",
                ]
                if ma_fast_values[index] is not None:
                    lines.append(f"MA5: {ma_fast_values[index]:.2f}")
                if ma_slow_values[index] is not None:
                    lines.append(f"MA20: {ma_slow_values[index]:.2f}")
                if boll_mid_values[index] is not None:
                    lines.append(
                        f"BOLL: {boll_mid_values[index]:.2f} / {boll_upper_values[index]:.2f} / {boll_lower_values[index]:.2f}"
                    )
                if recent_high_values[index] is not None:
                    lines.append(f"20周期高低: {recent_high_values[index]:.2f} / {recent_low_values[index]:.2f}")
                if channel_positions[index] is not None and channel_position_ratios[index] is not None:
                    lines.append(f"通道位置: {channel_positions[index]} | {channel_position_ratios[index] * 100:.0f}%")
                if index in swing_point_by_index:
                    lines.append(swing_point_by_index[index][2])
                if breakout_values[index] is not None:
                    lines.append(f"前10周期突破基准: {breakout_values[index]:.2f}")
                if breakout_states[index] is not None and breakout_distance_values[index] is not None:
                    lines.append(f"突破状态: {breakout_states[index]} | 偏离 {breakout_distance_values[index]:+.2f}%")
                if candle_tags[index] is not None:
                    detail = candle_tag_details[index] or "等待细节补充"
                    lines.append(f"关键K线: {candle_tags[index]} | {detail}")
                if index == len(visible_bars) - 1:
                    lines.append(structure_summary)
                    lines.append(rhythm_summary)
                    lines.append(latest_candle_tag_summary)
                    lines.append(trade_zone_text)
                hover_payloads.append(lines)
            self.daily_chart_view.set_chart_context(
                x_label="时间",
                y_label="价格",
                y_suffix="",
                x_kind="datetime",
                datetime_format=tooltip_format,
                x_values=dates,
                y_values=closes,
                hover_keys=hover_keys,
                hover_payloads=hover_payloads,
            )
        self._connect_market_chart_hover_links()

    def _windowed_market_bars(
        self,
        symbol: str,
        bars: list[PriceBar] | None = None,
        analyses: list[DailyAnalysis] | None = None,
    ) -> tuple[list[PriceBar], list[DailyAnalysis]]:
        full_bars = list(bars if bars is not None else self.universe_bars.get(symbol, []))
        full_analyses = list(analyses if analyses is not None else self.universe_analyses.get(symbol, []))
        if not full_bars:
            return [], []
        target_size = self._market_history_target_size(len(full_bars))
        step = max(4 if self._is_intraday_market_timeframe() else 1, target_size // 3)
        max_offset = max((len(full_bars) - target_size + step - 1) // step, 0)
        self.market_chart_offset = max(0, min(getattr(self, "market_chart_offset", 0), max_offset))

        end_index = len(full_bars) - self.market_chart_offset * step
        end_index = max(target_size, min(end_index, len(full_bars)))
        start_index = max(0, end_index - target_size)
        return full_bars[start_index:end_index], full_analyses[start_index:end_index]

    def _update_indicator_chart(self, symbol: str) -> None:
        if not hasattr(self, "indicator_chart_view"):
            return
        chart_series = getattr(self.market_screen_result, "chart_series_by_symbol", {}).get(symbol)
        snapshot = getattr(self.market_screen_result, "snapshots", {}).get(symbol)
        display_bars = self._market_chart_bars(symbol, snapshot, chart_series)
        bars, _ = self._windowed_market_bars(symbol, display_bars, [])
        chart = QChart()
        indicator_name = getattr(self, "market_secondary_indicator_mode", "MACD") or "MACD"
        self._style_dark_chart(chart, f"{indicator_name} 副图")
        if not bars:
            self.indicator_chart_view.setChart(chart)
            return

        closes = [bar.close for bar in bars]
        recent_bars = bars[-min(60 if self._is_intraday_market_timeframe() else 30, len(bars)):]
        categories = [bar.date[-5:] if ":" in bar.date else bar.date[5:] for bar in recent_bars]
        recent_closes = [bar.close for bar in recent_bars]

        if indicator_name == "VOL":
            positive = QBarSet("放量")
            negative = QBarSet("缩量")
            positive.setColor(QColor("#ff6b6b"))
            negative.setColor(QColor("#3fd59a"))
            volumes = [float(bar.volume or 0.0) for bar in recent_bars]
            ma5_values = self._moving_average_values(volumes, 5)
            ma10_values = self._moving_average_values(volumes, 10)
            ma5_series = QLineSeries()
            ma10_series = QLineSeries()
            ma5_series.setPen(QPen(QColor("#ffd166"), 1.6))
            ma10_series.setPen(QPen(QColor("#7ed7ff"), 1.4))
            for index, bar in enumerate(recent_bars):
                volume = volumes[index]
                positive.append(volume if bar.close >= bar.open else 0.0)
                negative.append(volume if bar.close < bar.open else 0.0)
                if ma5_values[index] is not None:
                    ma5_series.append(index, ma5_values[index])
                if ma10_values[index] is not None:
                    ma10_series.append(index, ma10_values[index])
            bars_series = QBarSeries()
            bars_series.append(positive)
            bars_series.append(negative)
            chart.addSeries(bars_series)
            if ma5_series.count():
                chart.addSeries(ma5_series)
            if ma10_series.count():
                chart.addSeries(ma10_series)
            axis_x = QBarCategoryAxis()
            axis_x.append(categories or ["--"])
            self._style_chart_axis(axis_x, compact=True)
            axis_y = QValueAxis()
            upper = max(volumes) if volumes else 1.0
            if ma10_values:
                upper = max(upper, max((value or 0.0) for value in ma10_values))
            axis_y.setRange(0, upper * 1.2 if upper > 0 else 1.0)
            self._style_chart_axis(axis_y, compact=True)
            chart.addAxis(axis_x, Qt.AlignBottom)
            chart.addAxis(axis_y, Qt.AlignRight)
            bars_series.attachAxis(axis_x)
            bars_series.attachAxis(axis_y)
            if ma5_series.count():
                ma5_series.attachAxis(axis_x)
                ma5_series.attachAxis(axis_y)
            if ma10_series.count():
                ma10_series.attachAxis(axis_x)
                ma10_series.attachAxis(axis_y)
            hover_payloads = []
            for index, label in enumerate(categories):
                lines = [f"时间: {label}", f"成交量: {self._compact_number(volumes[index])}"]
                if ma5_values[index] is not None:
                    lines.append(f"VOL MA5: {self._compact_number(ma5_values[index] or 0.0)}")
                if ma10_values[index] is not None:
                    lines.append(f"VOL MA10: {self._compact_number(ma10_values[index] or 0.0)}")
                hover_payloads.append(lines)
            context_payload = {
                "x_label": "周期",
                "y_label": "VOL",
                "y_suffix": "",
                "x_kind": "category",
                "x_labels": categories or ["--"],
                "x_values": list(range(len(categories))),
                "y_values": volumes or [0.0],
                "hover_keys": [bar.date for bar in recent_bars] if recent_bars else (categories or ["--"]),
                "hover_payloads": hover_payloads,
            }
        elif indicator_name == "RSI":
            series = QLineSeries()
            series.setPen(QPen(QColor("#57c7ff"), 2.0))
            series.setName("RSI")
            values = []
            for index in range(1, len(recent_closes)):
                window = recent_closes[max(0, index - 6): index + 1]
                gains = []
                losses = []
                for left, right in zip(window[:-1], window[1:]):
                    diff = right - left
                    gains.append(max(diff, 0.0))
                    losses.append(abs(min(diff, 0.0)))
                avg_gain = sum(gains) / max(len(gains), 1)
                avg_loss = sum(losses) / max(len(losses), 1)
                rs = avg_gain / avg_loss if avg_loss else 100.0
                rsi = 100.0 - (100.0 / (1.0 + rs))
                series.append(index, rsi)
                values.append(rsi)
            chart.addSeries(series)
            axis_x = QValueAxis()
            self._style_chart_axis(axis_x, labels_visible=False, compact=True)
            axis_y = QValueAxis()
            axis_y.setRange(0, 100)
            self._style_chart_axis(axis_y, compact=True)
            chart.addAxis(axis_x, Qt.AlignBottom)
            chart.addAxis(axis_y, Qt.AlignRight)
            series.attachAxis(axis_x)
            series.attachAxis(axis_y)
            axis_x.setRange(0, max(series.count() - 1, 1))
            hover_payloads = []
            for index, label in enumerate(categories[1:], start=0):
                value = series.at(index).y() if index < series.count() else 0.0
                hover_payloads.append([f"时间: {label}", f"RSI: {value:.2f}"])
            context_payload = {
                "x_label": "周期",
                "y_label": "RSI",
                "y_suffix": "",
                "x_kind": "category",
                "x_labels": categories[1:] or ["--"],
                "x_values": list(range(len(categories[1:]))),
                "y_values": [series.at(index).y() if index < series.count() else 0.0 for index in range(len(categories[1:]))],
                "hover_keys": [bar.date for bar in recent_bars[1:]] if len(recent_bars) > 1 else (categories[1:] or ["--"]),
                "hover_payloads": hover_payloads,
            }
        elif indicator_name == "KDJ":
            k_series = QLineSeries()
            d_series = QLineSeries()
            j_series = QLineSeries()
            k_series.setPen(QPen(QColor("#57c7ff"), 1.8))
            d_series.setPen(QPen(QColor("#ffd166"), 1.8))
            j_series.setPen(QPen(QColor("#ff7b72"), 1.6))
            k_value = 50.0
            d_value = 50.0
            for index in range(len(bars[-30:])):
                scope = bars[max(0, len(bars) - 30 + index - 8): len(bars) - 30 + index + 1]
                if not scope:
                    continue
                high = max(item.high for item in scope)
                low = min(item.low for item in scope)
                close = scope[-1].close
                rsv = 50.0 if high == low else (close - low) / (high - low) * 100.0
                k_value = k_value * 2 / 3 + rsv / 3
                d_value = d_value * 2 / 3 + k_value / 3
                j_value = 3 * k_value - 2 * d_value
                k_series.append(index, k_value)
                d_series.append(index, d_value)
                j_series.append(index, j_value)
            for series in [k_series, d_series, j_series]:
                chart.addSeries(series)
            axis_x = QValueAxis()
            self._style_chart_axis(axis_x, labels_visible=False, compact=True)
            axis_y = QValueAxis()
            axis_y.setRange(0, 120)
            self._style_chart_axis(axis_y, compact=True)
            chart.addAxis(axis_x, Qt.AlignBottom)
            chart.addAxis(axis_y, Qt.AlignRight)
            for series in [k_series, d_series, j_series]:
                series.attachAxis(axis_x)
                series.attachAxis(axis_y)
            axis_x.setRange(0, max(k_series.count() - 1, 1))
            hover_payloads = []
            for index in range(len(categories)):
                k_value = k_series.at(index).y() if index < k_series.count() else 0.0
                d_value = d_series.at(index).y() if index < d_series.count() else 0.0
                j_value = j_series.at(index).y() if index < j_series.count() else 0.0
                hover_payloads.append([f"时间: {categories[index]}", f"K: {k_value:.2f}", f"D: {d_value:.2f}", f"J: {j_value:.2f}"])
            context_payload = {
                "x_label": "周期",
                "y_label": "KDJ",
                "y_suffix": "",
                "x_kind": "category",
                "x_labels": categories or ["--"],
                "x_values": list(range(len(categories))),
                "y_values": [k_series.at(index).y() if index < k_series.count() else 0.0 for index in range(len(categories))],
                "hover_keys": [bar.date for bar in recent_bars] if recent_bars else (categories or ["--"]),
                "hover_payloads": hover_payloads,
            }
        else:
            dif_series = QLineSeries()
            dea_series = QLineSeries()
            dif_series.setPen(QPen(QColor("#57c7ff"), 1.8))
            dea_series.setPen(QPen(QColor("#ffb867"), 1.8))
            positive = QBarSet("红柱")
            negative = QBarSet("绿柱")
            positive.setColor(QColor("#ff6b6b"))
            negative.setColor(QColor("#45d795"))
            ema12 = recent_closes[0]
            ema26 = recent_closes[0]
            dea = 0.0
            values = []
            for index, close in enumerate(recent_closes):
                ema12 = ema12 * 11 / 13 + close * 2 / 13
                ema26 = ema26 * 25 / 27 + close * 2 / 27
                dif = ema12 - ema26
                dea = dea * 8 / 10 + dif * 2 / 10
                hist = (dif - dea) * 2
                dif_series.append(index, dif)
                dea_series.append(index, dea)
                positive.append(max(hist, 0.0))
                negative.append(abs(min(hist, 0.0)))
                values.extend([abs(dif), abs(dea), abs(hist)])
            bars_series = QBarSeries()
            bars_series.append(positive)
            bars_series.append(negative)
            chart.addSeries(bars_series)
            chart.addSeries(dif_series)
            chart.addSeries(dea_series)
            axis_x = QBarCategoryAxis()
            axis_x.append(categories or ["--"])
            self._style_chart_axis(axis_x, compact=True)
            axis_y = QValueAxis()
            upper = max(values) * 1.3 if values else 1.0
            axis_y.setRange(-upper, upper)
            self._style_chart_axis(axis_y, compact=True)
            chart.addAxis(axis_x, Qt.AlignBottom)
            chart.addAxis(axis_y, Qt.AlignRight)
            for series in [bars_series, dif_series, dea_series]:
                series.attachAxis(axis_x)
                series.attachAxis(axis_y)
            hover_payloads = []
            macd_values: list[float] = []
            for index in range(len(categories)):
                dif_value = dif_series.at(index).y() if index < dif_series.count() else 0.0
                dea_value = dea_series.at(index).y() if index < dea_series.count() else 0.0
                hist_value = positive.at(index) if index < positive.count() else -(negative.at(index) if index < negative.count() else 0.0)
                macd_values.append(hist_value)
                hover_payloads.append([f"时间: {categories[index]}", f"DIF: {dif_value:.3f}", f"DEA: {dea_value:.3f}", f"MACD: {hist_value:.3f}"])
            context_payload = {
                "x_label": "周期",
                "y_label": "MACD",
                "y_suffix": "",
                "x_kind": "category",
                "x_labels": categories or ["--"],
                "x_values": list(range(len(categories))),
                "y_values": macd_values or [0.0],
                "hover_keys": [bar.date for bar in recent_bars] if recent_bars else (categories or ["--"]),
                "hover_payloads": hover_payloads,
            }

        self.indicator_chart_view.setChart(chart)
        if hasattr(self.indicator_chart_view, "set_chart_context"):
            self.indicator_chart_view.set_chart_context(**context_payload)
        self._connect_market_chart_hover_links()

    def _update_price_chart(self, symbol: str) -> None:
        self._update_daily_chart(symbol)

    def _update_fund_chart(self, symbol: str, chart_series) -> None:
        if not hasattr(self, "fund_chart_view"):
            return
        chart = QChart()
        timeframe = self._normalize_market_timeframe()
        if self._is_intraday_market_timeframe(timeframe):
            self._style_dark_chart(chart, "主力资金" if timeframe == "分时" else f"{timeframe} 资金")
            points = list(getattr(chart_series, "capital_flow", [])) if chart_series else []

            positive = QBarSet("流入")
            negative = QBarSet("流出")
            positive.setColor(QColor("#25d07f"))
            negative.setColor(QColor("#ff5e57"))
            categories = []
            values = []
            for point in points[-24:]:
                value = point.v
                categories.append(point.t)
                positive.append(max(value, 0.0))
                negative.append(abs(min(value, 0.0)))
                values.append(abs(value))

            series = QBarSeries()
            series.append(positive)
            series.append(negative)
            chart.addSeries(series)

            axis_x = QBarCategoryAxis()
            axis_x.append(categories or ["00"])
            self._style_chart_axis(axis_x, compact=True)
            axis_y = QValueAxis()
            self._style_chart_axis(axis_y, compact=True)
            axis_y.setRange(0, max(values) * 1.25 if values else 1.0)
            chart.addAxis(axis_x, Qt.AlignBottom)
            chart.addAxis(axis_y, Qt.AlignRight)
            series.attachAxis(axis_x)
            series.attachAxis(axis_y)
        else:
            snapshot = getattr(self.market_screen_result, "snapshots", {}).get(symbol)
            display_bars = self._market_chart_bars(symbol, snapshot, chart_series)
            visible_bars, _ = self._windowed_market_bars(symbol, display_bars, [])
            self._style_dark_chart(chart, "成交量" if timeframe == "日线" else f"{timeframe} 成交量")

            rising = QBarSet("放量")
            falling = QBarSet("缩量")
            rising.setColor(QColor("#3fd59a"))
            falling.setColor(QColor("#ff6b6b"))
            categories = []
            volumes: list[float] = []
            for bar in visible_bars:
                categories.append(bar.date[-5:] if ":" in bar.date else bar.date[5:])
                volume = float(bar.volume or 0.0)
                volumes.append(volume)
                rising.append(volume if bar.close >= bar.open else 0.0)
                falling.append(volume if bar.close < bar.open else 0.0)

            series = QBarSeries()
            series.append(rising)
            series.append(falling)
            chart.addSeries(series)

            ma5_values = self._moving_average_values(volumes, 5)
            ma10_values = self._moving_average_values(volumes, 10)
            ma5_series = QLineSeries()
            ma5_series.setPen(QPen(QColor("#ffd166"), 1.6))
            ma10_series = QLineSeries()
            ma10_series.setPen(QPen(QColor("#7ed7ff"), 1.4))
            for index, value in enumerate(ma5_values):
                if value is not None:
                    ma5_series.append(index, value)
            for index, value in enumerate(ma10_values):
                if value is not None:
                    ma10_series.append(index, value)
            if ma5_series.count():
                chart.addSeries(ma5_series)
            if ma10_series.count():
                chart.addSeries(ma10_series)

            axis_x = QBarCategoryAxis()
            axis_x.append(categories or ["--"])
            self._style_chart_axis(axis_x, compact=True)
            axis_y = QValueAxis()
            self._style_chart_axis(axis_y, compact=True)
            upper = max(volumes) if volumes else 1.0
            if ma10_values:
                upper = max(upper, max((value or 0.0) for value in ma10_values))
            axis_y.setRange(0, upper * 1.2 if upper > 0 else 1.0)
            chart.addAxis(axis_x, Qt.AlignBottom)
            chart.addAxis(axis_y, Qt.AlignRight)
            series.attachAxis(axis_x)
            series.attachAxis(axis_y)
            if ma5_series.count():
                ma5_series.attachAxis(axis_x)
                ma5_series.attachAxis(axis_y)
            if ma10_series.count():
                ma10_series.attachAxis(axis_x)
                ma10_series.attachAxis(axis_y)
        self.fund_chart_view.setChart(chart)
        if hasattr(self.fund_chart_view, "set_chart_context"):
            if self._is_intraday_market_timeframe(timeframe):
                hover_payloads = [
                    [f"时间: {label}", f"净流: {(positive.at(index) if index < positive.count() else 0.0) - (negative.at(index) if index < negative.count() else 0.0):.2f} 亿"]
                    for index, label in enumerate(categories or ["00"])
                ]
                self.fund_chart_view.set_chart_context(
                    x_label="时间",
                    y_label="资金",
                    y_suffix=" 亿",
                    x_kind="category",
                    x_labels=categories or ["00"],
                    x_values=list(range(len(categories or ["00"]))),
                    y_values=[(positive.at(index) if index < positive.count() else 0.0) - (negative.at(index) if index < negative.count() else 0.0) for index in range(len(categories or ["00"]))],
                    hover_keys=categories or ["00"],
                    hover_payloads=hover_payloads,
                )
            else:
                hover_payloads = []
                for index, label in enumerate(categories or ["--"]):
                    lines = [f"时间: {label}", f"成交量: {self._compact_number(volumes[index] if index < len(volumes) else 0.0)}"]
                    if index < len(ma5_values) and ma5_values[index] is not None:
                        lines.append(f"VOL MA5: {self._compact_number(ma5_values[index] or 0.0)}")
                    if index < len(ma10_values) and ma10_values[index] is not None:
                        lines.append(f"VOL MA10: {self._compact_number(ma10_values[index] or 0.0)}")
                    hover_payloads.append(lines)
                self.fund_chart_view.set_chart_context(
                    x_label="周期",
                    y_label="成交量",
                    y_suffix="",
                    x_kind="category",
                    x_labels=categories or ["--"],
                    x_values=list(range(len(categories or ["--"]))),
                    y_values=volumes if volumes else [0.0],
                    hover_keys=[bar.date for bar in visible_bars] if visible_bars else (categories or ["--"]),
                    hover_payloads=hover_payloads,
                )
        self._connect_market_chart_hover_links()

    def _update_volume_chart(self, symbol: str) -> None:
        chart_series = getattr(self.market_screen_result, "chart_series_by_symbol", {}).get(symbol)
        self._update_fund_chart(symbol, chart_series)

    def _update_momentum_chart(self, symbol: str, chart_series) -> None:
        if not hasattr(self, "momentum_chart_view"):
            return
        chart = QChart()
        self._style_dark_chart(chart, "龙头动能")
        points = list(getattr(chart_series, "heat_momentum", [])) if chart_series else []

        positive = QBarSet("强势")
        negative = QBarSet("回落")
        positive.setColor(QColor("#ff3b30"))
        negative.setColor(QColor("#00e5ff"))
        categories = []
        values = []
        for point in points[-24:]:
            shifted = point.v - 50.0
            categories.append(point.t)
            positive.append(max(shifted, 0.0))
            negative.append(abs(min(shifted, 0.0)))
            values.append(abs(shifted))

        series = QBarSeries()
        series.append(positive)
        series.append(negative)
        chart.addSeries(series)

        axis_x = QBarCategoryAxis()
        axis_x.append(categories or ["00"])
        self._style_chart_axis(axis_x, compact=True)
        axis_y = QValueAxis()
        self._style_chart_axis(axis_y, compact=True)
        axis_y.setRange(0, max(values) * 1.25 if values else 1.0)
        chart.addAxis(axis_x, Qt.AlignBottom)
        chart.addAxis(axis_y, Qt.AlignRight)
        series.attachAxis(axis_x)
        series.attachAxis(axis_y)
        self.momentum_chart_view.setChart(chart)

    def _update_market_text_panels(self, symbol: str, snapshot, recommendation) -> None:
        symbol_news = list(getattr(self, "news_catalysts", {}).get(symbol, []) or [])
        confidence = news_confidence_label(symbol_news)
        latest_news = symbol_news[0] if symbol_news else None
        profile_loader = getattr(self, "_stock_profile_for_symbol", None)
        profile = profile_loader(symbol) if callable(profile_loader) and symbol else None
        theme_name = (
            getattr(recommendation, "mainline_tag", "") or getattr(recommendation, "theme_name", "") or getattr(snapshot, "strategy_tag", "") or "待确认"
        )
        hype_logic = build_hype_logic_summary(
            theme_name=theme_name,
            catalyst=getattr(recommendation, "catalyst", "") if recommendation is not None else "",
            rationale=getattr(recommendation, "rationale", "") if recommendation is not None else "",
            profile_notes=getattr(profile, "notes", "") if profile is not None else "",
            news_title=getattr(latest_news, "title", "") if latest_news is not None else "",
        )
        logic_lines = build_hype_logic_lines(
            theme_name=theme_name,
            catalyst=getattr(recommendation, "catalyst", "") if recommendation is not None else "",
            rationale=getattr(recommendation, "rationale", "") if recommendation is not None else "",
            profile_notes=getattr(profile, "notes", "") if profile is not None else "",
            news_title=getattr(latest_news, "title", "") if latest_news is not None else "",
            next_focus=getattr(recommendation, "next_focus", "") if recommendation is not None else "",
            risk_flag=getattr(recommendation, "mainline_risk_flag", "") if recommendation is not None else "",
            confidence_label=confidence,
        )
        news_loader = getattr(self, "_news_digest_lines_for_symbol", None)
        news_lines = news_loader(symbol, limit=2) if callable(news_loader) and symbol else []
        if hasattr(self, "overview_command_text"):
            command_lines = ["盘前指挥摘要", ""]
            if recommendation is not None:
                command_lines.extend(
                    [
                        f"焦点标的：{recommendation.stock_name} ({recommendation.stock_id} / {recommendation.symbol})",
                        f"主线：{recommendation.mainline_tag or recommendation.theme_name or '待确认'} | 分层：{getattr(recommendation, 'opportunity_tier', '') or '待确认'}",
                        f"动作：{self._display_action(recommendation.action)} | 主策略：{getattr(recommendation, 'primary_strategy', '') or '掘龙决策'}",
                        f"执行准备：{float(getattr(recommendation, 'execution_readiness', 0.0) or 0.0):.1f} | 置信：{float(getattr(recommendation, 'confidence_score', 0.0) or 0.0):.1f}",
                        f"催化：{recommendation.catalyst or getattr(latest_news, 'title', '') or '等待消息催化'} | {confidence}",
                        f"逻辑：{hype_logic}",
                        f"下一步：{getattr(recommendation, 'next_focus', '') or '先看分时承接、量能和主线持续性'}",
                    ]
                )
            elif snapshot is not None:
                command_lines.extend(
                    [
                        f"焦点标的：{snapshot.stock_name} ({snapshot.stock_id} / {symbol})",
                        f"状态：{snapshot.strategy_tag} | 资金模型：{snapshot.fund_model}",
                        f"热度：{snapshot.heat_score:.1f} | 动能：{snapshot.momentum_bias:.1f}",
                        f"消息：{news_lines[0] if news_lines else '暂无近期催化'}",
                        "动作建议：先看主线、盘口承接和主力净流入，再决定是否进入推荐池。",
                    ]
                )
            else:
                command_lines.extend(
                    [
                        "当前还没有焦点标的。",
                        "建议先刷新市场，再确认主线方向、容量核心和今天最值得跟踪的前排股票。",
                    ]
                )
            self._set_plain_text_if_changed(self.overview_command_text, "\n".join(command_lines))

        if hasattr(self, "overview_execution_text"):
            execution_lines = ["执行路径", ""]
            if recommendation is not None:
                execution_lines.extend(
                    [
                        f"买点：{(recommendation.entry_price or recommendation.close):.2f}",
                        f"止损：{(recommendation.stop_price or recommendation.close * 0.95):.2f}",
                        f"目标：{(recommendation.target_price or recommendation.close * 1.08):.2f}",
                        f"失效条件：{getattr(recommendation, 'invalidation_reason', '') or '跌破防守位或主线切换时重新评估'}",
                        f"逻辑：{hype_logic}",
                        f"验证：{logic_lines[1].split('：', 1)[-1]}",
                    ]
                )
            elif snapshot is not None:
                execution_lines.extend(
                    [
                        f"最新价：{snapshot.latest_price:.2f} | 涨跌幅：{snapshot.pct_change:.2f}%",
                        f"换手：{snapshot.turnover:.2f}% | 主力净流入：{snapshot.main_inflow / 1e8:.2f} 亿",
                        f"消息：{news_lines[0] if news_lines else '等待消息源同步'}",
                        "执行建议：先观察，再等待推荐池和交易计划确认。",
                    ]
                )
            else:
                execution_lines.extend(
                    [
                        "当前还没有可执行路径。",
                        "推荐池和交易计划生成后，这里会同步给出买点、止损、目标和失效条件。",
                    ]
                )
            self._set_plain_text_if_changed(self.overview_execution_text, "\n".join(execution_lines))

        if hasattr(self, "market_capital_text"):
            lines = ["主力控盘画像"]
            if snapshot is not None:
                lines.extend(
                    [
                        f"结论：{snapshot.fund_model} | 净流入 {snapshot.main_inflow / 1e8:.2f} 亿 | 热度 {snapshot.heat_score:.1f}",
                        f"风险：换手 {snapshot.turnover:.2f}% | 成交额 {snapshot.amount / 1e8:.2f} 亿",
                    ]
                )
                if recommendation is not None:
                    lines.append(
                        f"下一步：主策略 {getattr(recommendation, 'primary_strategy', '') or '掘龙决策'} | 决策 {getattr(recommendation, 'dragon_decision_score', recommendation.total_score):.1f}"
                    )
            else:
                lines.extend(
                    [
                        "结论：待资金画像",
                        "风险：当前还没有市场快照",
                        "下一步：刷新市场后补上净流入、换手和热度变化。",
                    ]
                )
            self._set_plain_text_if_changed(self.market_capital_text, "\n".join(lines))
            if hasattr(self, "overview_summary_cards"):
                capital_headline = f"{snapshot.main_inflow / 1e8:.2f} 亿" if snapshot is not None else "--"
                capital_detail = (
                    f"{snapshot.fund_model} / 换手 {snapshot.turnover:.2f}% / 热度 {snapshot.heat_score:.1f}"
                    if snapshot is not None
                    else "等待资金画像数据。"
                )
                self.overview_summary_cards["capital"].set_data(capital_headline, capital_detail)

        if hasattr(self, "market_decision_text"):
            lines = ["龙头状态 / 决策建议"]
            latest_signal = next((item for item in reversed(self.analyses) if item.label != "NONE"), None)
            if recommendation is not None:
                strategy_name = getattr(recommendation, "primary_strategy", "") or "掘龙决策"
                lines.extend(
                    [
                        f"结论：{self._display_action(recommendation.action)} | {strategy_name} | 决策 {getattr(recommendation, 'dragon_decision_score', recommendation.total_score):.1f}",
                        f"风险：买 {(recommendation.entry_price or recommendation.close):.2f} / 止 {(recommendation.stop_price or recommendation.close * 0.95):.2f} / 目 {(recommendation.target_price or recommendation.close * 1.1):.2f}",
                        f"下一步：{getattr(recommendation, 'next_focus', '') or recommendation.catalyst or '先看量价承接'}",
                    ]
                )
            elif latest_signal is not None:
                lines.extend([f"结论：{latest_signal.label}", f"下一步：{latest_signal.reason}"])
            else:
                lines.extend(
                    [
                        "结论：先观察",
                        "风险：当前还没有生成明确决策建议",
                        "下一步：先看主线是否清晰、量价是否匹配，再决定是否进入推荐池。",
                    ]
                )
            self._set_plain_text_if_changed(self.market_decision_text, "\n".join(lines))
            if hasattr(self, "overview_summary_cards"):
                decision_headline = self._display_action(recommendation.action) if recommendation is not None else "观察"
                decision_detail = (
                    f"{getattr(recommendation, 'primary_strategy', '') or '掘龙决策'} / 决策分 {getattr(recommendation, 'dragon_decision_score', recommendation.total_score):.1f}"
                    if recommendation is not None
                    else (latest_signal.label if latest_signal is not None else "等待交易决策生成。")
                )
                self.overview_summary_cards["decision"].set_data(decision_headline, decision_detail)

    def _market_pool_colors(self, row) -> tuple[QColor, QColor]:
        if row.pct_change >= 8:
            return QColor("#2b0909"), QColor("#ff5e57")
        if row.main_inflow > 1.5e8:
            return QColor("#08291d"), QColor("#25d07f")
        if row.turnover >= 10:
            return QColor("#2b2409"), QColor("#f7d354")
        return QColor("#0f1116"), QColor("#d7dce5")

    def _style_dark_chart(self, chart: QChart, title: str) -> None:
        title_font = QFont("Microsoft YaHei UI", 11)
        title_font.setWeight(QFont.DemiBold)
        chart.setTitle(title)
        chart.setTitleFont(title_font)
        chart.setTitleBrush(QColor("#eff5fb"))
        chart.setBackgroundBrush(QColor("#0c1117"))
        chart.setPlotAreaBackgroundVisible(True)
        chart.setPlotAreaBackgroundBrush(QColor("#0a0f15"))
        chart.setBackgroundRoundness(0)
        chart.setMargins(QMargins(14, 10, 12, 8))
        chart.setAnimationOptions(QChart.NoAnimation)
        chart.legend().hide()

    def _style_chart_axis(self, axis, *, labels_visible: bool = True, compact: bool = False) -> None:
        if hasattr(axis, "setLabelsVisible"):
            axis.setLabelsVisible(labels_visible)
        if hasattr(axis, "setLabelsColor"):
            axis.setLabelsColor(QColor("#9fb2c8"))
        if hasattr(axis, "setGridLineColor"):
            axis.setGridLineColor(QColor("#233140"))
        if hasattr(axis, "setMinorGridLineColor"):
            axis.setMinorGridLineColor(QColor("#17212d"))
        if hasattr(axis, "setMinorGridLineVisible"):
            axis.setMinorGridLineVisible(False)
        if hasattr(axis, "setShadesVisible"):
            axis.setShadesVisible(False)
        if hasattr(axis, "setLinePenColor"):
            axis.setLinePenColor(QColor("#334355"))
        if hasattr(axis, "setLabelsFont"):
            font = QFont("Microsoft YaHei UI", 8 if compact else 9)
            font.setWeight(QFont.Medium)
            axis.setLabelsFont(font)

    def _build_stock_identity_cell(self, row) -> QWidget:
        wrapper = QWidget()
        layout = QVBoxLayout(wrapper)
        layout.setContentsMargins(8, 4, 8, 4)
        layout.setSpacing(2)

        name_label = QLabel(row.stock_name)
        name_label.setStyleSheet("QLabel { color: #f3f5f7; font-weight: 800; font-size: 14px; }")
        meta_label = QLabel(f"{row.stock_id}  |  {row.symbol}  |  热度 {row.heat_score:.1f}")
        meta_label.setStyleSheet("QLabel { color: #8793a6; font-size: 11px; }")

        layout.addWidget(name_label)
        layout.addWidget(meta_label)
        return wrapper

    def _create_metric_card(self, title: str, value: str, accent: str) -> tuple[QFrame, QLabel, QLabel]:
        card = QFrame()
        card.setObjectName("metricCard")
        layout = QVBoxLayout(card)
        layout.setContentsMargins(14, 12, 14, 12)
        layout.setSpacing(4)

        title_label = QLabel(title)
        title_label.setObjectName("metricCaption")
        value_label = QLabel(value)
        value_label.setObjectName("metricValue")
        accent_label = QLabel(accent)
        accent_label.setObjectName("metricAccent")

        layout.addWidget(title_label)
        layout.addWidget(value_label)
        layout.addWidget(accent_label)
        layout.addStretch(1)
        return card, value_label, accent_label

