        if hasattr(self, "strategy_detail_combo") and self.strategy_detail_combo.count() <= 7:
            labels = ["龙头模型", "主力雷达", "擒龙打板", "价值低吸", "尾盘买入法", "一日持股法", "掘龙决策"]
