    if not getattr(self, "scan_rows", []):
        focus_row = self._selected_daily_pool_recommendation() if hasattr(self, "_selected_daily_pool_recommendation") else None
        if focus_row is not None:
            symbol = getattr(focus_row, "symbol", "") or ""
