def _qh_wrap_startup_deferred_refresh_v1(original):
    def wrapped(self: QuantHunterWindow, *args, **kwargs):
        if getattr(self, "_qh_defer_startup_refreshes_v1", False):
            return None
        return original(self, *args, **kwargs)
    return wrapped


