def _qh_apply_overview_hard_theme_v30(self: QuantHunterWindow) -> None:
    def _set(widget, stylesheet: str) -> None:
        if isinstance(widget, QWidget):
            widget.setAttribute(Qt.WA_StyledBackground, True)
            widget.setAutoFillBackground(False)
            widget.setStyleSheet(stylesheet)

    token = _terminal_theme_tokens(str(getattr(self, "current_theme", DEFAULT_TERMINAL_THEME) or DEFAULT_TERMINAL_THEME))
    palette = _build_terminal_palette(str(getattr(self, "current_theme", DEFAULT_TERMINAL_THEME) or DEFAULT_TERMINAL_THEME))

    def _tint(widget) -> None:
        if isinstance(widget, QWidget):
            widget.setPalette(palette)
            widget.setAutoFillBackground(False)

    def _fill_button_row(row_name: str, labels: list[str]) -> None:
        row = self.findChild(QWidget, row_name)
        if row is None:
            return
        buttons = row.findChildren(QPushButton)
        for index, label in enumerate(labels):
            if index >= len(buttons):
                break
            current = (buttons[index].text() or "").strip()
            if current != label:
                self._set_label_text_if_changed(buttons[index], label)

    def _fill_text(widget_name: str, text: str) -> None:
        widget = getattr(self, widget_name, None)
        if isinstance(widget, QTextEdit):
            current = widget.toPlainText().strip()
            if not current or self._has_mojibake_text(current):
                self._set_plain_text_if_changed(widget, text)

    group_style = (
        f"QGroupBox {{ background:qlineargradient(x1:0,y1:0,x2:1,y2:1, stop:0 {token['panel_0']}, stop:1 {token['panel_1']}); "
        f"border:1px solid {token['border']}; border-radius:18px; color:{token['text']}; }} "
        f"QGroupBox::title {{ color:{token['text']}; font-weight:800; }} "
        f"QLabel {{ background:transparent; color:{token['text']}; }}"
    )
    text_panel_style = (
        f"background:{token['panel_2']}; color:{token['text']}; "
        f"border:1px solid {token['border']}; border-radius:16px; padding:12px;"
    )
    input_style = (
        f"background:{token['input_bg']}; color:{token['input_fg']}; "
        f"border:1px solid {token['border']}; border-radius:14px; padding:8px 12px;"
    )
    ghost_button_style = (
        f"background:{token['button_ghost']}; color:{token['text']}; "
        f"border:1px solid {token['border']}; border-radius:12px; padding:0 14px; font-weight:800;"
    )
    tonal_button_style = (
        f"background:{token['button_tonal']}; color:{token['text']}; "
        f"border:1px solid {token['primary']}; border-radius:12px; padding:0 14px; font-weight:800;"
    )
    accent_button_style = (
        f"background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 {token['accent_0']}, stop:1 {token['accent_1']}); "
        f"color:{token['button_accent_text']}; border:1px solid {token['primary']}; border-radius:12px; padding:0 16px; font-weight:800;"
    )

    for name in [
        "overviewViewBox",
        "overviewSearchBox",
        "overviewTagBox",
        "dashboardMetricsBox",
        "cockpitBox",
        "playbookBox",
        "overviewPriorityBox",
        "opportunityPoolBox",
        "leaderboardBox",
        "overviewSummaryBox",
        "themeSummaryBox",
        "capitalBox",
        "decisionBox",
        "buySignalBox",
        "riskSignalBox",
        "breadthSignalBox",
    ]:
        widget = self.findChild(QGroupBox, name)
        _tint(widget)
        _set(widget, group_style)

    for attr_name in ["overviewSidePanel", "overviewCenterPanel", "overviewRightPanel", "overviewLeftNotes", "overviewRightNotes"]:
        widget = self.findChild(QWidget, attr_name)
        _tint(widget)
        _set(widget, "background:transparent;")

    for attr_name, style in [
        ("market_header_label", f"color:{token['text']}; background:transparent; font-size:22px; font-weight:900;"),
        ("market_subheader_label", "color:#d8e3ef; background:transparent; font-size:13px; font-weight:600;"),
        ("market_signal_label", f"color:{token['secondary']}; background:{token['panel_0']}; border:1px solid {token['border']}; border-radius:10px; padding:8px 12px; font-weight:800;"),
        ("market_quote_label", "color:#d7e3ee; background:transparent; font-size:12px; font-weight:600;"),
        ("market_status_label", f"color:{token['text']}; background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 {token['panel_0']}, stop:1 {token['button_ghost']}); border:1px solid {token['border']}; border-left:4px solid {token['primary']}; border-radius:15px; padding:10px 14px; font-weight:800;"),
    ]:
        widget = getattr(self, attr_name, None)
        _tint(widget)
        _set(widget, style)

    for attr_name in [
        "overview_command_text",
        "overview_execution_text",
        "overview_playbook_text",
        "market_buy_text",
        "market_sell_text",
        "market_breadth_text",
        "market_theme_brief_text",
        "market_source_status_text",
        "market_capital_text",
        "market_decision_text",
        "market_leaderboard_text",
    ]:
        widget = getattr(self, attr_name, None)
        _tint(widget)
        _set(widget, text_panel_style)

    for attr_name in ["market_search_input", "market_theme_combo", "market_history_date_combo"]:
        widget = getattr(self, attr_name, None)
        _tint(widget)
        _set(widget, input_style)

    for attr_name in ["market_refresh_button"]:
        widget = getattr(self, attr_name, None)
        _tint(widget)
        _set(widget, accent_button_style)
    for attr_name in ["market_history_reset_button"]:
        widget = getattr(self, attr_name, None)
        _tint(widget)
        _set(widget, ghost_button_style)

    for button_map_name in ["market_filter_buttons", "timeframe_buttons", "history_window_buttons", "market_overlay_buttons", "secondary_indicator_buttons"]:
        button_map = getattr(self, button_map_name, None)
        if isinstance(button_map, dict):
            for button in button_map.values():
                _tint(button)
                role = button.objectName()
                if role == "accentButton":
                    _set(button, accent_button_style)
                elif role == "tonalButton":
                    _set(button, tonal_button_style)
                else:
                    _set(button, ghost_button_style)

    for button in self.findChildren(QPushButton):
        if button.parentWidget() and button.parentWidget().property("actionRow"):
            _tint(button)
            role = button.objectName()
            if role == "accentButton":
                _set(button, accent_button_style)
            elif role == "tonalButton":
                _set(button, tonal_button_style)
            else:
                _set(button, ghost_button_style)

    for button in getattr(self, "overview_tab", QWidget()).findChildren(QPushButton):
        _tint(button)
        role = button.objectName()
        if role == "accentButton":
            _set(button, accent_button_style)
        elif role == "tonalButton":
            _set(button, tonal_button_style)
        else:
            _set(button, ghost_button_style)

    for row_name, labels in _overview_action_row_fallbacks().items():
        _fill_button_row(row_name, labels)

    overview_button_groups = _overview_nav_button_groups()
    for box_name, labels in overview_button_groups.items():
        box = self.findChild(QGroupBox, box_name)
        if box is None:
            continue
        buttons = box.findChildren(QPushButton)
        for index, label in enumerate(labels):
            if index >= len(buttons):
                break
            current = (buttons[index].text() or "").strip()
            if not current or self._has_mojibake_text(current):
                self._set_label_text_if_changed(buttons[index], label)

    _fill_text(
        "overview_command_text",
        "盘前指挥\n\n焦点：等待市场同步\n主线：待确认 | 信号：先观察\n动作：先刷新市场，再确认主线与执行链路。",
    )
    _fill_text(
        "overview_execution_text",
        "执行路径\n\n价格：等待行情同步\n资金：等待行情同步\n下一步：继续观察量能、承接与主线强度。",
    )
    _fill_text(
        "market_capital_text",
        "资金画像\n\n净流入、换手、封单稳定性和承接质量会在刷新市场后同步到这里。",
    )
    _fill_text(
        "market_decision_text",
        "买卖决策\n\n这里会汇总主线地位、趋势状态、消息催化与执行建议，帮助快速判断该不该做。",
    )
    _fill_text(
        "market_theme_brief_text",
        "主线摘要\n\n这里会汇总强势主题、趋势延续、切换预警和主线持续性。",
    )

    widget = getattr(self, "market_pool_table", None)
    _tint(widget)
    _set(widget, f"background:{token['panel_2']}; color:{token['text']}; border:1px solid {token['border']}; border-radius:18px; selection-background-color:{token['selection']}; selection-color:{token['selection_text']};")
    for attr_name in ["intraday_chart_view", "daily_chart_view", "fund_chart_view", "momentum_chart_view", "indicator_chart_view"]:
        widget = getattr(self, attr_name, None)
        _tint(widget)
        _set(widget, f"background:qlineargradient(x1:0,y1:0,x2:1,y2:1, stop:0 {token['shell_bg_0']}, stop:1 {token['shell_bg_1']}); border:1px solid {token['border']}; border-radius:16px;")

    self._qh_overview_hard_theme_applied_v30 = True


def _qh_schedule_overview_hard_theme_v30(self: QuantHunterWindow) -> None:
    if not hasattr(self, "_qh_overview_hard_theme_timer_v30"):
        timer = QTimer(self)
        timer.setSingleShot(True)
        timer.timeout.connect(self._apply_overview_hard_theme_v30)
        self._qh_overview_hard_theme_timer_v30 = timer
    self._qh_overview_hard_theme_timer_v30.start(0)
    QTimer.singleShot(180, self._apply_overview_hard_theme_v30)
    QTimer.singleShot(720, self._apply_overview_hard_theme_v30)


